import bisect

def table_zone_eval(zone, ops):
    # --- Validate Zone ---
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("zone must be a 2-tuple/list")
    initial, transitions = zone
    if not isinstance(initial, int) or isinstance(initial, bool):
        raise ValueError("initial must be int")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be list/tuple")

    trans_ts = []
    trans_offs = []
    prev_t = -float('inf')
    prev_off = initial

    for tr in transitions:
        if not isinstance(tr, (list, tuple)) or len(tr) != 2:
            raise ValueError("transition must be 2-tuple/list")
        t, off = tr
        if not isinstance(t, int) or isinstance(t, bool) or not isinstance(off, int) or isinstance(off, bool):
            raise ValueError("transition items must be int")
        if t < prev_t + 172800:
            raise ValueError("transition t constraints violated")
        if abs(off - prev_off) > 86400:
            raise ValueError("offset change constraint violated")
        trans_ts.append(t)
        trans_offs.append(off)
        prev_t = t
        prev_off = off

    # --- Precompute Structures ---
    gaps = []          # (w_start, w_end, t, a, b)
    later_instants = set()

    prev_off = initial
    for t, off in zip(trans_ts, trans_offs):
        a, b = prev_off, off
        if b > a:
            gaps.append((t + a, t + b, t, a, b))
        elif b < a:
            later_instants.add(t - 1 + a - b)
        prev_off = off

    gap_ws = [g[0] for g in gaps]

    # --- Helpers ---
    def get_offset(x):
        idx = bisect.bisect_right(trans_ts, x)
        return initial if idx == 0 else trans_offs[idx-1]

    def find_matches(w):
        x0 = w - initial
        idx = bisect.bisect_right(trans_ts, x0)
        matches = []

        # Check current interval
        off = trans_offs[idx-1] if idx > 0 else initial
        x_cand = w - off
        lo = trans_ts[idx-1] if idx > 0 else -float('inf')
        hi = trans_ts[idx] if idx < len(trans_ts) else float('inf')
        if lo <= x_cand < hi:
            matches.append(x_cand)

        # Check previous interval (for overlaps)
        if idx > 0:
            off_prev = trans_offs[idx-2] if idx > 1 else initial
            x_cand2 = w - off_prev
            lo2 = trans_ts[idx-2] if idx > 1 else -float('inf')
            hi2 = trans_ts[idx-1]
            if lo2 <= x_cand2 < hi2:
                matches.append(x_cand2)

        matches.sort()
        return matches

    def resolve(w, fold):
        matches = find_matches(w)
        if len(matches) == 1:
            return matches[0]
        elif len(matches) == 2:
            return matches[fold]
        else:
            gi = bisect.bisect_right(gap_ws, w) - 1
            if gi < 0 or gi >= len(gaps):
                raise ValueError("w not in any gap")
            g = gaps[gi]
            return w - g[3] if fold == 0 else w - g[4]

    # --- Process Ops ---
    if not isinstance(ops, (list, tuple)):
        raise ValueError("ops must be list/tuple")

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("op must be list/tuple")
        if not isinstance(op[0], str):
            raise ValueError("op name must be str")

        name = op[0]
        if name == "instant":
            if len(op) != 3: raise ValueError("instant needs 2 args")
            w, fold = op[1], op[2]
            if not isinstance(w, int) or isinstance(w, bool): raise ValueError("w")
            if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1): raise ValueError("fold")
            if abs(w) > 10**13: raise ValueError("w range")
            results.append(resolve(w, fold))

        elif name == "wall":
            if len(op) != 2: raise ValueError("wall needs 1 arg")
            x = op[1]
            if not isinstance(x, int) or isinstance(x, bool): raise ValueError("x")
            if abs(x) > 10**13: raise ValueError("x range")
            off = get_offset(x)
            w = x + off
            f = 1 if x in later_instants else 0
            results.append((w, f))

        elif name == "add":
            if len(op) != 5: raise ValueError("add needs 4 args")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or isinstance(w, bool): raise ValueError("w")
            if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1): raise ValueError("fold")
            if not isinstance(days, int) or isinstance(days, bool): raise ValueError("days")
            if not isinstance(secs, int) or isinstance(secs, bool): raise ValueError("secs")
            if abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6: raise ValueError("range")

            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            off2 = get_offset(x2)
            w2_final = x2 + off2
            f2 = 1 if x2 in later_instants else 0
            results.append((w2_final, f2))

        else:
            raise ValueError("unknown operation")

    return results

import bisect

def table_zone_eval(zone, ops):
    # Validate zone
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("Invalid zone structure")
    initial, transitions = zone
    if isinstance(initial, bool) or not isinstance(initial, int):
        raise ValueError("Initial must be int")
    if abs(initial) > 50400:
        raise ValueError("Initial out of range")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("Transitions must be list or tuple")
    if len(transitions) > 100000:
        raise ValueError("Too many transitions")

    trans_times = []
    trans_offs = []
    prev_t = None
    prev_off = initial

    for tr in transitions:
        if not isinstance(tr, (list, tuple)) or len(tr) != 2:
            raise ValueError("Invalid transition")
        t, off = tr
        if isinstance(t, bool) or not isinstance(t, int):
            raise ValueError("Transition t must be int")
        if isinstance(off, bool) or not isinstance(off, int):
            raise ValueError("Transition off must be int")
        if abs(off) > 50400:
            raise ValueError("Transition offset out of range")
        if abs(t) > 10**13:
            raise ValueError("Transition t out of range")
        if prev_t is not None:
            if t <= prev_t:
                raise ValueError("Transitions not strictly increasing")
            if t - prev_t < 172800:
                raise ValueError("Transition gap too small")
            if abs(off - prev_off) > 86400:
                raise ValueError("Offset change too large")
        prev_t = t
        prev_off = off
        trans_times.append(t)
        trans_offs.append(off)

    # Precompute for fast lookup
    n = len(trans_times)

    def get_offset(x):
        i = bisect.bisect_right(trans_times, x)
        return trans_offs[i-1] if i > 0 else initial

    def resolve(w, fold):
        if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1):
            raise ValueError("fold must be 0 or 1")
        if not isinstance(w, int) or isinstance(w, bool):
            raise ValueError("w must be int")
        if abs(w) > 10**13:
            raise ValueError("w out of range")

        i = bisect.bisect_right(trans_times, w)
        # Check transition i-1
        if i > 0:
            T = trans_times[i-1]
            a = trans_offs[i-2] if i > 1 else initial
            b = trans_offs[i-1]
            if b > a:
                if T + a <= w < T + b:
                    return w - a if fold == 0 else w - b
            elif b < a:
                if T + b <= w < T + a:
                    return w - a if fold == 0 else w - b
        # Not in transition range, offset is constant
        offset = trans_offs[i-1] if i > 0 else initial
        return w - offset

    def wall(x):
        if not isinstance(x, int) or isinstance(x, bool):
            raise ValueError("x must be int")
        if abs(x) > 10**13:
            raise ValueError("x out of range")

        i = bisect.bisect_right(trans_times, x)
        offset = trans_offs[i-1] if i > 0 else initial
        w = x + offset
        f = 0
        if i > 0:
            T = trans_times[i-1]
            a = trans_offs[i-2] if i > 1 else initial
            b = offset
            if b < a and T + b <= w < T + a:
                f = 1
        return (w, f)

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("Operation must be list or tuple")
        if len(op) == 0 or not isinstance(op[0], str):
            raise ValueError("Invalid operation")
        name = op[0]
        if name == "instant":
            if len(op) != 3:
                raise ValueError("Wrong number of items for instant")
            w, fold = op[1], op[2]
            results.append(resolve(w, fold))
        elif name == "wall":
            if len(op) != 2:
                raise ValueError("Wrong number of items for wall")
            x = op[1]
            results.append(wall(x))
        elif name == "add":
            if len(op) != 5:
                raise ValueError("Wrong number of items for add")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("w must be int")
            if abs(w) > 10**13:
                raise ValueError("w out of range")
            if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1):
                raise ValueError("fold must be 0 or 1")
            if not isinstance(days, int) or isinstance(days, bool):
                raise ValueError("days must be int")
            if abs(days) > 10**6:
                raise ValueError("days out of range")
            if not isinstance(secs, int) or isinstance(secs, bool):
                raise ValueError("secs must be int")
            if abs(secs) > 10**13:
                raise ValueError("secs out of range")
            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            results.append(wall(x2))
        else:
            raise ValueError("Unknown operation")

    return results

import bisect

def table_zone_eval(zone, ops):
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("Invalid zone format")
    initial, transitions = zone
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("Invalid transitions")

    # Parse and validate transitions
    N = len(transitions)
    T_list = [0] * N
    Off_list = [0] * N
    for i, tr in enumerate(transitions):
        if not isinstance(tr, (list, tuple)) or len(tr) != 2:
            raise ValueError("Invalid transition entry")
        t, off = tr
        if not isinstance(t, int) or not isinstance(off, int):
            raise ValueError("Transition values must be ints")
        if abs(off) > 50400:
            raise ValueError("Offset out of range")
        if i > 0 and t <= T_list[i-1]:
            raise ValueError("Transitions not strictly increasing")
        if i > 0 and (t - T_list[i-1]) < 172800:
            raise ValueError("Transition gap too small")
        if i > 0 and abs(off - Off_list[i-1]) > 86400:
            raise ValueError("Offset change too large")
        T_list[i] = t
        Off_list[i] = off

    if not isinstance(initial, int):
        raise ValueError("Initial offset must be int")
    if abs(initial) > 50400:
        raise ValueError("Initial offset out of range")

    # Precompute L[i] = T_list[i] + Off_list[i]
    L = [T_list[i] + Off_list[i] for i in range(N)]

    def get_offset(x):
        idx = bisect.bisect_right(T_list, x) - 1
        return Off_list[idx] if idx >= 0 else initial

    def resolve(w, fold):
        if fold not in (0, 1):
            raise ValueError("fold must be 0 or 1")
        if not isinstance(w, int):
            raise ValueError("w must be int")

        idx = bisect.bisect_right(L, w) - 1

        x1 = None
        x2 = None

        if idx == -1:
            if w < T_list[0] + initial:
                x1 = w - initial
            # else 0 matches
        else:
            x1 = w - Off_list[idx]
            end_T = T_list[idx+1] if idx + 1 < N else None

            if x1 < end_T:
                # One match candidate x1
                if idx + 1 < N and Off_list[idx] > Off_list[idx+1] and w >= L[idx+1]:
                    x2 = w - Off_list[idx+1]
                    # Two matches: x2 (earlier), x1 (later)
                else:
                    pass # Only x1
            else:
                # x1 is out of its interval, check gap or 0 matches
                if idx + 1 < N and Off_list[idx] > Off_list[idx+1] and w >= L[idx+1]:
                    x2 = w - Off_list[idx+1]
                    # Two matches
                else:
                    # 0 matches
                    pass

        if x2 is not None:
            # Two matches
            return x2 if fold == 0 else x1
        elif x1 is not None:
            return x1
        else:
            # 0 matches: gap
            # Gap is at transition idx (if idx>0) or initial->T_list[0]
            a = Off_list[idx-1] if idx > 0 else initial
            b = Off_list[idx]
            return w - a if fold == 0 else w - b

    def wall_of(x):
        if not isinstance(x, int):
            raise ValueError("x must be int")
        off = get_offset(x)
        w = x + off
        # Determine fold flag
        idx = bisect.bisect_right(L, x + off) - 1
        # x is the later match iff it falls in the ambiguous region of a fold transition
        # Ambiguous region for transition idx (from a to b, a>b): x in [T_list[idx], T_list[idx] + a - b)
        a = Off_list[idx-1] if idx > 0 else initial
        b = Off_list[idx]
        f = 0
        if idx + 1 < N and a > b:
            if x < T_list[idx] + (a - b):
                f = 1
        return (w, f)

    def add_op(w, fold, days, secs):
        if not isinstance(days, int) or not isinstance(secs, int):
            raise ValueError("days and secs must be ints")
        w2 = w + 86400 * days
        x1 = resolve(w2, fold)
        x2 = x1 + secs
        return wall_of(x2)

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("Invalid operation")
        name = op[0]
        if not isinstance(name, str):
            raise ValueError("Operation name must be string")

        if name == "instant":
            if len(op) != 3:
                raise ValueError("Wrong number of items for instant")
            w, fold = op[1], op[2]
            results.append(resolve(w, fold))
        elif name == "wall":
            if len(op) != 2:
                raise ValueError("Wrong number of items for wall")
            x = op[1]
            results.append(wall_of(x))
        elif name == "add":
            if len(op) != 5:
                raise ValueError("Wrong number of items for add")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            results.append(add_op(w, fold, days, secs))
        else:
            raise ValueError("Unknown operation")

    return results

import bisect

def table_zone_eval(zone, ops):
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("Invalid zone format")

    initial, transitions = zone
    if not isinstance(initial, int) or not isinstance(transitions, (list, tuple)):
        raise ValueError("Invalid zone components")
    if abs(initial) > 50400:
        raise ValueError("Initial offset out of range")

    n = len(transitions)
    if n > 100000:
        raise ValueError("Too many transitions")

    trans_t = []
    trans_off = []
    prev_t = -float('inf')
    prev_off = initial

    for i, tr in enumerate(transitions):
        if not isinstance(tr, (list, tuple)) or len(tr) != 2:
            raise ValueError("Invalid transition format")
        t, off = tr
        if not isinstance(t, int) or not isinstance(off, int):
            raise ValueError("Transition values must be ints")
        if abs(off) > 50400:
            raise ValueError("Transition offset out of range")
        if t <= prev_t:
            raise ValueError("Transitions not strictly increasing")
        if t - prev_t < 172800:
            raise ValueError("Transitions too close")
        if abs(off - prev_off) > 86400:
            raise ValueError("Offset change too large")

        trans_t.append(t)
        trans_off.append(off)
        prev_t, prev_off = t, off

    wall_starts = [t + o for t, o in zip(trans_t, trans_off)]

    def get_offset(x):
        idx = bisect.bisect_right(trans_t, x) - 1
        if idx < 0:
            return initial
        return trans_off[idx]

    def get_wall(x):
        return x + get_offset(x)

    def resolve(w, fold):
        if fold not in (0, 1):
            raise ValueError("fold must be 0 or 1")

        idx = bisect.bisect_right(wall_starts, w) - 1

        # Check first interval
        if idx < 0:
            x = w - initial
            if x < trans_t[0]:
                return x
            else:
                # Gap before first transition
                a, b = initial, trans_off[0]
                if fold == 0:
                    return w - a
                else:
                    return w - b

        # Check interval idx
        t_i = trans_t[idx]
        off_i = trans_off[idx]
        t_next = trans_t[idx + 1] if idx + 1 < n else float('inf')
        off_next = trans_off[idx + 1] if idx + 1 < n else 0

        # Wall range for interval idx: [t_i + off_i, t_next + off_i)
        if w < t_next + off_i:
            x = w - off_i
            return x
        else:
            # Gap after interval idx
            a, b = off_i, off_next
            if fold == 0:
                return w - a
            else:
                return w - b

    def resolve_wall(x):
        w = get_wall(x)
        # Check if x is the later of two matches
        if x > 0 and get_wall(x - 1) == w:
            return (w, 1)
        return (w, 0)

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("Invalid operation format")
        if len(op) == 0:
            raise ValueError("Empty operation")

        name = op[0]
        if not isinstance(name, str):
            raise ValueError("Operation name must be a string")

        if name == "instant":
            if len(op) != 3:
                raise ValueError("Wrong number of items for instant")
            w, fold = op[1], op[2]
            if not isinstance(w, int) or not isinstance(fold, int):
                raise ValueError("instant arguments must be ints")
            if abs(w) > 10**13:
                raise ValueError("w out of range")
            if fold not in (0, 1):
                raise ValueError("fold must be 0 or 1")
            results.append(resolve(w, fold))

        elif name == "wall":
            if len(op) != 2:
                raise ValueError("Wrong number of items for wall")
            x = op[1]
            if not isinstance(x, int):
                raise ValueError("wall argument must be int")
            if abs(x) > 10**13:
                raise ValueError("x out of range")
            results.append(resolve_wall(x))

        elif name == "add":
            if len(op) != 5:
                raise ValueError("Wrong number of items for add")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or not isinstance(fold, int) or not isinstance(days, int) or not isinstance(secs, int):
                raise ValueError("add arguments must be ints")
            if abs(w) > 10**13 or abs(secs) > 10**13:
                raise ValueError("w or secs out of range")
            if abs(days) > 10**6:
                raise ValueError("days out of range")
            if fold not in (0, 1):
                raise ValueError("fold must be 0 or 1")

            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            results.append(resolve_wall(x2))

        else:
            raise ValueError("Unknown operation name")

    return results

import bisect

def table_zone_eval(zone, ops):
    # Validate zone structure
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("Invalid zone")
    initial, transitions = zone
    if not isinstance(initial, int) or isinstance(initial, bool):
        raise ValueError("Invalid initial offset")
    if abs(initial) > 50400:
        raise ValueError("Initial offset out of range")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("Invalid transitions")
    if len(transitions) > 100000:
        raise ValueError("Too many transitions")

    T_list = []
    off_list = []
    prev_offs = [initial]

    for i, t_off in enumerate(transitions):
        if not isinstance(t_off, (list, tuple)) or len(t_off) != 2:
            raise ValueError("Invalid transition entry")
        t, off = t_off
        if not isinstance(t, int) or isinstance(t, bool):
            raise ValueError("Invalid transition time")
        if not isinstance(off, int) or isinstance(off, bool):
            raise ValueError("Invalid transition offset")
        if abs(off) > 50400:
            raise ValueError("Transition offset out of range")
        if i > 0:
            if t <= T_list[-1]:
                raise ValueError("Transitions not strictly increasing")
            if t - T_list[-1] < 172800:
                raise ValueError("Transitions too close")
            if abs(off - prev_offs[-1]) > 86400:
                raise ValueError("Offset change too large")
        T_list.append(t)
        off_list.append(off)
        if i < len(transitions) - 1:
            prev_offs.append(off)

    # Helper to get offset at instant x
    def get_offset(x):
        idx = bisect.bisect_right(T_list, x)
        if idx == 0:
            return initial
        return off_list[idx-1]

    results = []

    for op in ops:
        if not isinstance(op, (list, tuple)) or len(op) < 2:
            raise ValueError("Invalid operation")
        cmd = op[0]
        if not isinstance(cmd, str):
            raise ValueError("Invalid command type")

        if cmd == "instant":
            if len(op) != 3:
                raise ValueError("Wrong number of items")
            w, fold = op[1], op[2]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("Invalid w")
            if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1):
                raise ValueError("Invalid fold")
            if abs(w) > 10**13:
                raise ValueError("w out of range")

            idx = bisect.bisect_right(T_list, w)
            found = False
            for i in [idx-1, idx]:
                if 0 <= i < len(transitions):
                    T = T_list[i]
                    a = prev_offs[i]
                    b = off_list[i]
                    if b > a: # gap
                        if T + a <= w < T + b:
                            results.append(w - (a if fold == 0 else b))
                            found = True
                            break
                    elif b < a: # overlap
                        if T + b <= w < T + a:
                            results.append(w - (a if fold == 0 else b))
                            found = True
                            break
            if not found:
                off = get_offset(w)
                results.append(w - off)

        elif cmd == "wall":
            if len(op) != 2:
                raise ValueError("Wrong number of items")
            x = op[1]
            if not isinstance(x, int) or isinstance(x, bool):
                raise ValueError("Invalid x")
            if abs(x) > 10**13:
                raise ValueError("x out of range")

            off = get_offset(x)
            w = x + off
            is_later = False
            idx = bisect.bisect_right(T_list, x)
            for i in [idx-1, idx]:
                if 0 <= i < len(transitions):
                    T = T_list[i]
                    a = prev_offs[i]
                    b = off_list[i]
                    if b < a: # overlap
                        if T <= x < T + a - b:
                            is_later = True
                            break
            results.append((w, 1 if is_later else 0))

        elif cmd == "add":
            if len(op) != 5:
                raise ValueError("Wrong number of items")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("Invalid w")
            if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1):
                raise ValueError("Invalid fold")
            if not isinstance(days, int) or isinstance(days, bool):
                raise ValueError("Invalid days")
            if not isinstance(secs, int) or isinstance(secs, bool):
                raise ValueError("Invalid secs")
            if abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6:
                raise ValueError("Out of range")

            w2 = w + 86400 * days
            idx2 = bisect.bisect_right(T_list, w2)
            x1 = None
            for i in [idx2-1, idx2]:
                if 0 <= i < len(transitions):
                    T = T_list[i]
                    a = prev_offs[i]
                    b = off_list[i]
                    if b > a: # gap
                        if T + a <= w2 < T + b:
                            x1 = w2 - (a if fold == 0 else b)
                            break
                    elif b < a: # overlap
                        if T + b <= w2 < T + a:
                            x1 = w2 - (a if fold == 0 else b)
                            break
            if x1 is None:
                off2 = get_offset(w2)
                x1 = w2 - off2

            x2 = x1 + secs
            off_x2 = get_offset(x2)
            w_x2 = x2 + off_x2
            is_later = False
            idx3 = bisect.bisect_right(T_list, x2)
            for i in [idx3-1, idx3]:
                if 0 <= i < len(transitions):
                    T = T_list[i]
                    a = prev_offs[i]
                    b = off_list[i]
                    if b < a: # overlap
                        if T <= x2 < T + a - b:
                            is_later = True
                            break
            results.append((w_x2, 1 if is_later else 0))

        else:
            raise ValueError("Unknown operation")

    return results

import bisect

def table_zone_eval(zone, ops):
    # --- Validation ---
    def is_int(v):
        return type(v) is int and not isinstance(v, bool)

    def check_zone():
        if not isinstance(zone, (list, tuple)) or len(zone) != 2:
            raise ValueError("zone must be a list/tuple of length 2")
        initial, transitions = zone
        if not is_int(initial) or abs(initial) > 50400:
            raise ValueError("initial offset invalid")
        if not isinstance(transitions, (list, tuple)):
            raise ValueError("transitions must be a list/tuple")
        if len(transitions) > 100000:
            raise ValueError("too many transitions")

        prev_t = -float('inf')
        prev_off = initial
        instants = []
        offsets = [initial]

        for t, off in transitions:
            if not isinstance((t, off), (list, tuple)) or len((t, off)) != 2:
                raise ValueError("transition must be a list/tuple of 2 ints")
            if not (is_int(t) and is_int(off)):
                raise ValueError("transition values must be ints")
            if abs(off) > 50400 or abs(t) > 10**13:
                raise ValueError("transition value out of range")
            if t - prev_t < 172800:
                raise ValueError("transition instants too close")
            if abs(off - prev_off) > 86400:
                raise ValueError("offset change too large")
            instants.append(t)
            offsets.append(off)
            prev_t = t
            prev_off = off

        # Precompute wall_end for fast resolve
        # wall_end[i] is the wall time at the start of interval i+1
        # interval i covers [instants[i-1], instants[i]) with offset offsets[i]
        # wall_end[i] = instants[i] + offsets[i]
        N = len(instants)
        wall_end = [instants[i] + offsets[i] for i in range(N)] + [float('inf')]
        return instants, offsets, wall_end, N

    instants, offsets, wall_end, N = check_zone()

    def resolve(w, fold):
        k = bisect.bisect_right(wall_end, w)
        i = k - 1
        matches = []

        # Check interval i
        if i >= 0:
            x = w - offsets[i]
            low = instants[i-1] if i > 0 else -float('inf')
            high = instants[i] if i < N else float('inf')
            if low <= x < high:
                matches.append(x)

        # Check interval i-1 (handles overlaps)
        if i > 0:
            x = w - offsets[i-1]
            low = instants[i-2] if i > 1 else -float('inf')
            high = instants[i-1]
            if low <= x < high:
                matches.append(x)

        if len(matches) == 0:
            # Gap: offset rises from a to b at instants[i-1]
            a = offsets[i-1]
            b = offsets[i]
            return w - a if fold == 0 else w - b

        matches.sort()
        return matches[fold]

    def get_wall(x):
        idx = bisect.bisect_right(instants, x) - 1
        off = offsets[idx]
        w = x + off
        f = 0
        # Check if x is the later match (overlap with previous interval)
        if idx > 0:
            x_prev = w - offsets[idx-1]
            if instants[idx-1] <= x_prev < instants[idx] and x_prev < x:
                f = 1
        return (w, f)

    # --- Ops Validation & Execution ---
    if not isinstance(ops, (list, tuple)):
        raise ValueError("ops must be a list/tuple")

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)) or len(op) < 1:
            raise ValueError("each op must be a list/tuple")
        name = op[0]
        if not isinstance(name, str):
            raise ValueError("op name must be a string")

        if name == "instant":
            if len(op) != 3:
                raise ValueError("instant op needs 3 items")
            w, fold = op[1], op[2]
            if not is_int(w) or abs(w) > 10**13:
                raise ValueError("instant w out of range")
            if not is_int(fold) or fold not in (0, 1):
                raise ValueError("fold must be 0 or 1")
            results.append(resolve(w, fold))

        elif name == "wall":
            if len(op) != 2:
                raise ValueError("wall op needs 2 items")
            x = op[1]
            if not is_int(x) or abs(x) > 10**13:
                raise ValueError("wall x out of range")
            results.append(get_wall(x))

        elif name == "add":
            if len(op) != 5:
                raise ValueError("add op needs 5 items")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not is_int(w) or abs(w) > 10**13:
                raise ValueError("add w out of range")
            if not is_int(fold) or fold not in (0, 1):
                raise ValueError("add fold must be 0 or 1")
            if not is_int(days) or abs(days) > 10**6:
                raise ValueError("add days out of range")
            if not is_int(secs) or abs(secs) > 10**13:
                raise ValueError("add secs out of range")
            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            results.append(get_wall(x2))

        else:
            raise ValueError("unknown operation")

    return results

