def petri_starts(places, transitions, until, limit):
    # --- Validation ---

    # Validate places
    if not isinstance(places, dict):
        raise ValueError("places must be a dict")
    for k, v in places.items():
        if not isinstance(k, str) or not k:
            raise ValueError("place name must be a non-empty string")
        if isinstance(v, bool) or not isinstance(v, int):
            raise ValueError("place token count must be an int")
        if not (0 <= v <= 10**6):
            raise ValueError("place token count out of range")

    # Validate transitions
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be a list or tuple")
    if len(transitions) > 50:
        raise ValueError("too many transitions")

    seen_names = set()
    parsed_transitions = []

    for t in transitions:
        if not isinstance(t, tuple) or len(t) != 6:
            raise ValueError("each transition must be a tuple of 6 elements")

        name, inputs, outputs, duration, priority, servers = t

        # Name
        if not isinstance(name, str) or not name:
            raise ValueError("transition name must be a non-empty string")
        if name in seen_names:
            raise ValueError("duplicate transition name")
        seen_names.add(name)

        # Inputs
        if not isinstance(inputs, dict) or not inputs:
            raise ValueError("inputs must be a non-empty dict")
        for p, w in inputs.items():
            if p not in places:
                raise ValueError(f"unknown place {p} in inputs")
            if isinstance(w, bool) or not isinstance(w, int):
                raise ValueError("input weight must be an int")
            if not (1 <= w <= 1000):
                raise ValueError("input weight out of range")

        # Outputs
        if not isinstance(outputs, dict):
            raise ValueError("outputs must be a dict")
        for p, w in outputs.items():
            if p not in places:
                raise ValueError(f"unknown place {p} in outputs")
            if isinstance(w, bool) or not isinstance(w, int):
                raise ValueError("output weight must be an int")
            if not (1 <= w <= 1000):
                raise ValueError("output weight out of range")

        # Duration
        if isinstance(duration, bool) or not isinstance(duration, int):
            raise ValueError("duration must be an int")
        if not (0 <= duration <= 10**12):
            raise ValueError("duration out of range")

        # Priority
        if isinstance(priority, bool) or not isinstance(priority, int):
            raise ValueError("priority must be an int")

        # Servers
        if isinstance(servers, bool) or not isinstance(servers, int):
            raise ValueError("servers must be an int")
        if not (1 <= servers <= 10**6):
            raise ValueError("servers out of range")

        parsed_transitions.append((name, inputs, outputs, duration, priority, servers))

    # Validate until and limit
    if isinstance(until, bool) or not isinstance(until, int):
        raise ValueError("until must be an int")
    if not (0 <= until <= 10**12):
        raise ValueError("until out of range")

    if isinstance(limit, bool) or not isinstance(limit, int):
        raise ValueError("limit must be an int")
    if not (1 <= limit <= 2000):
        raise ValueError("limit out of range")

    # --- Simulation ---

    # State
    tokens = dict(places)
    active_counts = [0] * len(parsed_transitions)
    heap = []  # min-heap of (completion_time, transition_index)
    result = []
    current_time = 0

    # Helper to check if transition is enabled
    def is_enabled(idx):
        t = parsed_transitions[idx]
        inputs = t[1]
        servers = t[5]

        # Server constraint
        if active_counts[idx] >= servers:
            return False

        # Token constraint
        for p, w in inputs.items():
            if tokens[p] < w:
                return False
        return True

    while True:
        if len(result) >= limit:
            break

        # If current time is beyond until, we cannot start anything new
        if current_time > until:
            break

        # Check if we need to advance time
        # We only advance time if there are active firings and the next completion is > current_time
        if heap:
            next_time = heap[0][0]
            if next_time > current_time:
                # If the next event is strictly in the future
                if next_time > until:
                    # We cannot advance time to process completions, 
                    # but we might still be able to start transitions at current_time?
                    # However, if next_time > until, and current_time <= until,
                    # we can still start transitions at current_time.
                    # But if we start a transition with duration > 0, it will complete at > until.
                    # That's allowed.
                    # But we cannot process completions at next_time.
                    # So we just proceed to start phase at current_time.
                    pass 
                else:
                    # Advance time
                    current_time = next_time
                    # Process completions at current_time
                    while heap and heap[0][0] <= current_time:
                        comp_time, t_idx = heapq.heappop(heap)
                        active_counts[t_idx] -= 1
                        t = parsed_transitions[t_idx]
                        for p, w in t[2].items():
                            tokens[p] += w

        # Start phase: repeatedly enable transitions
        started_any = True
        while started_any and len(result) < limit:
            started_any = False

            # Find all enabled transitions
            candidates = []
            for i in range(len(parsed_transitions)):
                if is_enabled(i):
                    t = parsed_transitions[i]
                    candidates.append((t[4], i)) # (priority, index)

            if not candidates:
                started_any = False
                break

            # Sort by priority, then index
            candidates.sort()
            best_priority, best_idx = candidates[0]

            # Fire transition
            t = parsed_transitions[best_idx]
            result.append((current_time, t[0]))

            # Consume inputs
            for p, w in t[1].items():
                tokens[p] -= w

            # Handle duration
            if t[3] > 0:
                active_counts[best_idx] += 1
                heapq.heappush(heap, (current_time + t[3], best_idx))
            else:
                # Duration 0: outputs immediately, no server usage
                for p, w in t[2].items():
                    tokens[p] += w
                # active_counts not incremented

    return result

