            raise ValueError("inputs must be a non-empty dict")
        for p, w in inputs.items():
            if p not in places:
                raise ValueError(f"unknown place {p} in inputs")
            if isinstance(w, bool) or not isinstance(w, int):
                raise ValueError("input weight must be an int")
            if not (1 <= w <= 1000):
                raise ValueError("input weight out of range")

        if not isinstance(outputs, dict):
            raise ValueError("outputs must be a dict")
        for p, w in outputs.items():
            if p not in places:
                raise ValueError(f"unknown place {p} in outputs")
            if isinstance(w, bool) or not isinstance(w, int):
                raise ValueError("output weight must be an int")
            if not (1 <= w <= 1000):
                raise ValueError("output weight out of range")

        if isinstance(duration, bool) or not isinstance(duration, int):
            raise ValueError("duration must be an int")
        if not (0 <= duration <= 10**12):
            raise ValueError("duration out of range")

        if isinstance(priority, bool) or not isinstance(priority, int):
            raise ValueError("priority must be an int")

        if isinstance(servers, bool) or not isinstance(servers, int):
            raise ValueError("servers must be an int")
        if not (1 <= servers <= 10**6):
            raise ValueError("servers out of range")

        parsed_transitions.append((name, inputs, outputs, duration, priority, servers))

    if isinstance(until, bool) or not isinstance(until, int):
        raise ValueError("until must be an int")
    if not (0 <= until <= 10**12):
        raise ValueError("until out of range")

    if isinstance(limit, bool) or not isinstance(limit, int):
        raise ValueError("limit must be an int")
    if not (1 <= limit <= 2000):
        raise ValueError("limit out of range")

    # --- Simulation ---

    tokens = dict(places)
    active_counts = [0] * len(parsed_transitions)
    heap = []  # min-heap of (completion_time, transition_index)
    result = []
    current_time = 0

    # Unpack for faster access in the simulation loop
    t_names = [t[0] for t in parsed_transitions]
    t_inputs = [t[1] for t in parsed_transitions]
    t_outputs = [t[2] for t in parsed_transitions]
    t_durations = [t[3] for t in parsed_transitions]
    t_priorities = [t[4] for t in parsed_transitions]
    t_servers = [t[5] for t in parsed_transitions]

    num_trans = len(parsed_transitions)

    while len(result) < limit:
        # 1. Process completions at current_time
        while heap and heap[0][0] == current_time:
            comp_time, idx = heapq.heappop(heap)
            active_counts[idx] -= 1
            for p, w in t_outputs[idx].items():
                tokens[p] += w

        # 2. Repeatedly start enabled transitions
        started_any = True
        while started_any and len(result) < limit:
            started_any = False

            best_idx = -1
            best_priority = float('inf')

            for i in range(num_trans):
                # Check server limit
                if active_counts[i] >= t_servers[i]:
                    continue

                # Check token constraints
                enabled = True
                for p, w in t_inputs[i].items():
                    if tokens[p] < w:
                        enabled = False
                        break

                if not enabled:
                    continue

                pri = t_priorities[i]
                # Pick smallest priority, ties go to smaller index
                if pri < best_priority or (pri == best_priority and (best_idx == -1 or i < best_idx)):
                    best_priority = pri
                    best_idx = i

            if best_idx != -1:
                started_any = True
                result.append((current_time, t_names[best_idx]))

                # Consume inputs
                for p, w in t_inputs[best_idx].items():
                    tokens[p] -= w

                dur = t_durations[best_idx]
                if dur > 0:
                    active_counts[best_idx] += 1
                    heapq.heappush(heap, (current_time + dur, best_idx))
                else:
                    # Duration 0: outputs immediately, never counts as in-progress
                    for p, w in t_outputs[best_idx].items():
                        tokens[p] += w
            else:
                started_any = False

        # 3. Advance time or stop
        if not heap:
            # No firings in progress
            break

        next_time = heap[0][0]
        if next_time > until:
            # Next instant is beyond until, stop immediately
            break

        current_time = next_time

    return result

def gate_trace(gates, stimuli, watch, until):
    # Validation
    if not isinstance(until, int) or isinstance(until, bool) or until < 0 or until > 10**12:
        raise ValueError("until")
    if not isinstance(gates, (list, tuple)) or len(gates) > 60:
        raise ValueError("gates")
    if not isinstance(stimuli, (list, tuple)) or len(stimuli) > 200:
        raise ValueError("stimuli")
    if not isinstance(watch, (list, tuple)):
        raise ValueError("watch")

    ALLOWED_OPS = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}
    OPS_IN = {"NOT": 1, "BUF": 1, "AND": (2,4), "OR": (2,4), "XOR": (2,4), "NAND": (2,4), "NOR": (2,4)}

    outs = set()
    gates_list = []
    all_signals = set()

    for g in gates:
        if not isinstance(g, tuple) or len(g) != 4: raise ValueError
        out, op, ins, delay = g
        if not isinstance(out, str) or not out: raise ValueError
        if op not in ALLOWED_OPS: raise ValueError
        if not isinstance(ins, (list, tuple)): raise ValueError
        req = OPS_IN[op]
        if isinstance(req, int):
            if len(ins) != req: raise ValueError
        else:
            if not (req[0] <= len(ins) <= req[1]): raise ValueError
        if not isinstance(delay, int) or isinstance(delay, bool) or delay < 0 or delay > 10**12: raise ValueError
        if out in outs: raise ValueError
        outs.add(out)
        for i in ins:
            if not isinstance(i, str) or not i: raise ValueError
        gates_list.append((out, op, ins, delay))

    for out, op, ins, delay in gates_list:
        all_signals.add(out)
        for i in ins: all_signals.add(i)

    for _, sig, val in stimuli:
        if not isinstance(sig, str) or not sig: raise ValueError
        if not isinstance(val, int) or isinstance(val, bool) or val not in (0, 1): raise ValueError
        if sig not in all_signals: raise ValueError
        if sig in outs: raise ValueError
        all_signals.add(sig)

    for w in watch:
        if not isinstance(w, str) or not w: raise ValueError
        if w not in all_signals: raise ValueError

    # Cycle detection (Kahn's)
    in_deg = {s: 0 for s in all_signals}
    adj = {s: [] for s in all_signals}
    for out, op, ins, delay in gates_list:
        for i in ins:
            adj[i].append(out)
            in_deg[out] += 1
    q = [s for s in all_signals if in_deg[s] == 0]
    cnt = 0
    while q:
        u = q.pop(0)
        cnt += 1
        for v in adj[u]:
            in_deg[v] -= 1
            if in_deg[v] == 0:
                q.append(v)
    if cnt != len(all_signals):
        raise ValueError("Cycle")

    # Simulation setup
    FUNC = {
        "AND": lambda x: 1 if all(x) else 0,
        "OR": lambda x: 1 if any(x) else 0,
        "XOR": lambda x: 1 if sum(x) % 2 else 0,
        "NAND": lambda x: 1 - (1 if all(x) else 0),
        "NOR": lambda x: 1 - (1 if any(x) else 0),
        "NOT": lambda x: 1 - x[0],
        "BUF": lambda x: x[0]
    }

    gmap = {}
    by_input = {s: [] for s in all_signals}
    for out, op, ins, delay in gates_list:
        gmap[out] = (op, ins, delay, FUNC[op])
        for i in ins:
            by_input[i].append(out)

    cur_val = {s: 0 for s in all_signals}
    pending = {}
    prev_final = {s: 0 for s in all_signals}
    trace = {w: [] for w in watch}

    stim_map = {}
    for t, sig, val in stimuli:
        stim_map.setdefault(t, []).append((sig, val))

    import heapq
    heap = [0]
    seen_inst = set()

    while heap:
        t = heapq.heappop(heap)
        if t > until: break
        if t in seen_inst: continue
        seen_inst.add(t)

        round_num = 0
        while True:
            round_num += 1
            changed = set()

            # Batch
            if round_num == 1 and t in stim_map:
                for sig, val in stim_map[t]:
                    if cur_val[sig] != val:
                        cur_val[sig] = val
                        changed.add(sig)

            # Apply pending due at t
            due_now = [(out, val) for out, (val, due) in list(pending.items()) if due == t]
            for out, val in due_now:
                del pending[out]
                if cur_val[out] != val:
                    cur_val[out] = val
                    changed.add(out)

            # Evaluate
            gates_to_eval = set()
            if t == 0 and round_num == 1:
                gates_to_eval = set(gmap.keys())
            else:
                for sig in changed:
                    if sig in by_input:
                        gates_to_eval.update(by_input[sig])

            new_due_at_t = False
            for out in gates_to_eval:
                op, ins, delay, func = gmap[out]
                if out in pending:
                    del pending[out]

                new_val = func([cur_val[i] for i in ins])
                if new_val != cur_val[out]:
                    due_time = t + delay
                    pending[out] = (new_val, due_time)
                    if due_time == t:
                        new_due_at_t = True
                    elif due_time <= until and due_time not in seen_inst:
                        heapq.heappush(heap, due_time)

            if not new_due_at_t:
                break

        # Record trace
        for w in watch:
            if cur_val[w] != prev_final[w]:
                trace[w].append((t, cur_val[w]))
        prev_final = dict(cur_val)

    return trace

