        elif op == "XOR":
            res = 0
            for v in vals:
                res ^= v
        elif op == "NAND":
            res = 1
            for v in vals:
                res &= v
            res = 1 - res
        elif op == "NOR":
            res = 0
            for v in vals:
                res |= v
            res = 1 - res
        elif op == "NOT":
            res = 1 - vals[0]
        elif op == "BUF":
            res = vals[0]
        else:
            res = 0 # Should not happen

