        for out_name, val in assignments_due:
            if signal_values[out_name] != val:
                changed_signals.add(out_name)
            signal_values[out_name] = val

        # 2. Evaluate
        # "Every gate with an input that changed in this round ... computes"
        # "In the first round of instant 0: every gate"
        evaluate_all = (t == 0)

        gates_to_eval = []
        if evaluate_all:
            gates_to_eval = list(gate_map.keys())
        else:
            for out_name, g in gate_map.items():
                for inp in g["ins"]:
                    if inp in changed_signals:
                        gates_to_eval.append(out_name)
