            new_val = evaluate_gate(out_name)
            current_val = signal_values[out_name]

            if new_val != current_val:
                due_time = t + gate_map[out_name]["delay"]
                if due_time <= until:
                    # Queue new assignment
                    # If delay is 0, it's due at t
                    pending[out_name] = (due_time, new_val)
                    if due_time == t:
                        new_pending_t.append((out_name, new_val))
                    else:
                        add_time(due_time)

        # 3. Later Rounds
        # "Rounds continue while some assignment is due at t."
        # "In the later rounds apply the assignments due at t (queued by the previous round with delay 0)."

        while new_pending_t:
            # Apply assignments due at t
            # Note: new_pending_t contains (out_name, val)
            # We apply them and track changes relative to start of this round?
            # Text: "A signal 'changed' in the round if its value after the batch differs from before it."
            # "Before it" for later rounds means before this round started.

            # Snapshot before this round
            values_before_round = {s: signal_values[s] for s in all_signals}

            for out_name, val in new_pending_t:
                if signal_values[out_name] != val:
                    changed_signals.add(out_name)
                signal_values[out_name] = val

            # Clear new_pending_t for next iteration
            current_new_pending = new_pending_t
            new_pending_t = []

            # Evaluate
            # "Every gate with an input that changed in this round"
            gates_to_eval = []
            for out_name, g in gate_map.items():
                for inp in g["ins"]:
                    if inp in changed_signals:
                        gates_to_eval.append(out_name)
                        break

            for out_name in gates_to_eval:
                if out_name in pending:
                    del pending[out_name]

                new_val = evaluate_gate(out_name)
                current_val = signal_values[out_name]

                if new_val != current_val:
                    due_time = t + gate_map[out_name]["delay"]
                    if due_time <= until:
                        pending[out_name] = (due_time, new_val)
                        if due_time == t:
                            new_pending_t.append((out_name, new_val))
                        else:
                            add_time(due_time)

        # 4. Record Trace
        # "Trace of a watched signal has (t, v) for each instant t whose final value v ... differs from the final value at the previous simulated instant"
        for w in watch:
            val = signal_values[w]
            if val != last_watched_value[w]:
                trace[w].append((t, val))
                last_watched_value[w] = val

    return trace

