                if out_name in pending:
                    del pending[out_name]

                new_val = evaluate_gate(out_name)
                if new_val != signal_values[out_name]:
                    due_time = t + gate_map[out_name]["delay"]
                    if due_time <= until:
                        pending[out_name] = (due_time, new_val)
