import heapq

def gate_trace(gates, stimuli, watch, until):
    # --- Validation & Parsing ---

    def is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    # Validate gates
    if not isinstance(gates, (list, tuple)):
        raise ValueError("gates must be a list or tuple")

    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}
    gate_map = {} # out -> {op, ins, delay, ins_list}
    outs = set()
    known_signals = set()
    graph = {} # adjacency list for cycle detection: input_signal -> [output_signals]

    for item in gates:
        if not isinstance(item, (list, tuple)) or len(item) != 4:
            raise ValueError("Each gate must be a tuple of 4 elements")
        out, op, ins, delay = item

        if not isinstance(out, str) or not out:
            raise ValueError("Gate out must be a non-empty string")
        if out in outs:
            raise ValueError("Duplicate gate output name")
        if op not in valid_ops:
            raise ValueError(f"Invalid operation {op}")
        if not isinstance(ins, (list, tuple)):
            raise ValueError("Gate inputs must be a list or tuple")
        for i in ins:
            if not isinstance(i, str) or not i:
                raise ValueError("Gate input names must be non-empty strings")
        if not isinstance(delay, int) or isinstance(delay, bool):
            raise ValueError("Gate delay must be an integer")
        if delay < 0 or delay > 10**12:
            raise ValueError("Gate delay out of range")

        # Check input counts
        if op in ("NOT", "BUF"):
            if len(ins) != 1:
                raise ValueError(f"{op} gate requires exactly 1 input")
        else:
            if len(ins) < 2 or len(ins) > 4:
                raise ValueError(f"{op} gate requires 2 to 4 inputs")

        outs.add(out)
        known_signals.update(ins)
        known_signals.add(out)

        # Build graph for cycle detection
        if out not in graph:
            graph[out] = []
        for inp in ins:
            if inp not in graph:
                graph[inp] = []
            graph[inp].append(out)

        gate_map[out] = {"op": op, "ins": list(ins), "delay": delay}

    # Cycle detection (DFS)
    # Nodes are signals. Edges: input -> output.
    # We need to check if the graph formed by signal dependencies has cycles.
    # A gate reading its own out is a cycle. Also chains.
    # We can use Kahn's algorithm or DFS.
    # Nodes involved: all signals in known_signals.
    # But edges are only defined if there's a gate.
    # Actually, the graph is: for each gate (out, ins), edges u->out for u in ins.

    in_degree = {s: 0 for s in known_signals}
    adj = {s: [] for s in known_signals}

    for out_name, g in gate_map.items():
        for inp in g["ins"]:
            adj[inp].append(out_name)
            in_degree[out_name] += 1

    queue = [s for s in known_signals if in_degree[s] == 0]
    visited_count = 0
    while queue:
        u = queue.pop(0)
        visited_count += 1
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if visited_count != len(known_signals):
        raise ValueError("Cycle detected in gate connections")

    # Validate stimuli
    primary_inputs = known_signals - outs
    if not isinstance(stimuli, (list, tuple)):
        raise ValueError("stimuli must be a list or tuple")

    processed_stimuli = []
    for item in stimuli:
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError("Each stimulus must be a tuple of 3 elements")
        time, signal, value = item

        if not isinstance(time, int) or isinstance(time, bool):
            raise ValueError("Stimulus time must be an integer")
        if time < 0 or time > 10**12:
            raise ValueError("Stimulus time out of range")
        if not isinstance(signal, str) or not signal:
            raise ValueError("Stimulus signal must be a non-empty string")
        if signal not in primary_inputs:
            raise ValueError(f"Stimulus signal '{signal}' is not a primary input")
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("Stimulus value must be an integer")
        if value not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")
        processed_stimuli.append((time, signal, value))

    # Validate watch
    if not isinstance(watch, (list, tuple)):
        raise ValueError("watch must be a list or tuple")
    watch_set = set()
    for w in watch:
        if not isinstance(w, str) or not w:
            raise ValueError("Watch names must be non-empty strings")
        if w not in known_signals:
            raise ValueError(f"Watch signal '{w}' is unknown")
        watch_set.add(w)

    # Validate until
    if not isinstance(until, int) or isinstance(until, bool):
        raise ValueError("until must be an integer")
    if until < 0 or until > 10**12:
        raise ValueError("until out of range")

    # --- Simulation Setup ---

    current_value = {s: 0 for s in known_signals}
    pending_assignments = {} # out -> (value, due_time)

