            for s in known_signals:
                if current_value[s] != values_before_round[s]:
                    changed_signals.add(s)

            first_round = False

            # 2. Evaluate Gates
            # Determine which gates to evaluate
            gates_to_eval = []

            if t == 0:
                # All gates evaluated in first round of instant 0
                gates_to_eval = list(gate_map.keys())
            else:
                # Gates with inputs that changed
                for out_name, g in gate_map.items():
                    if any(inp in changed_signals for inp in g["ins"]):
                        gates_to_eval.append(out_name)

            # Cancel pending assignments for gates being evaluated
            for out_name in gates_to_eval:
                if out_name in pending_assignments:
                    del pending_assignments[out_name]

            # Compute new values and schedule
            for out_name in gates_to_eval:
                g = gate_map[out_name]
                op = g["op"]
                ins = g["ins"]
                delay = g["delay"]

                # Compute value
                if op == "AND":
                    val = 1
                    for inp in ins:
                        if current_value[inp] == 0:
