        gate_map[out] = (op, list(ins), delay)

    if not isinstance(stimuli, (list, tuple)):
        raise ValueError("stimuli must be a list or tuple")
    if len(stimuli) > 200:
        raise ValueError("Too many stimuli")

    primary_inputs = all_signal_names - gate_outputs
    stimuli_by_time = {}

    for s in stimuli:
        if not isinstance(s, (list, tuple)) or len(s) != 3:
            raise ValueError("Each stimulus must be a tuple/list of 3 elements")
        time, signal, value = s

        if not is_int_not_bool(time):
            raise ValueError("Stimulus time must be an integer (not bool)")
        if time < 0 or time > 10**12:
            raise ValueError("Stimulus time out of range")

        if not isinstance(signal, str):
            raise ValueError("Stimulus signal must be a string")
        if signal not in all_signal_names:
            raise ValueError(f"Unknown stimulus signal: {signal}")
        if signal in gate_outputs:
            raise ValueError(f"Stimulus signal '{signal}' is driven by a gate")

        if not is_int_not_bool(value):
            raise ValueError("Stimulus value must be an integer (not bool)")
        if value not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")

        if time not in stimuli_by_time:
            stimuli_by_time[time] = []
        stimuli_by_time[time].append((signal, value))

    if not isinstance(watch, (list, tuple)):
        raise ValueError("watch must be a list or tuple")

    for w in watch:
        if not isinstance(w, str):
            raise ValueError("Watch names must be strings")
        if w not in all_signal_names:
            raise ValueError(f"Unknown watch signal: {w}")

    if not is_int_not_bool(until):
        raise ValueError("until must be an integer (not bool)")
    if until < 0 or until > 10**12:
        raise ValueError("until out of range")

    # Check for cycles
    adj = {name: [] for name in all_signal_names}
    for out, (op, ins, delay) in gate_map.items():
        for inp in ins:
            adj[inp].append(out)

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {name: WHITE for name in all_signal_names}

    def has_cycle(u):
        color[u] = GRAY
        for v in adj[u]:
            if color[v] == GRAY:
                return True
            if color[v] == WHITE and has_cycle(v):
                return True
        color[u] = BLACK
        return False

    for name in all_signal_names:
        if color[name] == WHITE:
            if has_cycle(name):
                raise ValueError("Cycle detected in gate graph")

    # --- Simulation Setup ---
    signals = {name: 0 for name in all_signal_names}
    pending = {}

    import heapq
    times_heap = []
    if 0 <= until:
        heapq.heappush(times_heap, 0)
    for t in stimuli_by_time:
        if t <= until:
            heapq.heappush(times_heap, t)

    trace = {w: [] for w in watch}
    last_values = {w: 0 for w in watch}

    last_processed_t = -1

    while times_heap:
        t = heapq.heappop(times_heap)
        if t <= last_processed_t:
            continue
        last_processed_t = t
        if t > until:
            break

        changed_signals = set()

        # Round 1 Batch: Stimuli then Pending Assignments
        if t in stimuli_by_time:
            for sig, val in stimuli_by_time[t]:
                if signals[sig] != val:
                    signals[sig] = val
                    changed_signals.add(sig)

        assignments_due_t = []
        for out_name, (due_time, val) in list(pending.items()):
            if due_time == t:
                assignments_due_t.append((out_name, val))
                del pending[out_name]

        for out_name, val in assignments_due_t:
            if signals[out_name] != val:
                signals[out_name] = val
                changed_signals.add(out_name)

        # Evaluate Gates
        gates_to_eval = []
        if t == 0:
            gates_to_eval = list(gate_map.keys())
        else:
            for out_name in gate_map:
                op, ins, delay = gate_map[out_name]
                if any(inp in changed_signals for inp in ins):
                    gates_to_eval.append(out_name)

        new_pending_times = set()

        for out_name in gates_to_eval:
            op, ins, delay = gate_map[out_name]
            if out_name in pending:
                del pending[out_name]

            input_vals = [signals[inp] for inp in ins]

            if op == "AND":
                new_val = 1 if all(input_vals) else 0
            elif op == "OR":
                new_val = 1 if any(input_vals) else 0
            elif op == "XOR":
                new_val = sum(input_vals) % 2
            elif op == "NAND":
                new_val = 0 if all(input_vals) else 1
            elif op == "NOR":
                new_val = 1 if not any(input_vals) else 0
            elif op == "NOT":
                new_val = 1 - input_vals[0]
            elif op == "BUF":
                new_val = input_vals[0]
            else:
                new_val = 0

            if new_val != signals[out_name]:
                due_time = t + delay
                if due_time <= until:
                    pending[out_name] = (due_time, new_val)
                    if due_time == t:
                        new_pending_times.add(t)
                    else:
                        heapq.heappush(times_heap, due_time)

        # Delta Rounds Loop
        while new_pending_times:
            assignments_due_t_round2 = []
            for out_name, (due_time, val) in list(pending.items()):
                if due_time == t:
                    assignments_due_t_round2.append((out_name, val))
                    del pending[out_name]

            round_changed_signals = set()
            for out_name, val in assignments_due_t_round2:
                if signals[out_name] != val:
                    signals[out_name] = val
                    round_changed_signals.add(out_name)

            gates_to_eval_round2 = []
            for out_name in gate_map:
                op, ins, delay = gate_map[out_name]
                if any(inp in round_changed_signals for inp in ins):
                    gates_to_eval_round2.append(out_name)

            new_pending_times = set()
            for out_name in gates_to_eval_round2:
                op, ins, delay = gate_map[out_name]
                if out_name in pending:
                    del pending[out_name]

                input_vals = [signals[inp] for inp in ins]
                if op == "AND": new_val = 1 if all(input_vals) else 0
                elif op == "OR": new_val = 1 if any(input_vals) else 0
                elif op == "XOR": new_val = sum(input_vals) % 2
                elif op == "NAND": new_val = 0 if all(input_vals) else 1
                elif op == "NOR": new_val = 1 if not any(input_vals) else 0
                elif op == "NOT": new_val = 1 - input_vals[0]
                elif op == "BUF": new_val = input_vals[0]
                else: new_val = 0

                if new_val != signals[out_name]:
                    due_time = t + delay
                    if due_time <= until:
                        pending[out_name] = (due_time, new_val)
                        if due_time == t:
                            new_pending_times.add(t)
                        else:
                            heapq.heappush(times_heap, due_time)

            if not new_pending_times:
                break

        # Record trace
        for w in watch:
            curr = signals[w]
            if curr != last_values[w]:
                trace[w].append((t, curr))
                last_values[w] = curr

    return trace

