class Type:
    __slots__ = ('name', 'args')
    def __init__(self, name, args=()):
        self.name = name
        self.args = tuple(args)
    def __eq__(self, other):
        return isinstance(other, Type) and self.name == other.name and self.args == other.args
    def __hash__(self):
        return hash((self.name, self.args))

def is_var(t): return isinstance(t, Type) and t.name.startswith('t')
def is_func(t): return isinstance(t, Type) and t.name == '->'
def is_list(t): return isinstance(t, Type) and t.name == 'List'
def is_ref(t): return isinstance(t, Type) and t.name == 'Ref'

def apply(t, subs):
    if is_var(t):
        res = subs.get(t.name)
        return res if res is not None else t
    return Type(t.name, tuple(apply(a, subs) for a in t.args))

def occurs(var, t, subs):
    t = apply(t, subs)
    if is_var(t): return t.name == var
    return any(occurs(var, a, subs) for a in t.args)

def bind(var, t, subs):
    if occurs(var, t, subs): raise ValueError("Infinite type")
    return {var: t} | subs

def unify(t1, t2, subs):
    t1 = apply(t1, subs)
    t2 = apply(t2, subs)
    if t1 == t2: return subs
    if is_var(t1): return bind(t1.name, t2, subs)
    if is_var(t2): return bind(t2.name, t1, subs)
    if is_func(t1) and is_func(t2):
        if len(t1.args) != len(t2.args): raise ValueError("Type mismatch")
        for a1, a2 in zip(t1.args, t2.args):
            subs = unify(a1, a2, subs)
        return subs
    raise ValueError("Type mismatch")

def free_vars(t, subs):
    t = apply(t, subs)
    if is_var(t): return {t.name}
    return set().union(*(free_vars(a, subs) for a in t.args))

def is_value(term):
    tag = term[0]
    if tag in ('int', 'bool', 'str', 'unit', 'var', 'fn', 'nil'):
        return True
    if tag == 'cons':
        return is_value(term[1]) and is_value(term[2])
    return False

def validate(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed tag")

    if tag == 'int':
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
            raise ValueError("Malformed int")
    elif tag == 'bool':
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed bool")
    elif tag == 'str':
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed str")
    elif tag == 'unit':
        if len(term) != 1:
            raise ValueError("Malformed unit")
    elif tag == 'var':
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed var")
    elif tag == 'fn':
        if len(term) != 3:
            raise ValueError("Malformed fn")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("Malformed fn params")
        if not isinstance(body, tuple):
            raise ValueError("Malformed fn body")
        for p in params:
            if not isinstance(p, str) or not p or p in params[:params.index(p)]:
                raise ValueError("Malformed fn params")
    elif tag == 'call':
        if len(term) != 3:
            raise ValueError("Malformed call")
        f, args = term[1], term[2]
        if not isinstance(f, tuple) or not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("Malformed call")
        for a in args:
            if not isinstance(a, tuple):
                raise ValueError("Malformed call args")
    elif tag == 'let':
        if len(term) != 4:
            raise ValueError("Malformed let")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name or not isinstance(e1, tuple) or not isinstance(e2, tuple):
            raise ValueError("Malformed let")
    elif tag == 'letrec':
        if len(term) != 4:
            raise ValueError("Malformed letrec")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name or not isinstance(e1, tuple) or not isinstance(e2, tuple):
            raise ValueError("Malformed letrec")
    elif tag == 'nil':
        if len(term) != 1:
            raise ValueError("Malformed nil")
    elif tag == 'cons':
        if len(term) != 3:
            raise ValueError("Malformed cons")
        h, t = term[1], term[2]
        if not isinstance(h, tuple) or not isinstance(t, tuple):
            raise ValueError("Malformed cons")
    elif tag == 'match':
        if len(term) != 5:
            raise ValueError("Malformed match")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not isinstance(s, tuple) or not isinstance(e_nil, tuple) or not isinstance(e_cons, tuple):
            raise ValueError("Malformed match")
        if not isinstance(hn, str) or not isinstance(tn, str) or not hn or not tn or hn == tn:
            raise ValueError("Malformed match names")
    elif tag == 'ref':
        if len(term) != 2 or not isinstance(term[1], tuple):
            raise ValueError("Malformed ref")
    elif tag == 'get':
        if len(term) != 2 or not isinstance(term[1], tuple):
            raise ValueError("Malformed get")
    elif tag == 'set':
        if len(term) != 3:
            raise ValueError("Malformed set")
        r, e = term[1], term[2]
        if not isinstance(r, tuple) or not isinstance(e, tuple):
            raise ValueError("Malformed set")
    else:
        raise ValueError("Unknown tag")

def weak_infer(term):
    validate(term)

    env = {
        'plus': Type('->', (Type('Int'), Type('Int'), Type('Int'))),
        'eq': Type('->', (Type('t0'), Type('t0'), Type('Bool'))),
        'size': Type('->', (Type('Str'), Type('Int')))
    }
    subs = {}
    tv_counter = [0]
    poly_vars = set()

    def fresh():
        tv_counter[0] += 1
        return Type(f"t{tv_counter[0]}")

    def infer(term, env, subs, poly_vars):
        tag = term[0]
        if tag == 'int': return Type('Int')
        if tag == 'bool': return Type('Bool')
        if tag == 'str': return Type('Str')
        if tag == 'unit': return Type('Unit')
        if tag == 'var':
            name = term[1]
            if name not in env: raise ValueError("Unbound variable")
            return apply(env[name], subs)
        if tag == 'fn':
            _, params, body = term
            new_env = env.copy()
            for p in params:
                new_env[p] = fresh()
            t_body = infer(body, new_env, subs, poly_vars)
            t_fn = Type('->', tuple(new_env[p] for p in params) + (t_body,))
            return t_fn
        if tag == 'call':
            _, f, args = term
            t_f = infer(f, env, subs, poly_vars)
            t_args = [infer(a, env, subs, poly_vars) for a in args]
            t_res = fresh()
            t_fn = Type('->', tuple(t_args) + (t_res,))
            subs = unify(t_f, t_fn, subs)
            return apply(t_res, subs)
        if tag == 'nil':
            return Type('List', (fresh(),))
        if tag == 'cons':
            _, h, t = term
            t_h = infer(h, env, subs, poly_vars)
            t_t = infer(t, env, subs, poly_vars)
            t_list = Type('List', (fresh(),))
            subs = unify(t_t, t_list, subs)
            subs = unify(t_t, Type('List', (t_h,)), subs)
            return apply(t_t, subs)
        if tag == 'match':
            _, s, e_nil, hn, tn, e_cons = term
            t_s = infer(s, env, subs, poly_vars)
            t_A = fresh()
            t_list_A = Type('List', (t_A,))
            subs = unify(t_s, t_list_A, subs)
            new_env = env.copy()
            new_env[hn] = apply(t_A, subs)
            new_env[tn] = apply(t_list_A, subs)
            t_nil = infer(e_nil, new_env, subs, poly_vars)
            t_cons = infer(e_cons, new_env, subs, poly_vars)
            subs = unify(t_nil, t_cons, subs)
            return apply(t_nil, subs)
        if tag == 'ref':
            _, e = term
            t_e = infer(e, env, subs, poly_vars)
            return Type('Ref', (t_e,))
        if tag == 'get':
            _, r = term
            t_r = infer(r, env, subs, poly_vars)
            t_content = fresh()
            subs = unify(t_r, Type('Ref', (t_content,)), subs)
            return apply(t_content, subs)
        if tag == 'set':
            _, r, e = term
            t_r = infer(r, env, subs, poly_vars)
            t_e = infer(e, env, subs, poly_vars)
            t_content = fresh()
            subs = unify(t_r, Type('Ref', (t_content,)), subs)
            return Type('Unit')
        if tag == 'let':
            _, name, e1, e2 = term
            t1 = infer(e1, env, subs, poly_vars)
            if is_value(term):
                gen = free_vars(t1, subs) - free_vars(env, subs)
            else:
                gen = set()
                poly_vars |= free_vars(t1, subs)
            new_env = env.copy()
            new_env[name] = t1
            return infer(e2, new_env, subs, poly_vars)
        if tag == 'letrec':
            _, name, e1, e2 = term
            if e1[0] != 'fn': raise ValueError("letrec requires fn")
            new_env = env.copy()
            t_name = fresh()
            new_env[name] = t_name
            t1 = infer(e1, new_env, subs, poly_vars)
            gen = free_vars(t1, subs) - free_vars(env, subs)
            poly_vars |= gen
            new_env2 = env.copy()
            new_env2[name] = t1
            return infer(e2, new_env2, subs, poly_vars)
        raise ValueError("Unknown tag in infer")

    final_type = infer(term, env, subs, poly_vars)
    final_type = apply(final_type, subs)

    seen = {}
    counter = [1]
    def fmt(t):
        if is_var(t):
            if t.name not in seen:
                seen[t.name] = f"t{counter[0]}"
                counter[0] += 1
            return seen[t.name]
        if t.name == 'List':
            return f"List[{fmt(t.args[0])}]"
        if t.name == 'Ref':
            return f"Ref[{fmt(t.args[0])}]"
        if t.name == '->':
            args = t.args
            n = len(args) - 1
            P = args[:-1]
            R = args[-1]
            if n == 1:
                p_str = fmt(P[0])
                if is_func(P[0]): p_str = f"({p_str})"
                return f"{p_str} -> {fmt(R)}"
            else:
                p_strs = [fmt(p) for p in P]
                return f"({', '.join(p_strs)}) -> {fmt(R)}"
        return t.name

    return fmt(final_type)

