                new_env[p] = Scheme(fresh(), set())
            t_body, subs = infer(body, new_env, subs)
            t_fn = Type('->', tuple(new_env[p].type for p in params) + (t_body,))
            return t_fn, subs
        if tag == 'call':
            _, f, args = term
            t_f, subs = infer(f, env, subs)
            t_args = []
            for a in args:
                t_a, subs = infer(a, env, subs)
                t_args.append(t_a)
            t_res = fresh()
            t_fn = Type('->', tuple(t_args) + (t_res,))
            subs = unify(t_f, t_fn, subs)
            return apply(t_res, subs), subs
        if tag == 'nil':
            return Type('List', (fresh(),)), subs
        if tag == 'cons':
            _, h, t = term
            t_h, subs = infer(h, env, subs)
            t_t, subs = infer(t, env, subs)
            t_list = Type('List', (fresh(),))
            subs = unify(t_t, t_list, subs)
            subs = unify(t_t, Type('List', (t_h,)), subs)
            return apply(t_t, subs), subs
        if tag == 'match':
            _, s, e_nil, hn, tn, e_cons = term
            t_s, subs = infer(s, env, subs)
            t_A = fresh()
            t_list_A = Type('List', (t_A,))
            subs = unify(t_s, t_list_A, subs)
            new_env = env.copy()
            new_env[hn] = Scheme(apply(t_A, subs), set())
            new_env[tn] = Scheme(apply(t_list_A, subs), set())
            t_nil, subs = infer(e_nil, new_env, subs)
            t_cons, subs = infer(e_cons, new_env, subs)
            subs = unify(t_nil, t_cons, subs)
            return apply(t_nil, subs), subs
        if tag == 'ref':
            _, e = term
            t_e, subs = infer(e, env, subs)
            return Type('Ref', (t_e,)), subs
        if tag == 'get':
            _, r = term
            t_r, subs = infer(r, env, subs)
            t_content = fresh()
            subs = unify(t_r, Type('Ref', (t_content,)), subs)
            return apply(t_content, subs), subs
        if tag == 'set':
            _, r, e = term
            t_r, subs = infer(r, env, subs)
            t_e, subs = infer(e, env, subs)
            t_content = fresh()
            subs = unify(t_r, Type('Ref', (t_content,)), subs)
            subs = unify(t_e, apply(t_content, subs), subs)
            return Type('Unit'), subs
        if tag == 'let':
            _, name, e1, e2 = term
            t1, subs = infer(e1, env, subs)
            if is_value(e1):
                scheme = generalize(t1, env)
            else:
                scheme = Scheme(t1, set())
            new_env = env.copy()
            new_env[name] = scheme
            return infer(e2, new_env, subs)
        if tag == 'letrec':
            _, name, e1, e2 = term
            if e1[0] != 'fn': raise ValueError("letrec requires fn")
            t_name = fresh()
            new_env = env.copy()
            new_env[name] = Scheme(t_name, set())
            t1, subs = infer(e1, new_env, subs)
            subs = unify(t_name, t1, subs)
            t1 = apply(t1, subs)
            scheme = generalize(t1, env)
            new_env2 = env.copy()
            new_env2[name] = scheme
            return infer(e2, new_env2, subs)
        raise ValueError("Unknown tag in infer")

    final_type, subs = infer(term, env, subs)
    final_type = apply(final_type, subs)

    seen = {}
    counter = [1]
    def fmt(t):
        if is_var(t):
            if t.name not in seen:
                seen[t.name] = f"t{counter[0]}"
                counter[0] += 1
            return seen[t.name]
        if t.name == 'List':
            return f"List<{fmt(t.args[0])}>"
        if t.name == 'Ref':
            return f"Ref<{fmt(t.args[0])}>"
        if t.name == '->':
            args = t.args
            n = len(args) - 1
            P = args[:-1]
            R = args[-1]
            if n == 1:
                p_str = fmt(P[0])
                if is_var(P[0]) or (isinstance(P[0], Type) and P[0].name == '->'):
                    p_str = f"({p_str})"
                return f"{p_str} -> {fmt(R)}"
            else:
                p_strs = [fmt(p) for p in P]
                return f"({', '.join(p_strs)}) -> {fmt(R)}"
        return t.name

    return fmt(final_type)

