    v_eq = fresh()
    env[0]["plus"] = TFunc((TCon("Int"), TCon("Int")), TCon("Int"))
    env[0]["eq"] = TForall((v_eq,), TFunc((v_eq, v_eq), TCon("Bool")))
    env[0]["size"] = TFunc((TCon("Str"),), TCon("Int"))

