            env.append({name: v_name})
            t1 = infer(e1)
            unify(v_name, t1)
            t1 = apply_subst(t1)
            env_vars = set()
            for d in old_env:
                for t in d.values():
                    env_vars.update(free_vars(t))
            to_quantify = free_vars(t1) - env_vars
            t1_gen = TForall(tuple(to_quantify), t1) if to_quantify else t1
            env[-1][name] = t1_gen
            t2 = infer(e2)
            env.pop()
            return t2
        if tag == "nil":
            return TCon("List", (fresh(),))
        if tag == "cons":
            h, t_val = t[1], t[2]
            th = infer(h)
            tt = infer(t_val)
            a = fresh()
            unify(tt, TCon("List", (a,)))
            unify(th, a)
            return tt
        if tag == "match":
            s, e_nil, hn, tn, e_cons = t[1], t[2], t[3], t[4], t[5]
            ts = infer(s)
            a = fresh()
            unify(ts, TCon("List", (a,)))
            env.append({hn: a, tn: TCon("List", (a,))})
            t_nil = infer(e_nil)
            t_cons = infer(e_cons)
            unify(t_nil, t_cons)
            env.pop()
            return t_nil
        if tag == "ref":
            te = infer(t[1])
            return TCon("Ref", (te,))
        if tag == "get":
            tr = infer(t[1])
            te = fresh()
            unify(tr, TCon("Ref", (te,)))
            return te
        if tag == "set":
            r, e = t[1], t[2]
            tr = infer(r)
            te = infer(e)
            unify(tr, TCon("Ref", (te,)))
            return TCon("Unit")
        raise ValueError("unknown tag")

    final_type = apply_subst(infer(term))

    order = []
    seen = set()
    def collect(T):
        if isinstance(T, TVar):
            if T.rid not in seen:
                seen.add(T.rid)
                order.append(T)
        elif isinstance(T, TCon):
            for a in T.args: collect(a)
        elif isinstance(T, TFunc):
            for a in T.args: collect(a)
            collect(T.ret)
        elif isinstance(T, TForall):
            collect(T.body)
    collect(final_type)

    var_map = {t.rid: f"t{i+1}" for i, t in enumerate(order)}

    def fmt(T):
        if isinstance(T, TVar):
            return var_map[T.rid]
        if isinstance(T, TCon):
            if T.name == "List":
                return f"List<{fmt(T.args[0])}>"
            if T.name == "Ref":
                return f"Ref<{fmt(T.args[0])}>"
            return T.name
        if isinstance(T, TFunc):
            args_strs = [fmt(a) for a in T.args]
            ret_str = fmt(T.ret)
            if len(args_strs) == 1:
                p = args_strs[0]
                if isinstance(T.args[0], TFunc):
                    return f"({p}) -> {ret_str}"
                return f"{p} -> {ret_str}"
            else:
                return f"({', '.join(args_strs)}) -> {ret_str}"
        return "?"

    return fmt(final_type)

class TVar:
    def __init__(self, rid):
        self.rid = rid
class TCon:
    def __init__(self, name, args=()):
        self.name = name
        self.args = tuple(args)
class TFunc:
    def __init__(self, args, ret):
        self.args = tuple(args)
        self.ret = ret
class TForall:
    def __init__(self, vars, body):
        self.vars = vars
        self.body = body

def weak_infer(term):
