    env = [{}]
    v_eq = fresh()
    env[0]["plus"] = TFunc((TCon("Int"), TCon("Int")), TCon("Int"))
    env[0]["eq"] = TForall((v_eq,), TFunc((v_eq, v_eq), TCon("Bool")))
    env[0]["size"] = TFunc((TCon("Str"),), TCon("Int"))

    subst = {}

    def apply_subst(T):
        if isinstance(T, TVar):
            v = subst.get(T)
            if v is not None: return apply_subst(v)
            return T
        elif isinstance(T, TCon):
            return TCon(T.name, tuple(apply_subst(a) for a in T.args))
        elif isinstance(T, TFunc):
            return TFunc(tuple(apply_subst(a) for a in T.args), apply_subst(T.ret))
        elif isinstance(T, TForall):
            return TForall(T.vars, apply_subst(T.body))
        return T

    def instantiate(T, mapping):
