            return mapping.get(T, T)
        elif isinstance(T, TCon):
            return TCon(T.name, tuple(instantiate(a, mapping) for a in T.args))
        elif isinstance(T, TFunc):
            return TFunc(tuple(instantiate(a, mapping) for a in T.args), instantiate(T.ret, mapping))
        elif isinstance(T, TForall):
            return TForall(T.vars, instantiate(T.body, mapping))
        return T

    def occurs(v, T):
