        if isinstance(T, TCon): return any(occurs(v, a) for a in T.args)
        if isinstance(T, TFunc): return any(occurs(v, a) for a in T.args) or occurs(v, T.ret)
        return False

    def unify(t1, t2):
        t1, t2 = apply_subst(t1), apply_subst(t2)
        if isinstance(t1, TVar) and isinstance(t2, TVar) and t1.rid == t2.rid: return
        if isinstance(t1, TVar):
            if occurs(t1, t2): raise ValueError("infinite type")
            subst[t1] = t2
        elif isinstance(t2, TVar):
            if occurs(t2, t1): raise ValueError("infinite type")
            subst[t2] = t1
        elif isinstance(t1, TCon) and isinstance(t2, TCon):
            if t1.name != t2.name or len(t1.args) != len(t2.args): raise ValueError("type mismatch")
            for a, b in zip(t1.args, t2.args): unify(a, b)
        elif isinstance(t1, TFunc) and isinstance(t2, TFunc):
