            te = infer(t[1])
            return TCon("Ref", (te,))
        if tag == "get":
            tr = infer(t[1])
            te = fresh()
            unify(tr, TCon("Ref", (te,)))
            return te
        if tag == "set":
            r, e = t[1], t[2]
            tr = infer(r)
            te = infer(e)
            unify(tr, TCon("Ref", (te,)))
