            if len(t) != 2 or not isinstance(t[1], int) or isinstance(t[1], bool): raise ValueError("malformed")
        elif tag == "bool":
            if len(t) != 2 or not isinstance(t[1], bool): raise ValueError("malformed")
        elif tag == "str":
            if len(t) != 2 or not isinstance(t[1], str): raise ValueError("malformed")
        elif tag == "unit":
            if len(t) != 1: raise ValueError("malformed")
        elif tag == "var":
            if len(t) != 2 or not isinstance(t[1], str) or not t[1]: raise ValueError("malformed")
        elif tag == "fn":
            if len(t) != 3: raise ValueError("malformed")
            params, body = t[1], t[2]
            if not isinstance(params, tuple) or len(params) == 0: raise ValueError("malformed")
            if len(set(params)) != len(params): raise ValueError("malformed")
            if not all(isinstance(p, str) and p for p in params): raise ValueError("malformed")
            validate(body)
        elif tag == "call":
            if len(t) != 3: raise ValueError("malformed")
            f, args = t[1], t[2]
            if not isinstance(args, tuple) or len(args) == 0: raise ValueError("malformed")
            validate(f)
            for a in args: validate(a)
        elif tag == "let":
            if len(t) != 4: raise ValueError("malformed")
            name, e1, e2 = t[1], t[2], t[3]
            if not isinstance(name, str) or not name: raise ValueError("malformed")
            validate(e1); validate(e2)
        elif tag == "letrec":
            if len(t) != 4: raise ValueError("malformed")
            name, e1, e2 = t[1], t[2], t[3]
            if not isinstance(name, str) or not name: raise ValueError("malformed")
            validate(e1); validate(e2)
        elif tag == "nil":
            if len(t) != 1: raise ValueError("malformed")
        elif tag == "cons":
            if len(t) != 3: raise ValueError("malformed")
            validate(t[1]); validate(t[2])
        elif tag == "match":
            if len(t) != 6: raise ValueError("malformed")
            s, e_nil, hn, tn, e_cons = t[1], t[2], t[3], t[4], t[5]
            if not isinstance(hn, str) or not hn or not isinstance(tn, str) or not tn: raise ValueError("malformed")
            if hn == tn: raise ValueError("malformed")
            validate(s); validate(e_nil); validate(e_cons)
        elif tag == "ref":
            if len(t) != 2: raise ValueError("malformed")
            validate(t[1])
        elif tag == "get":
            if len(t) != 2: raise ValueError("malformed")
            validate(t[1])
        elif tag == "set":
            if len(t) != 3: raise ValueError("malformed")
            validate(t[1]); validate(t[2])
        else:
            raise ValueError("malformed")

    validate(term)

    # --- State ---
    subst = {}
    next_id = [0]
    env = []  # List of dicts mapping name -> Type

    def fresh():
        v = TVar(next_id[0])
        next_id[0] += 1
