    def is_value(t):
        tag = t[0]
        if tag in ("int", "bool", "str", "unit", "var"): return True
        if tag == "fn": return True
        if tag == "nil": return True
        if tag == "cons":
            h, tr = t[1], t[2]
            return is_value(h) and is_value(tr)
        return False

    def infer(t):
        tag = t[0]
