            name, e1, e2 = t[1], t[2], t[3]
            if not isinstance(e1, tuple) or e1[0] != "fn":
                raise ValueError("letrec requires fn")
            params, body = e1[1], e1[2]
            ptypes = [fresh() for _ in params]
            env.append({name: FuncT(ptypes, fresh())}) # Placeholder for recursion
            ret = infer(body)
            env[-1][name] = FuncT(ptypes, ret)
