    class UnitT: pass
    class ListT:
        def __init__(self, elem): self.elem = elem
    class RefT:
        def __init__(self, content): self.content = content
    class FuncT:
        def __init__(self, params, ret): self.params = params; self.ret = ret

    # --- Malformation Validation ---
    def validate(t):
        if not isinstance(t, tuple) or len(t) == 0:
            raise ValueError("malformed")
        tag = t[0]
        if not isinstance(tag, str):
            raise ValueError("malformed")
        if tag == "int":
            if len(t) != 2 or not isinstance(t[1], int) or isinstance(t[1], bool): raise ValueError("malformed")
        elif tag == "bool":
            if len(t) != 2 or not isinstance(t[1], bool): raise ValueError("malformed")
        elif tag == "str":
            if len(t) != 2 or not isinstance(t[1], str): raise ValueError("malformed")
        elif tag == "unit":
            if len(t) != 1: raise ValueError("malformed")
        elif tag == "var":
            if len(t) != 2 or not isinstance(t[1], str) or not t[1]: raise ValueError("malformed")
        elif tag == "fn":
            if len(t) != 3: raise ValueError("malformed")
            params, body = t[1], t[2]
            if not isinstance(params, tuple) or len(params) == 0: raise ValueError("malformed")
            if len(set(params)) != len(params): raise ValueError("malformed")
            if not all(isinstance(p, str) and p for p in params): raise ValueError("malformed")
            validate(body)
        elif tag == "call":
            if len(t) != 3: raise ValueError("malformed")
            f, args = t[1], t[2]
            if not isinstance(args, tuple) or len(args) == 0: raise ValueError("malformed")
            validate(f)
            for a in args: validate(a)
        elif tag == "let":
            if len(t) != 4: raise ValueError("malformed")
            name, e1, e2 = t[1], t[2], t[3]
            if not isinstance(name, str) or not name: raise ValueError("malformed")
            validate(e1); validate(e2)
        elif tag == "letrec":
            if len(t) != 4: raise ValueError("malformed")
            name, e1, e2 = t[1], t[2], t[3]
            if not isinstance(name, str) or not name: raise ValueError("malformed")
            validate(e1); validate(e2)
        elif tag == "nil":
            if len(t) != 1: raise ValueError("malformed")
        elif tag == "cons":
            if len(t) != 3: raise ValueError("malformed")
            validate(t[1]); validate(t[2])
        elif tag == "match":
            if len(t) != 6: raise ValueError("malformed")
            s, e_nil, hn, tn, e_cons = t[1], t[2], t[3], t[4], t[5]
            if not isinstance(hn, str) or not hn or not isinstance(tn, str) or not tn: raise ValueError("malformed")
            if hn == tn: raise ValueError("malformed")
            validate(s); validate(e_nil); validate(e_cons)
        elif tag == "ref":
            if len(t) != 2: raise ValueError("malformed")
            validate(t[1])
        elif tag == "get":
            if len(t) != 2: raise ValueError("malformed")
            validate(t[1])
        elif tag == "set":
            if len(t) != 3: raise ValueError("malformed")
            validate(t[1]); validate(t[2])
        else:
            raise ValueError("malformed")

    validate(term)

    # --- State ---
    subst = {}
    next_id = [0]
    env = []

    def fresh():
        v = TVar(next_id[0])
        next_id[0] += 1
        return v

    def apply_subst(t):
        if isinstance(t, TVar):
            while t in subst:
                t = subst[t]
            return t
        if isinstance(t, FuncT):
            return FuncT([apply_subst(p) for p in t.params], apply_subst(t.ret))
        if isinstance(t, ListT):
            return ListT(apply_subst(t.elem))
        if isinstance(t, RefT):
            return RefT(apply_subst(t.content))
        return t

    def occurs(v, t, s):
        if isinstance(t, TVar):
            if t == v: return True
            return occurs(v, s[t], s) if t in s else False
        if isinstance(t, FuncT):
            return any(occurs(v, p, s) for p in t.params) or occurs(v, t.ret, s)
        if isinstance(t, ListT):
            return occurs(v, t.elem, s)
        if isinstance(t, RefT):
            return occurs(v, t.content, s)
        return False

    def unify(t1, t2):
        t1 = apply_subst(t1)
        t2 = apply_subst(t2)
        if t1 == t2: return
        if isinstance(t1, TVar):
            if occurs(t1, t2, subst): raise ValueError("infinite type")
            subst[t1] = t2
        elif isinstance(t2, TVar):
            if occurs(t2, t1, subst): raise ValueError("infinite type")
            subst[t2] = t1
        elif isinstance(t1, FuncT) and isinstance(t2, FuncT):
            if len(t1.params) != len(t2.params): raise ValueError("arity mismatch")
            for p1, p2 in zip(t1.params, t2.params):
                unify(p1, p2)
            unify(t1.ret, t2.ret)
        elif isinstance(t1, ListT) and isinstance(t2, ListT):
            unify(t1.elem, t2.elem)
        elif isinstance(t1, RefT) and isinstance(t2, RefT):
            unify(t1.content, t2.content)
        else:
            raise ValueError("type mismatch")

    def collect_vars(t):
        if isinstance(t, TVar):
            return {t}
        if isinstance(t, FuncT):
            free = set()
            for p in t.params:
                free.update(collect_vars(p))
            free.update(collect_vars(t.ret))
            return free
        if isinstance(t, ListT):
            return collect_vars(t.elem)
        if isinstance(t, RefT):
            return collect_vars(t.content)
        return set()

    def collect_all_env_vars(env):
        free = set()
        for scope in env:
            for t_val in scope.values():
                free.update(collect_vars(t_val))
        return free

    def get_free_vars(t, env):
        return collect_vars(t) - collect_all_env_vars(env)

    def substitute(t, mapping):
        if isinstance(t, TVar):
            return mapping.get(t, t)
        if isinstance(t, FuncT):
            return FuncT([substitute(p, mapping) for p in t.params], substitute(t.ret, mapping))
        if isinstance(t, ListT):
            return ListT(substitute(t.elem, mapping))
        if isinstance(t, RefT):
            return RefT(substitute(t.content, mapping))
        return t

    def is_value_term(t):
        tag = t[0]
        if tag in ("int", "bool", "str", "unit", "var", "fn", "nil"):
            return True
        if tag == "cons":
            return is_value_term(t[1]) and is_value_term(t[2])
        return False

    def infer(t):
        tag = t[0]
        if tag == "int": return IntT()
        if tag == "bool": return BoolT()
        if tag == "str": return StrT()
        if tag == "unit": return UnitT()
        if tag == "var":
            name = t[1]
            for scope in reversed(env):
                if name in scope:
                    return apply_subst(scope[name])
            if name == "plus":
                return FuncT([IntT(), IntT()], IntT())
            if name == "eq":
                A = fresh()
                return FuncT([A, A], BoolT())
            if name == "size":
                return FuncT([StrT()], IntT())
            raise ValueError("unbound variable")
        if tag == "fn":
            params, body = t[1], t[2]
            ptypes = [fresh() for _ in params]
            env.append(dict(zip(params, ptypes)))
            ret = infer(body)
            env.pop()
            return FuncT(ptypes, ret)
        if tag == "call":
            f, args = t[1], t[2]
            tf = infer(f)
            targs = [infer(a) for a in args]
            ret = fresh()
            unify(tf, FuncT(targs, ret))
            return apply_subst(ret)
        if tag == "let":
            name, e1, e2 = t[1], t[2], t[3]
            t1 = infer(e1)
            t1 = apply_subst(t1)
            is_val = is_value_term(e1)
            if is_val:
                # Generalize: replace free vars in t1 not in env with fresh vars
                free = get_free_vars(t1, env)
                fresh_map = {v: fresh() for v in free}
                t1_gen = substitute(t1, fresh_map)
                env.append({name: t1_gen})
            else:
                # Monomorphic: replace free vars in t1 with fresh vars
                free = get_free_vars(t1, env)
                fresh_map = {v: fresh() for v in free}
                t1_mono = substitute(t1, fresh_map)
                env.append({name: t1_mono})
            t2 = infer(e2)
            env.pop()
            return t2
        if tag == "letrec":
            name, e1, e2 = t[1], t[2], t[3]
            if not isinstance(e1, tuple) or e1[0] != "fn":
                raise ValueError("letrec requires fn")
            params, body = e1[1], e1[2]
            func_type = fresh()
            env.append({name: func_type})
            inferred_func_type = infer(e1)
            unify(func_type, inferred_func_type)
            env.pop()
            # letrec always generalizes, but func_type is already a fresh TVar
            env.append({name: func_type})
            t2 = infer(e2)
            env.pop()
            return t2
        if tag == "nil":
            return ListT(fresh())
        if tag == "cons":
            h, tr = t[1], t[2]
            th = infer(h)
            tt = infer(tr)
            tt = apply_subst(tt)
            if not isinstance(tt, ListT): raise ValueError("type mismatch")
            unify(th, tt.elem)
            return ListT(apply_subst(th))
        if tag == "match":
            s, e_nil, hn, tn, e_cons = t[1], t[2], t[3], t[4], t[5]
            ts = infer(s)
            ts = apply_subst(ts)
            if not isinstance(ts, ListT): raise ValueError("type mismatch")
            A = ts.elem
            env.append({tn: ListT(A)})
            tn1 = infer(e_nil)
            env.pop()
            env.append({hn: A})
            tn2 = infer(e_cons)
            env.pop()
            unify(tn1, tn2)
            return apply_subst(tn1)
        if tag == "ref":
            e = t[1]
            te = infer(e)
            return RefT(te)
        if tag == "get":
            r = t[1]
            tr = infer(r)
            tr = apply_subst(tr)
            if not isinstance(tr, RefT): raise ValueError("type mismatch")
            return tr.content
        if tag == "set":
            r, e = t[1], t[2]
            tr = infer(r)
            tr = apply_subst(tr)
            if not isinstance(tr, RefT): raise ValueError("type mismatch")
            te = infer(e)
            unify(te, tr.content)
            return UnitT()
        raise ValueError("malformed")

    result = infer(term)
    result = apply_subst(result)

    # --- Printing ---
    def fmt(t):
        seen = {}
        counter = [0]
        def assign(v):
            if v not in seen:
                seen[v] = f"t{counter[0]+1}"
                counter[0] += 1
            return seen[v]
        def traverse(t):
            if isinstance(t, TVar):
                return assign(t)
            if isinstance(t, IntT): return "Int"
            if isinstance(t, BoolT): return "Bool"
            if isinstance(t, StrT): return "Str"
            if isinstance(t, UnitT): return "Unit"
            if isinstance(t, ListT): return f"List<{traverse(t.elem)}>"
            if isinstance(t, RefT): return f"Ref<{traverse(t.content)}>"
            if isinstance(t, FuncT):
                p_strs = [traverse(p) for p in t.params]
                r_str = traverse(t.ret)
                if len(t.params) == 1:
                    p = p_strs[0]
                    if isinstance(t.params[0], FuncT): return f"({p}) -> {r_str}"
                    return f"{p} -> {r_str}"
                return f"({', '.join(p_strs)}) -> {r_str}"
            return "?"
        return traverse(t)

    return fmt(result)

import sys
sys.setrecursionlimit(10000)

class TVar:
    def __init__(self, id):
        self.id = id
    def __repr__(self):
        return f"t{self.id+1}"
    def __hash__(self):
        return id(self)
    def __eq__(self, other):
        return self is other

class TBasic:
    def __init__(self, name):
        self.name = name
    def __repr__(self):
        return self.name
    def __hash__(self):
        return hash(self.name)
    def __eq__(self, other):
        return isinstance(other, TBasic) and self.name == other.name

class TList:
    def __init__(self, elem):
        self.elem = elem
    def __repr__(self):
        return f"List[{self.elem}]"
    def __hash__(self):
        return hash(("List", self.elem))
    def __eq__(self, other):
        return isinstance(other, TList) and self.elem == other.elem

class TRef:
    def __init__(self, elem):
        self.elem = elem
    def __repr__(self):
        return f"Ref[{self.elem}]"
    def __hash__(self):
        return hash(("Ref", self.elem))
    def __eq__(self, other):
        return isinstance(other, TRef) and self.elem == other.elem

class TFunc:
    def __init__(self, args, ret):
        self.args = args  # tuple
        self.ret = ret
    def __repr__(self):
        def fmt(t):
            if isinstance(t, TFunc):
                return f"({t})"
            return f"{t}"
        if len(self.args) == 1:
            return f"{fmt(self.args[0])} -> {self.ret}"
        else:
            return f"({', '.join(fmt(a) for a in self.args)}) -> {self.ret}"
    def __hash__(self):
        return hash(("Func", self.args, self.ret))
    def __eq__(self, other):
        return isinstance(other, TFunc) and self.args == other.args and self.ret == other.ret

KNOWN_TAGS = {
    "int", "bool", "str", "unit", "var", "fn", "call", "let", "letrec",
    "nil", "cons", "match", "ref", "get", "set"
}

def validate_term(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed tag")
    if tag not in KNOWN_TAGS:
        raise ValueError("Unknown tag")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
            raise ValueError("Malformed int")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed bool")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed str")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Malformed unit")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed var")
    elif tag == "fn":
        if len(term) != 3:
            raise ValueError("Malformed fn")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("Malformed fn params")
        if len(set(params)) != len(params):
            raise ValueError("Malformed fn params: not distinct")
        for p in params:
            if not isinstance(p, str) or not p:
                raise ValueError("Malformed fn param")
        validate_term(body)
    elif tag == "call":
        if len(term) != 3:
            raise ValueError("Malformed call")
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("Malformed call args")
        validate_term(f)
        for a in args:
            validate_term(a)
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Malformed let")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed let name")
        validate_term(e1)
        validate_term(e2)
    elif tag == "letrec":
        if len(term) != 4:
            raise ValueError("Malformed letrec")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed letrec name")
        validate_term(e1)
        validate_term(e2)
    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("Malformed nil")
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("Malformed cons")
        validate_term(term[1])
        validate_term(term[2])
    elif tag == "match":
        if len(term) != 5:
            raise ValueError("Malformed match")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        validate_term(s)
        validate_term(e_nil)
        validate_term(e_cons)
        if not isinstance(hn, str) or not hn:
            raise ValueError("Malformed match hn")
        if not isinstance(tn, str) or not tn:
            raise ValueError("Malformed match tn")
        if hn == tn:
            raise ValueError("Malformed match: hn and tn must differ")
    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("Malformed ref")
        validate_term(term[1])
    elif tag == "get":
        if len(term) != 2:
            raise ValueError("Malformed get")
        validate_term(term[1])
    elif tag == "set":
        if len(term) != 3:
            raise ValueError("Malformed set")
        validate_term(term[1])
        validate_term(term[2])

def apply_sub(t, sub):
    if isinstance(t, TVar):
        return sub.get(t, t)
    if isinstance(t, TBasic):
        return t
    if isinstance(t, TList):
        return TList(apply_sub(t.elem, sub))
    if isinstance(t, TRef):
        return TRef(apply_sub(t.elem, sub))
    if isinstance(t, TFunc):
        return TFunc(tuple(apply_sub(a, sub) for a in t.args), apply_sub(t.ret, sub))
    return t

def occurs(v, t, sub):
    t = apply_sub(t, sub)
    if t == v: return True
    if isinstance(t, TVar): return False
    if isinstance(t, TList) or isinstance(t, TRef):
        return occurs(v, t.elem, sub)
    if isinstance(t, TFunc):
        return any(occurs(v, a, sub) for a in t.args) or occurs(v, t.ret, sub)
    return False

def unify(t1, t2, sub):
    t1 = apply_sub(t1, sub)
    t2 = apply_sub(t2, sub)
    if t1 == t2:
        return sub
    if isinstance(t1, TVar):
        if isinstance(t2, TVar) and t1 == t2:
            return sub
        if occurs(t1, t2, sub):
            raise ValueError("Infinite type")
        return {t1: t2, **sub}
    if isinstance(t2, TVar):
        return unify(t2, t1, sub)
    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        if len(t1.args) != len(t2.args):
            raise ValueError("Arity mismatch")
        sub2 = unify(t1.ret, t2.ret, sub)
        for a1, a2 in zip(t1.args, t2.args):
            sub2 = unify(a1, a2, sub2)
        return sub2
    if isinstance(t1, TList) and isinstance(t2, TList):
        return unify(t1.elem, t2.elem, sub)
    if isinstance(t1, TRef) and isinstance(t2, TRef):
        return unify(t1.elem, t2.elem, sub)
    raise ValueError("Type mismatch")

def free_vars(t):
    if isinstance(t, TVar):
        return {t}
    if isinstance(t, TBasic):
        return set()
    if isinstance(t, TList):
        return free_vars(t.elem)
    if isinstance(t, TRef):
        return free_vars(t.elem)
    if isinstance(t, TFunc):
        res = set()
        for a in t.args:
            res |= free_vars(a)
        res |= free_vars(t.ret)
        return res
    return set()

def is_value(term):
    if not isinstance(term, tuple) or len(term) == 0:
        return False
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var", "fn", "nil"):
        return True
    if tag == "cons":
        return is_value(term[1]) and is_value(term[2])
    return False

class InferenceContext:
    def __init__(self):
        self.fresh_counter = 0
        self.sub = {}
        self.env = {
            "plus": TFunc((TBasic("Int"), TBasic("Int")), TBasic("Int")),
            "eq": TFunc((TVar(0), TVar(0)), TBasic("Bool")),
            "size": TFunc((TBasic("Str")), TBasic("Int"))
        }

def instantiate(t, ctx):
    mapping = {}
    for v in free_vars(t):
        if v not in mapping:
            mapping[v] = TVar(next(ctx.fresh_counter))
    return apply_sub(t, mapping), mapping

def infer(term, ctx):
    tag = term[0]
    if tag == "int":
        return TBasic("Int")
    elif tag == "bool":
        return TBasic("Bool")
    elif tag == "str":
        return TBasic("Str")
    elif tag == "unit":
        return TBasic("Unit")
    elif tag == "var":
        name = term[1]
        if name not in ctx.env:
            raise ValueError(f"Unbound variable: {name}")
        t = ctx.env[name]
        return instantiate(t, ctx)[0]
    elif tag == "fn":
        params, body = term[1], term[2]
        param_types = tuple(TVar(next(ctx.fresh_counter)) for _ in params)
        new_env = {**ctx.env}
        for p, pt in zip(params, param_types):
            new_env[p] = pt
        old_env = ctx.env
        ctx.env = new_env
        ret_type = infer(body, ctx)
        ctx.env = old_env
        ret_type = apply_sub(ret_type, ctx.sub)
        param_types = tuple(apply_sub(pt, ctx.sub) for pt in param_types)
        return TFunc(param_types, ret_type)
    elif tag == "call":
        f, args = term[1], term[2]
        f_type = infer(f, ctx)
        f_type = apply_sub(f_type, ctx.sub)
        if not isinstance(f_type, TFunc):
            raise ValueError("Call on non-function")
        if len(args) != len(f_type.args):
            raise ValueError("Arity mismatch")
        arg_types = tuple(infer(a, ctx) for a in args)
        for at, pt in zip(arg_types, f_type.args):
            ctx.sub = unify(at, pt, ctx.sub)
        return apply_sub(f_type.ret, ctx.sub)
    elif tag == "let":
        name, e1, e2 = term[1], term[2], term[3]
        t1 = infer(e1, ctx)
        t1 = apply_sub(t1, ctx.sub)
        if is_value(e1):
            ctx.env[name] = t1
        else:
            t1, _ = instantiate(t1, ctx)
            ctx.env[name] = t1
        return infer(e2, ctx)
    elif tag == "letrec":
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(e1, tuple) or e1[0] != "fn":
            raise ValueError("letrec requires fn")
        fresh_t = TVar(next(ctx.fresh_counter))
        new_env = {**ctx.env, name: fresh_t}
        old_env = ctx.env
        ctx.env = new_env
        t1 = infer(e1, ctx)
        ctx.env = old_env
        t1 = apply_sub(t1, ctx.sub)
        ctx.env[name] = t1
        return infer(e2, ctx)
    elif tag == "nil":
        return TList(TVar(next(ctx.fresh_counter)))
    elif tag == "cons":
        h, t = term[1], term[2]
        t_type = infer(t, ctx)
        t_type = apply_sub(t_type, ctx.sub)
        if not isinstance(t_type, TList):
            raise ValueError("cons tail not list")
        h_type = infer(h, ctx)
        ctx.sub = unify(h_type, t_type.elem, ctx.sub)
        return apply_sub(t_type, ctx.sub)
    elif tag == "match":
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        s_type = infer(s, ctx)
        s_type = apply_sub(s_type, ctx.sub)
        if not isinstance(s_type, TList):
            raise ValueError("match scrutinee not list")
        s_type_inst, _ = instantiate(s_type, ctx)
        t_nil = infer(e_nil, ctx)
        new_env = {**ctx.env, hn: s_type_inst.elem, tn: s_type_inst}
        old_env = ctx.env
        ctx.env = new_env
        t_cons = infer(e_cons, ctx)
        ctx.env = old_env
        ctx.sub = unify(t_nil, t_cons, ctx.sub)
        return apply_sub(t_nil, ctx.sub)
    elif tag == "ref":
        e = term[1]
        t = infer(e, ctx)
        return TRef(t)
    elif tag == "get":
        r = term[1]
        r_type = infer(r, ctx)
        r_type = apply_sub(r_type, ctx.sub)
        if not isinstance(r_type, TRef):
            raise ValueError("get on non-ref")
        return r_type.elem
    elif tag == "set":
        r, e = term[1], term[2]
        r_type = infer(r, ctx)
        r_type = apply_sub(r_type, ctx.sub)
        if not isinstance(r_type, TRef):
            raise ValueError("set on non-ref")
        e_type = infer(e, ctx)
        ctx.sub = unify(e_type, r_type.elem, ctx.sub)
        return TBasic("Unit")
    else:
        raise ValueError("Unknown tag")

def weak_infer(term):
    validate_term(term)
    ctx = InferenceContext()
    try:
        res_type = infer(term, ctx)
        res_type = apply_sub(res_type, ctx.sub)
    except ValueError:
        raise
    except Exception as e:
        raise ValueError(str(e))

    # Collect all type vars in order of appearance
    type_vars = []
    def collect_vars(t):
        if isinstance(t, TVar):
            if t not in type_vars:
                type_vars.append(t)
        elif isinstance(t, TList):
            collect_vars(t.elem)
        elif isinstance(t, TRef):
            collect_vars(t.elem)
        elif isinstance(t, TFunc):
            for a in t.args:
                collect_vars(a)
            collect_vars(t.ret)
    collect_vars(res_type)

    # Renumber
    mapping = {t: TBasic(f"t{i+1}") for i, t in enumerate(type_vars)}
    def replace_vars(t):
        if isinstance(t, TVar):
            return mapping[t]
        if isinstance(t, TList):
            return TList(replace_vars(t.elem))
        if isinstance(t, TRef):
            return TRef(replace_vars(t.elem))
        if isinstance(t, TFunc):
            return TFunc(tuple(replace_vars(a) for a in t.args), replace_vars(t.ret))
        return t

    final_type = replace_vars(res_type)
    return str(final_type)

import sys

# Prevent recursion limit issues for deeply nested terms
sys.setrecursionlimit(10000)

class Type:
    pass

class TVar(Type):
    def __init__(self, idx): self.idx = idx
    def __eq__(self, o): return isinstance(o, TVar) and self.idx == o.idx
    def __hash__(self): return self.idx

class TInt(Type): pass
class TBool(Type): pass
class TStr(Type): pass
class TUnit(Type): pass

class TList(Type):
    def __init__(self, inner): self.inner = inner
    def __eq__(self, o): return isinstance(o, TList) and self.inner == o.inner
    def __hash__(self): return hash(self.inner)

class TRef(Type):
    def __init__(self, inner): self.inner = inner
    def __eq__(self, o): return isinstance(o, TRef) and self.inner == o.inner
    def __hash__(self): return hash(self.inner)

class TFunc(Type):
    def __init__(self, args, ret): self.args = args; self.ret = ret
    def __eq__(self, o): return isinstance(o, TFunc) and self.args == o.args and self.ret == o.ret
    def __hash__(self): return hash((self.args, self.ret))

class Unifier:
    def __init__(self):
        self.subst = {}

    def apply(self, t):
        if isinstance(t, TVar):
            while t in self.subst and self.subst[t] != t:
                t = self.subst[t]
            return t
        elif isinstance(t, TFunc):
            return TFunc(tuple(self.apply(a) for a in t.args), self.apply(t.ret))
        elif isinstance(t, TList):
            return TList(self.apply(t.inner))
        elif isinstance(t, TRef):
            return TRef(self.apply(t.inner))
        return t

    def occurs(self, var, t):
        t = self.apply(t)
        if t == var: return True
        if isinstance(t, TFunc):
            return any(self.occurs(var, a) for a in t.args) or self.occurs(var, t.ret)
        elif isinstance(t, TList):
            return self.occurs(var, t.inner)
        elif isinstance(t, TRef):
            return self.occurs(var, t.inner)
        return False

    def unify(self, t1, t2):
        t1 = self.apply(t1)
        t2 = self.apply(t2)
        if t1 == t2: return
        if isinstance(t1, TVar):
            if self.occurs(t1, t2): raise ValueError("Infinite type")
            self.subst[t1] = t2
        elif isinstance(t2, TVar):
            if self.occurs(t2, t1): raise ValueError("Infinite type")
            self.subst[t2] = t1
        elif isinstance(t1, TFunc) and isinstance(t2, TFunc):
            if len(t1.args) != len(t2.args): raise ValueError("Arity mismatch")
            for a1, a2 in zip(t1.args, t2.args):
                self.unify(a1, a2)
            self.unify(t1.ret, t2.ret)
        elif isinstance(t1, TList) and isinstance(t2, TList):
            self.unify(t1.inner, t2.inner)
        elif isinstance(t1, TRef) and isinstance(t2, TRef):
            self.unify(t1.inner, t2.inner)
        else:
            raise ValueError("Type mismatch")

def free_vars(t):
    if isinstance(t, TVar): return {t.idx}
    if isinstance(t, TFunc):
        fvs = set()
        for a in t.args: fvs |= free_vars(a)
        return fvs | free_vars(t.ret)
    if isinstance(t, TList): return free_vars(t.inner)
    if isinstance(t, TRef): return free_vars(t.inner)
    return set()

def substitute(t, mapping):
    if isinstance(t, TVar): return mapping.get(t.idx, t)
    if isinstance(t, TFunc):
        return TFunc(tuple(substitute(a, mapping) for a in t.args), substitute(t.ret, mapping))
    if isinstance(t, TList): return TList(substitute(t.inner, mapping))
    if isinstance(t, TRef): return TRef(substitute(t.inner, mapping))
    return t

def validate(term):
    if not isinstance(term, tuple) or len(term) == 0: raise ValueError
    tag = term[0]
    if not isinstance(tag, str): raise ValueError
    valid = {"int","bool","str","unit","var","fn","call","let","letrec","nil","cons","match","ref","get","set"}
    if tag not in valid: raise ValueError
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool): raise ValueError
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool): raise ValueError
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str): raise ValueError
    elif tag == "unit":
        if len(term) != 1: raise ValueError
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]: raise ValueError
    elif tag == "fn":
        if len(term) != 3: raise ValueError
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0: raise ValueError
        if len(set(params)) != len(params): raise ValueError
        if not all(isinstance(p, str) and p for p in params): raise ValueError
        validate(body)
    elif tag == "call":
        if len(term) != 3: raise ValueError
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or len(args) == 0: raise ValueError
        validate(f)
        for a in args: validate(a)
    elif tag == "let":
        if len(term) != 4: raise ValueError
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name: raise ValueError
        validate(e1); validate(e2)
    elif tag == "letrec":
        if len(term) != 4: raise ValueError
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name: raise ValueError
        validate(e1); validate(e2)
    elif tag == "nil":
        if len(term) != 1: raise ValueError
    elif tag == "cons":
        if len(term) != 3: raise ValueError
        h, t = term[1], term[2]
        validate(h); validate(t)
    elif tag == "match":
        if len(term) != 5: raise ValueError
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not isinstance(hn, str) or not isinstance(tn, str) or not hn or not tn: raise ValueError
        if hn == tn: raise ValueError
        validate(s); validate(e_nil); validate(e_cons)
    elif tag == "ref":
        if len(term) != 2: raise ValueError
        validate(term[1])
    elif tag == "get":
        if len(term) != 2: raise ValueError
        validate(term[1])
    elif tag == "set":
        if len(term) != 3: raise ValueError
        r, e = term[1], term[2]
        validate(r); validate(e)

def is_value(term):
    if not isinstance(term, tuple): return False
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var", "fn", "nil"): return True
    if tag == "cons":
        return is_value(term[1]) and is_value(term[2])
    return False

def weak_infer(term):
    validate(term)

    class Infer:
        def __init__(self):
            self.u = Unifier()
            self.fresh_idx = 0
            self.env = {"plus": TFunc((TInt, TInt), TInt),
                        "eq": TFunc((TVar(0), TVar(0)), TBool),
                        "size": TFunc((TStr,), TInt)}
            # Hack for eq's generic var: we'll treat env types as already applied
            # Actually, eq: (a,a)->Bool means fresh vars on call. We'll just store a fresh var for 'a' initially, 
            # but since it's in env, we should instantiate it fresh each time or store it as a pattern.
            # Simpler: store as TFunc((self.fresh(), self.fresh()), TBool) but that ties them.
            # Better: store as TFunc((TVar(-1), TVar(-1)), TBool) and unify on use? 
            # Standard HM: env stores monomorphic types. Polymorphic functions are instantiated on call.
            # We'll instantiate env functions on lookup.
            self.env = {"plus": TFunc((TInt, TInt), TInt),
                        "eq": TFunc((TVar(0), TVar(0)), TBool),
                        "size": TFunc((TStr,), TInt)}
            # We'll handle instantiation in var lookup.

        def fresh(self):
            v = TVar(self.fresh_idx)
            self.fresh_idx += 1
            return v

        def instantiate(self, t):
            # Replace free vars with fresh ones
            fv = free_vars(t)
            mapping = {v: self.fresh() for v in fv}
            return substitute(t, mapping)

        def generalize(self, t):
            fv = free_vars(t)
            env_fv = set()
            for v in self.env.values():
                env_fv |= free_vars(self.u.apply(v))
            to_quantify = fv - env_fv
            mapping = {v: self.fresh() for v in to_quantify}
            return substitute(t, mapping)

        def infer(self, term):
            tag = term[0]
            if tag == "int": return TInt
            if tag == "bool": return TBool
            if tag == "str": return TStr
            if tag == "unit": return TUnit
            if tag == "var":
                name = term[1]
                if name not in self.env: raise ValueError("Unbound variable")
                t = self.u.apply(self.env[name])
                # Instantiate polymorphic types
                if isinstance(t, TFunc):
                    # Check if it has free vars (polymorphic)
                    if free_vars(t):
                        t = self.instantiate(t)
                return t
            if tag == "fn":
                params, body = term[1], term[2]
                param_types = tuple(self.fresh() for _ in params)
                old_env = self.env
                self.env = {**self.env, **{p: t for p, t in zip(params, param_types)}}
                ret_type = self.infer(body)
                self.env = old_env
                return TFunc(param_types, ret_type)
            if tag == "call":
                f, args = term[1], term[2]
                f_type = self.infer(f)
                arg_types = tuple(self.fresh() for _ in args)
                ret_type = self.fresh()
                self.u.unify(f_type, TFunc(arg_types, ret_type))
                for a, at in zip(args, arg_types):
                    self.u.unify(self.infer(a), at)
                return ret_type
            if tag == "let":
                name, e1, e2 = term[1], term[2], term[3]
                t1 = self.infer(e1)
                if is_value(e1):
                    t1 = self.generalize(t1)
                self.env = {**self.env, name: t1}
                return self.infer(e2)
            if tag == "letrec":
                name, e1, e2 = term[1], term[2], term[3]
                if not (isinstance(e1, tuple) and e1[0] == "fn"):
                    raise ValueError("letrec requires fn")
                t1 = self.infer(e1)
                t1 = self.generalize(t1)
                self.env = {**self.env, name: t1}
                return self.infer(e2)
            if tag == "nil":
                return TList(self.fresh())
            if tag == "cons":
                h, t = term[1], term[2]
                th = self.infer(h)
                tt = self.infer(t)
                self.u.unify(tt, TList(th))
                return tt
            if tag == "match":
                s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
                ts = self.infer(s)
                A = self.fresh()
                self.u.unify(ts, TList(A))
                old_env = self.env
                self.env = {**self.env, hn: A, tn: TList(A)}
                t_nil = self.infer(e_nil)
                t_cons = self.infer(e_cons)
                self.env = old_env
                self.u.unify(t_nil, t_cons)
                return t_cons
            if tag == "ref":
                e = term[1]
                te = self.infer(e)
                return TRef(te)
            if tag == "get":
                r = term[1]
                tr = self.u.apply(self.infer(r))
                if not isinstance(tr, TRef): raise ValueError("Type mismatch")
                return tr.inner
            if tag == "set":
                r, e = term[1], term[2]
                tr = self.u.apply(self.infer(r))
                te = self.infer(e)
                if not isinstance(tr, TRef): raise ValueError("Type mismatch")
                self.u.unify(tr.inner, te)
                return TUnit
            raise ValueError("Unknown tag")

    inf = Infer()
    res_type = inf.infer(term)
    res_type = inf.u.apply(res_type)

    # Collect vars in order of first appearance
    order = []
    seen = set()
    def collect(t):
        if isinstance(t, TVar):
            if t.idx not in seen:
                seen.add(t.idx)
                order.append(t.idx)
        elif isinstance(t, TFunc):
            for a in t.args: collect(a)
            collect(t.ret)
        elif isinstance(t, TList): collect(t.inner)
        elif isinstance(t, TRef): collect(t.inner)
    collect(res_type)
    var_map = {idx: f"t{i+1}" for i, idx in enumerate(order)}

    def fmt(t):
        if isinstance(t, TVar): return var_map[t.idx]
        if isinstance(t, TInt): return "Int"
        if isinstance(t, TBool): return "Bool"
        if isinstance(t, TStr): return "Str"
        if isinstance(t, TUnit): return "Unit"
        if isinstance(t, TRef): return f"Ref<{fmt(t.inner)}>"
        if isinstance(t, TList): return f"List<{fmt(t.inner)}>"
        if isinstance(t, TFunc):
            ret_str = fmt(t.ret)
            if len(t.args) == 1:
                p = fmt(t.args[0])
                if isinstance(t.args[0], TFunc): p = f"({p})"
                return f"{p} -> {ret_str}"
            else:
                ps = ", ".join(fmt(a) for a in t.args)
                return f"({ps}) -> {ret_str}"
        return "?"

    return fmt(res_type)

import sys

# Increase recursion depth for deep type trees
sys.setrecursionlimit(10000)

class Type:
    pass

class TVar(Type):
    def __init__(self, id):
        self.id = id
    def __eq__(self, other):
        return isinstance(other, TVar) and self.id == other.id
    def __hash__(self):
        return hash(self.id)

class TInt(Type):
    pass

class TBool(Type):
    pass

class TFun(Type):
    def __init__(self, a, b):
        self.a, self.b = a, b
    def __eq__(self, other):
        return isinstance(other, TFun) and self.a == other.a and self.b == other.b

class TList(Type):
    def __init__(self, a):
        self.a = a
    def __eq__(self, other):
        return isinstance(other, TList) and self.a == other.a

class TTuple(Type):
    def __init__(self, types):
        self.types = types
    def __eq__(self, other):
        return isinstance(other, TTuple) and self.types == other.types

class HMInfer:
    def __init__(self):
        self.fresh_counter = 0
        self.env = {
            'add': (set(), TFun(TInt, TFun(TInt, TInt))),
            'eq': (set(), TFun(TVar('a'), TFun(TVar('a'), TBool))),
            'nil': (set(), TList(TVar('a'))),
            'cons': (set(), TFun(TVar('a'), TFun(TList(TVar('a')), TList(TVar('a'))))),
            'head': (set(), TFun(TList(TVar('a')), TVar('a'))),
            'tail': (set(), TFun(TList(TVar('a')), TList(TVar('a')))),
            'isnil': (set(), TFun(TList(TVar('a')), TBool))
        }

    def fresh(self):
        v = TVar(f'v{self.fresh_counter}')
        self.fresh_counter += 1
        return v

    def apply_subst(self, t, s):
        if isinstance(t, TVar):
            return s.get(t.id, t)
        elif isinstance(t, TFun):
            return TFun(self.apply_subst(t.a, s), self.apply_subst(t.b, s))
        elif isinstance(t, TList):
            return TList(self.apply_subst(t.a, s))
        elif isinstance(t, TTuple):
            return TTuple([self.apply_subst(x, s) for x in t.types])
        return t

    def free_vars(self, t):
        if isinstance(t, TVar):
            return {t.id}
        elif isinstance(t, TFun):
            return self.free_vars(t.a) | self.free_vars(t.b)
        elif isinstance(t, TList):
            return self.free_vars(t.a)
        elif isinstance(t, TTuple):
            fs = set()
            for x in t.types:
                fs |= self.free_vars(x)
            return fs
        return set()

    def occurs(self, vid, t):
        if isinstance(t, TVar):
            return t.id == vid
        elif isinstance(t, TFun):
            return self.occurs(vid, t.a) or self.occurs(vid, t.b)
        elif isinstance(t, TList):
            return self.occurs(vid, t.a)
        elif isinstance(t, TTuple):
            return any(self.occurs(vid, x) for x in t.types)
        return False

    def unify(self, t1, t2, s=None):
        if s is None:
            s = {}
        t1 = self.apply_subst(t1, s)
        t2 = self.apply_subst(t2, s)
        if t1 == t2:
            return s
        if isinstance(t1, TVar):
            return self.unify_var(t1, t2, s)
        if isinstance(t2, TVar):
            return self.unify_var(t2, t1, s)
        if isinstance(t1, TFun) and isinstance(t2, TFun):
            s1 = self.unify(t1.a, t2.a, s)
            return self.unify(t1.b, t2.b, s1)
        if isinstance(t1, TList) and isinstance(t2, TList):
            return self.unify(t1.a, t2.a, s)
        if isinstance(t1, TTuple) and isinstance(t2, TTuple):
            if len(t1.types) != len(t2.types):
                raise ValueError("Type mismatch")
            res = s
            for a, b in zip(t1.types, t2.types):
                res = self.unify(a, b, res)
            return res
        raise ValueError("Type mismatch")

    def unify_var(self, v, t, s):
        if self.occurs(v.id, t):
            raise ValueError("Infinite type")
        s[v.id] = t
        return s

    def free_vars_in_env(self, env):
        fs = set()
        for _, val in env.items():
            if isinstance(val, tuple):
                _, typ = val
                fs |= self.free_vars(typ)
            else:
                fs |= self.free_vars(val)
        return fs

    def generalize(self, env, t):
        qvars = self.free_vars(t) - self.free_vars_in_env(env)
        return (qvars, t)

    def instantiate(self, qvars, t):
        s = {v: self.fresh() for v in qvars}
        return self.apply_subst(t, s)

    def lookup(self, name, env):
        if name not in env:
            raise ValueError(f"Unbound variable: {name}")
        val = env[name]
        if isinstance(val, tuple):
            qvars, typ = val
            return self.instantiate(qvars, typ)
        return val

    def validate(self, term):
        if isinstance(term, int) and not isinstance(term, bool):
            return
        if isinstance(term, bool):
            return
        if isinstance(term, str) and len(term) > 0:
            return
        if not isinstance(term, tuple) or len(term) < 1:
            raise ValueError("Malformed")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Malformed")
        if tag == "lam":
            if len(term) != 3: raise ValueError("Malformed")
            if not isinstance(term[1], str) or len(term[1]) == 0: raise ValueError("Malformed")
            self.validate(term[2])
        elif tag == "app":
            if len(term) != 3: raise ValueError("Malformed")
            self.validate(term[1])
            self.validate(term[2])
        elif tag == "if":
            if len(term) != 4: raise ValueError("Malformed")
            self.validate(term[1])
            self.validate(term[2])
            self.validate(term[3])
        elif tag == "let":
            if len(term) != 4: raise ValueError("Malformed")
            if not isinstance(term[1], str) or len(term[1]) == 0: raise ValueError("Malformed")
            self.validate(term[2])
            self.validate(term[3])
        elif tag == "letrec":
            if len(term) != 3: raise ValueError("Malformed")
            group = term[1]
            if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Malformed")
            names = set()
            for item in group:
                if not isinstance(item, tuple) or len(item) != 2: raise ValueError("Malformed")
                n, e = item
                if not isinstance(n, str) or len(n) == 0: raise ValueError("Malformed")
                if n in names: raise ValueError("Duplicate name")
                names.add(n)
                self.validate(e)
            self.validate(term[2])
        elif tag == "tuple":
            if len(term) == 1:
                pass # n=0
            elif len(term) == 2:
                raise ValueError("n=1 not allowed")
            else:
                for e in term[1:]:
                    self.validate(e)
        elif tag == "proj":
            if len(term) != 4: raise ValueError("Malformed")
            i, n, e = term[1], term[2], term[3]
            if not isinstance(i, int) or isinstance(i, bool): raise ValueError("Malformed")
            if not isinstance(n, int) or isinstance(n, bool): raise ValueError("Malformed")
            if n < 2: raise ValueError("n<2")
            if i < 0 or i >= n: raise ValueError("i out of bounds")
            self.validate(e)
        else:
            raise ValueError("Unknown tag")

    def infer(self, term, env):
        if isinstance(term, int) and not isinstance(term, bool):
            return TInt
        if isinstance(term, bool):
            return TBool
        if isinstance(term, str):
            return self.lookup(term, env)
        if not isinstance(term, tuple):
            raise ValueError("Malformed")
        tag = term[0]
        if tag == "lam":
            x, body = term[1], term[2]
            x_type = self.fresh()
            new_env = {**env, x: x_type}
            body_type = self.infer(body, new_env)
            return TFun(x_type, body_type)
        if tag == "app":
            f, a = term[1], term[2]
            f_type = self.infer(f, env)
            a_type = self.infer(a, env)
            arg_type = self.fresh()
            res_type = self.fresh()
            self.unify(f_type, TFun(arg_type, res_type))
            return res_type
        if tag == "if":
            c, t, e = term[1], term[2], term[3]
            c_type = self.infer(c, env)
            self.unify(c_type, TBool)
            t_type = self.infer(t, env)
            e_type = self.infer(e, env)
            self.unify(t_type, e_type)
            return t_type
        if tag == "let":
            x, e1, e2 = term[1], term[2], term[3]
            x_type = self.infer(e1, env)
            qvars, gen_type = self.generalize(env, x_type)
            new_env = {**env, x: (qvars, gen_type)}
            return self.infer(e2, new_env)
        if tag == "letrec":
            group, body = term[1], term[2]
            group_env = {**env}
            for name, _ in group:
                group_env[name] = (set(), self.fresh())
            group_types = {}
            for name, expr in group:
                group_types[name] = self.infer(expr, group_env)
            letrec_env = {**env}
            for name, t in group_types.items():
                qvars = self.free_vars(t) - self.free_vars_in_env(env)
                letrec_env[name] = (qvars, t)
            return self.infer(body, letrec_env)
        if tag == "tuple":
            es = term[1:]
            types = [self.infer(e, env) for e in es]
            return TTuple(types)
        if tag == "proj":
            i, n, e = term[1], term[2], term[3]
            e_type = self.infer(e, env)
            tuple_vars = [self.fresh() for _ in range(n)]
            self.unify(e_type, TTuple(tuple_vars))
            # After unification, e_type is unified to TTuple(tuple_vars)
            # We need to apply the substitution to e_type to get the actual type
            # But unify modifies nothing in place, we need to track substitution
            # Actually, we can just reconstruct from e_type using a fresh subst map
            # Simpler: unify returns s. We apply s to e_type.
            # But we didn't capture s. Let's refactor unify to return s and modify e_type.
            # I'll rewrite proj to capture substitution.
            pass
        raise ValueError("Malformed")

    def infer_proj(self, term, env):
        i, n, e = term[1], term[2], term[3]
        e_type = self.infer(e, env)
        tuple_vars = [self.fresh() for _ in range(n)]
        s = self.unify(e_type, TTuple(tuple_vars))
        resolved = self.apply_subst(e_type, s)
        if not isinstance(resolved, TTuple):
            raise ValueError("Type mismatch")
        return resolved.types[i]

    def type_to_str(self, t):
        order = []
        def collect(tv):
            if isinstance(tv, TVar) and tv.id not in order:
                order.append(tv.id)
            elif isinstance(tv, TFun):
                collect(tv.a)
                collect(tv.b)
            elif isinstance(tv, TList):
                collect(tv.a)
            elif isinstance(tv, TTuple):
                for x in tv.types:
                    collect(x)
        collect(t)

        mapping = {}
        idx = 0
        for vid in order:
            mapping[vid] = self.to_name(idx)
            idx += 1

        def to_name(i):
            if i < 26:
                return chr(ord('a') + i)
            res = []
            while i >= 0:
                i, r = divmod(i, 26)
                res.append(chr(ord('a') + r))
                i -= 1
            return ''.join(reversed(res))

        def build(t):
            if isinstance(t, TVar):
                return mapping[t.id]
            elif isinstance(t, TInt):
                return "Int"
            elif isinstance(t, TBool):
                return "Bool"
            elif isinstance(t, TFun):
                return f"(-> {build(t.a)} {build(t.b)})"
            elif isinstance(t, TList):
                return f"(List {build(t.a)})"
            elif isinstance(t, TTuple):
                if len(t.types) == 0:
                    return "(Tuple)"
                return f"(Tuple {' '.join(build(x) for x in t.types)})"
            return "?"
        return build(t)

