        res_type = inferer.infer(term, inferer.env)
    except ValueError:
        raise

    return inferer.type_to_str(res_type)

import sys

# Increase recursion depth for deep type trees
sys.setrecursionlimit(10000)

class Type:
    pass

class TVar(Type):
    def __init__(self, id):
        self.id = id
    def __eq__(self, other):
        return isinstance(other, TVar) and self.id == other.id
    def __hash__(self):
        return hash(self.id)

class TInt(Type):
    pass

class TBool(Type):
    pass

class TFun(Type):
    def __init__(self, a, b):
        self.a = a
        self.b = b
    def __eq__(self, other):
        return isinstance(other, TFun) and self.a == other.a and self.b == other.b

class TList(Type):
    def __init__(self, a):
        self.a = a
    def __eq__(self, other):
        return isinstance(other, TList) and self.a == other.a

class TTuple(Type):
    def __init__(self, types):
        self.types = types
    def __eq__(self, other):
        return isinstance(other, TTuple) and self.types == other.types

class HMInfer:
    def __init__(self):
        self.fresh_counter = 0
        self.env = {
            'add': (set(), TFun(TInt, TFun(TInt, TInt))),
            'eq': (set(), TFun(TVar('a'), TFun(TVar('a'), TBool))),
            'nil': (set(), TList(TVar('a'))),
            'cons': (set(), TFun(TVar('a'), TFun(TList(TVar('a')), TList(TVar('a'))))),
            'head': (set(), TFun(TList(TVar('a')), TVar('a'))),
            'tail': (set(), TFun(TList(TVar('a')), TList(TVar('a')))),
            'isnil': (set(), TFun(TList(TVar('a')), TBool))
        }

    def fresh(self):
        v = TVar(f'v{self.fresh_counter}')
        self.fresh_counter += 1
        return v

    def apply_subst(self, t, s):
        if isinstance(t, TVar):
            return s.get(t.id, t)
        elif isinstance(t, TFun):
            return TFun(self.apply_subst(t.a, s), self.apply_subst(t.b, s))
        elif isinstance(t, TList):
            return TList(self.apply_subst(t.a, s))
        elif isinstance(t, TTuple):
            return TTuple([self.apply_subst(x, s) for x in t.types])
        return t

    def free_vars(self, t):
        if isinstance(t, TVar):
            return {t.id}
        elif isinstance(t, TFun):
            return self.free_vars(t.a) | self.free_vars(t.b)
        elif isinstance(t, TList):
            return self.free_vars(t.a)
        elif isinstance(t, TTuple):
            fs = set()
            for x in t.types:
                fs |= self.free_vars(x)
            return fs
        return set()

    def occurs(self, vid, t):
        if isinstance(t, TVar):
            return t.id == vid
        elif isinstance(t, TFun):
            return self.occurs(vid, t.a) or self.occurs(vid, t.b)
        elif isinstance(t, TList):
            return self.occurs(vid, t.a)
        elif isinstance(t, TTuple):
            return any(self.occurs(vid, x) for x in t.types)
        return False

    def unify(self, t1, t2, s=None):
        if s is None:
            s = {}
        t1 = self.apply_subst(t1, s)
        t2 = self.apply_subst(t2, s)
        if t1 == t2:
            return s
        if isinstance(t1, TVar):
            return self.unify_var(t1, t2, s)
        if isinstance(t2, TVar):
            return self.unify_var(t2, t1, s)
        if isinstance(t1, TFun) and isinstance(t2, TFun):
            s1 = self.unify(t1.a, t2.a, s)
            return self.unify(t1.b, t2.b, s1)
        if isinstance(t1, TList) and isinstance(t2, TList):
            return self.unify(t1.a, t2.a, s)
        if isinstance(t1, TTuple) and isinstance(t2, TTuple):
            if len(t1.types) != len(t2.types):
                raise ValueError("Type mismatch")
            res = s
            for a, b in zip(t1.types, t2.types):
                res = self.unify(a, b, res)
            return res
        raise ValueError("Type mismatch")

    def unify_var(self, v, t, s):
        if self.occurs(v.id, t):
            raise ValueError("Infinite type")
        s = dict(s)
        s[v.id] = t
        return s

    def free_vars_in_env(self, env):
        fs = set()
        for _, val in env.items():
            if isinstance(val, tuple):
                _, typ = val
                fs |= self.free_vars(typ)
            else:
                fs |= self.free_vars(val)
        return fs

    def generalize(self, env, t):
        qvars = self.free_vars(t) - self.free_vars_in_env(env)
        return (qvars, t)

    def instantiate(self, qvars, t):
        s = {v: self.fresh() for v in qvars}
        return self.apply_subst(t, s)

    def lookup(self, name, env):
        if name not in env:
            raise ValueError(f"Unbound variable: {name}")
        val = env[name]
        if isinstance(val, tuple):
            qvars, typ = val
            return self.instantiate(qvars, typ)
        return val

    def validate(self, term):
        if isinstance(term, int) and not isinstance(term, bool):
            return
        if isinstance(term, bool):
            return
        if isinstance(term, str) and len(term) > 0:
            return
        if not isinstance(term, tuple) or len(term) < 1:
            raise ValueError("Malformed")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Malformed")
        if tag == "lam":
            if len(term) != 3: raise ValueError("Malformed")
            if not isinstance(term[1], str) or len(term[1]) == 0: raise ValueError("Malformed")
            self.validate(term[2])
        elif tag == "app":
            if len(term) != 3: raise ValueError("Malformed")
            self.validate(term[1])
            self.validate(term[2])
        elif tag == "if":
            if len(term) != 4: raise ValueError("Malformed")
            self.validate(term[1])
            self.validate(term[2])
            self.validate(term[3])
        elif tag == "let":
            if len(term) != 4: raise ValueError("Malformed")
            if not isinstance(term[1], str) or len(term[1]) == 0: raise ValueError("Malformed")
            self.validate(term[2])
            self.validate(term[3])
        elif tag == "letrec":
            if len(term) != 3: raise ValueError("Malformed")
            group = term[1]
            if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Malformed")
            names = set()
            for item in group:
                if not isinstance(item, tuple) or len(item) != 2: raise ValueError("Malformed")
                n, e = item
                if not isinstance(n, str) or len(n) == 0: raise ValueError("Malformed")
                if n in names: raise ValueError("Duplicate name")
                names.add(n)
                self.validate(e)
            self.validate(term[2])
        elif tag == "tuple":
            if len(term) == 1:
                pass # n=0
            elif len(term) == 2:
                raise ValueError("n=1 not allowed")
            else:
                for e in term[1:]:
                    self.validate(e)
        elif tag == "proj":
            if len(term) != 4: raise ValueError("Malformed")
            i, n, e = term[1], term[2], term[3]
            if not isinstance(i, int) or isinstance(i, bool): raise ValueError("Malformed")
            if not isinstance(n, int) or isinstance(n, bool): raise ValueError("Malformed")
            if n < 2: raise ValueError("n<2")
            if i < 0 or i >= n: raise ValueError("i out of bounds")
            self.validate(e)
        else:
            raise ValueError("Unknown tag")

    def infer(self, term, env):
        if isinstance(term, int) and not isinstance(term, bool):
            return TInt
        if isinstance(term, bool):
            return TBool
        if isinstance(term, str):
            return self.lookup(term, env)
        if not isinstance(term, tuple):
            raise ValueError("Malformed")
        tag = term[0]
        if tag == "lam":
            x, body = term[1], term[2]
            x_type = self.fresh()
            new_env = {**env, x: x_type}
            body_type = self.infer(body, new_env)
            return TFun(x_type, body_type)
        if tag == "app":
            f, a = term[1], term[2]
            f_type = self.infer(f, env)
            a_type = self.infer(a, env)
            arg_type = self.fresh()
            res_type = self.fresh()
            s = self.unify(f_type, TFun(arg_type, res_type))
            return self.apply_subst(res_type, s)
        if tag == "if":
            c, t, e = term[1], term[2], term[3]
            c_type = self.infer(c, env)
            s1 = self.unify(c_type, TBool)
            t_type = self.infer(t, env)
            e_type = self.infer(e, env)
            s2 = self.unify(t_type, e_type, s1)
            return self.apply_subst(t_type, s2)
        if tag == "let":
            x, e1, e2 = term[1], term[2], term[3]
            x_type = self.infer(e1, env)
            qvars, gen_type = self.generalize(env, x_type)
            new_env = {**env, x: (qvars, gen_type)}
            return self.infer(e2, new_env)
        if tag == "letrec":
            group, body = term[1], term[2]
            group_env = {**env}
            # Assign fresh types to names in the group
            for name, _ in group:
                group_env[name] = (set(), self.fresh())

            # Infer types for each expression in the group
            group_types = {}
            for name, expr in group:
                # Note: group_env is updated as we go? 
                # The prompt says "Every name is visible in every expr of the group".
                # So we should use the full group_env for all inferences.
                # But we are building group_types.
                # We can infer all in parallel using the initial group_env.
                pass

            # Actually, we need to infer each expr with the environment containing all names.
            # Let's create a stable env for this step.
            stable_group_env = {**env}
            for name, _ in group:
                stable_group_env[name] = (set(), group_env[name][1]) # Use the fresh types assigned

            for name, expr in group:
                t = self.infer(expr, stable_group_env)
                group_types[name] = t

            # Now generalize and update env
            letrec_env = {**env}
            for name, t in group_types.items():
                qvars = self.free_vars(t) - self.free_vars_in_env(env)
                letrec_env[name] = (qvars, t)

            return self.infer(body, letrec_env)
        if tag == "tuple":
            es = term[1:]
            types = [self.infer(e, env) for e in es]
            return TTuple(types)
        if tag == "proj":
            i, n, e = term[1], term[2], term[3]
            e_type = self.infer(e, env)
            tuple_vars = [self.fresh() for _ in range(n)]
            target = TTuple(tuple_vars)
            s = self.unify(e_type, target)
            resolved = self.apply_subst(e_type, s)
            if not isinstance(resolved, TTuple):
                raise ValueError("Type mismatch")
            return resolved.types[i]
        raise ValueError("Malformed")

    def type_to_str(self, t):
        order = []
        def collect(tv):
            if isinstance(tv, TVar):
                if tv.id not in order:
                    order.append(tv.id)
            elif isinstance(tv, TFun):
                collect(tv.a)
                collect(tv.b)
            elif isinstance(tv, TList):
                collect(tv.a)
            elif isinstance(tv, TTuple):
                for x in tv.types:
                    collect(x)
        collect(t)

        mapping = {}
        idx = 0
        for vid in order:
            mapping[vid] = HMInfer.index_to_name(idx)
            idx += 1

        def build(t):
            if isinstance(t, TVar):
                return mapping[t.id]
            elif isinstance(t, TInt):
                return "Int"
            elif isinstance(t, TBool):
                return "Bool"
            elif isinstance(t, TFun):
                return f"(-> {build(t.a)} {build(t.b)})"
            elif isinstance(t, TList):
                return f"(List {build(t.a)})"
            elif isinstance(t, TTuple):
                if len(t.types) == 0:
                    return "(Tuple)"
                return f"(Tuple {' '.join(build(x) for x in t.types)})"
            return "?"
        return build(t)

    @staticmethod
    def index_to_name(i):
        if i < 0:
            return "?"
        # Count strings of length 1, 2, ...
        count = 0
        L = 1
        while True:
            num_strings = 26**L
            if i < count + num_strings:
                break
            count += num_strings
            L += 1
        n = i - count
        digits = []
        for _ in range(L):
            digits.append(n % 26)
            n //= 26
        digits.reverse()
        return ''.join(chr(ord('a') + d) for d in digits)

def group_type(term):
    # Validate first
    try:
        HMInfer().validate(term)
    except ValueError:
        raise ValueError("Malformed")

    inferer = HMInfer()
    try:
        res_type = inferer.infer(term, inferer.env)
    except ValueError:
        raise

    return inferer.type_to_str(res_type)

import sys

# --- Type Definitions ---

class Type:
    pass

class TypeVar(Type):
    def __init__(self, id):
        self.id = id
    def __repr__(self):
        return f"Var({self.id})"
    def __eq__(self, other):
        return isinstance(other, TypeVar) and self.id == other.id
    def __hash__(self):
        return self.id

class TypeFunc(Type):
    def __init__(self, left, right):
        self.left = left
        self.right = right
    def __repr__(self):
        return f"Func({self.left}, {self.right})"
    def __eq__(self, other):
        return isinstance(other, TypeFunc) and self.left == other.left and self.right == other.right
    def __hash__(self):
        return hash((self.left, self.right))

class TypeTuple(Type):
    def __init__(self, items):
        self.items = tuple(items)
    def __repr__(self):
        return f"Tuple({self.items})"
    def __eq__(self, other):
        return isinstance(other, TypeTuple) and self.items == other.items
    def __hash__(self):
        return hash(self.items)

class TypeList(Type):
    def __init__(self, elem):
        self.elem = elem
    def __repr__(self):
        return f"List({self.elem})"
    def __eq__(self, other):
        return isinstance(other, TypeList) and self.elem == other.elem
    def __hash__(self):
        return hash(self.elem)

class TypeInt(Type):
    def __repr__(self):
        return "Int"
    def __eq__(self, other):
        return isinstance(other, TypeInt)
    def __hash__(self):
        return hash("Int")

class TypeBool(Type):
    def __repr__(self):
        return "Bool"
    def __eq__(self, other):
        return isinstance(other, TypeBool)
    def __hash__(self):
        return hash("Bool")

class TypeTuple0(Type):
    def __repr__(self):
        return "Tuple0"
    def __eq__(self, other):
        return isinstance(other, TypeTuple0)
    def __hash__(self):
        return hash("Tuple0")

# --- Unification ---

def occurs(t, v):
    if t == v:
        return True
    if isinstance(t, TypeFunc):
        return occurs(t.left, v) or occurs(t.right, v)
    if isinstance(t, TypeTuple):
        return any(occurs(item, v) for item in t.items)
    if isinstance(t, TypeList):
        return occurs(t.elem, v)
    return False

def apply_subst(t, subst):
    if isinstance(t, TypeVar):
        if t in subst:
            return apply_subst(subst[t], subst)
        return t
    if isinstance(t, TypeFunc):
        return TypeFunc(apply_subst(t.left, subst), apply_subst(t.right, subst))
    if isinstance(t, TypeTuple):
        return TypeTuple([apply_subst(item, subst) for item in t.items])
    if isinstance(t, TypeList):
        return TypeList(apply_subst(t.elem, subst))
    return t

def unify(t1, t2, subst):
    t1 = apply_subst(t1, subst)
    t2 = apply_subst(t2, subst)

    if isinstance(t1, TypeVar):
        if t1 in subst:
            return unify(subst[t1], t2, subst)
        if occurs(t1, t2):
            raise ValueError("Infinite type")
        subst[t1] = t2
        return t2

    if isinstance(t2, TypeVar):
        if t2 in subst:
            return unify(t1, subst[t2], subst)
        if occurs(t2, t1):
            raise ValueError("Infinite type")
        subst[t2] = t1
        return t1

    if isinstance(t1, TypeFunc) and isinstance(t2, TypeFunc):
        unify(t1.left, t2.left, subst)
        return unify(t1.right, t2.right, subst)

    if isinstance(t1, TypeTuple) and isinstance(t2, TypeTuple):
        if len(t1.items) != len(t2.items):
            raise ValueError("Tuple length mismatch")
        for i in range(len(t1.items)):
            unify(t1.items[i], t2.items[i], subst)
        return t1

    if isinstance(t1, TypeList) and isinstance(t2, TypeList):
        unify(t1.elem, t2.elem, subst)
        return t1

    if isinstance(t1, TypeInt) and isinstance(t2, TypeInt):
        return t1
    if isinstance(t1, TypeBool) and isinstance(t2, TypeBool):
        return t1
    if isinstance(t1, TypeTuple0) and isinstance(t2, TypeTuple0):
        return t1

    raise ValueError("Type mismatch")

# --- Scheme ---

class Scheme:
    def __init__(self, vars, type):
        self.vars = tuple(vars)
        self.type = type

# --- Helpers ---

_counter = 0
def fresh_var():
    global _counter
    v = TypeVar(_counter)
    _counter += 1
    return v

def free_vars(t):
    if isinstance(t, TypeVar):
        return {t}
    if isinstance(t, TypeFunc):
        return free_vars(t.left) | free_vars(t.right)
    if isinstance(t, TypeTuple):
        res = set()
        for item in t.items:
            res |= free_vars(item)
        return res
    if isinstance(t, TypeList):
        return free_vars(t.elem)
    return set()

def env_vars(env):
    res = set()
    for scope in env:
        for scheme in scope.values():
            res |= set(scheme.vars)
    return res

def generalize(type, env):
    fv = free_vars(type)
    ev = env_vars(env)
    gen_vars = fv - ev
    return Scheme(tuple(gen_vars), type)

def instantiate(scheme):
    subst = {}
    for v in scheme.vars:
        new_v = fresh_var()
        subst[v] = new_v
    return apply_subst(scheme.type, subst)

def get_name(idx):
    chars = "abcdefghijklmnopqrstuvwxyz"
    idx += 1
    res = []
    while idx > 0:
        idx -= 1
        res.append(chars[idx % 26])
        idx //= 26
    return "".join(reversed(res))

def collect_vars(t, seen):
    if isinstance(t, TypeVar):
        if t not in seen:
            seen.add(t)
            return [t]
        return []
    if isinstance(t, TypeFunc):
        res = collect_vars(t.left, seen)
        res += collect_vars(t.right, seen)
        return res
    if isinstance(t, TypeTuple):
        res = []
        for item in t.items:
            res += collect_vars(item, seen)
        return res
    if isinstance(t, TypeList):
        return collect_vars(t.elem, seen)
    return []

def print_type(t, var_map):
    if isinstance(t, TypeVar):
        return var_map[t]
    if isinstance(t, TypeFunc):
        return f"(-> {print_type(t.left, var_map)} {print_type(t.right, var_map)})"
    if isinstance(t, TypeTuple):
        items = " ".join(print_type(item, var_map) for item in t.items)
        return f"(Tuple {items})"
    if isinstance(t, TypeList):
        return f"(List {print_type(t.elem, var_map)})"
    if isinstance(t, TypeInt):
        return "Int"
    if isinstance(t, TypeBool):
        return "Bool"
    if isinstance(t, TypeTuple0):
        return "(Tuple)"
    return "Unknown"

# --- Inference ---

def infer(term, env, subst):
    # term validation and inference
    if isinstance(term, int):
        if isinstance(term, bool):
            raise ValueError("Malformed term: bool is not Int")
        return TypeInt()

    if isinstance(term, bool):
        return TypeBool()

    if isinstance(term, str):
        if not term:
            raise ValueError("Malformed term: empty variable name")
        # lookup
        for scope in reversed(env):
            if term in scope:
                scheme = scope[term]
                return instantiate(scheme)
        raise ValueError(f"Unbound variable: {term}")

    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")

    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed term: non-str tag")

    if tag == "lam":
        if len(term) != 3:
            raise ValueError("Malformed term: lam length")
        x, body = term[1], term[2]
        if not isinstance(x, str) or not x:
            raise ValueError("Malformed term: lam param")
        # lambda params are monomorphic
        xa = fresh_var()
        new_env = env + [{x: Scheme((), xa)}]
        tb = infer(body, new_env, subst)
        return TypeFunc(xa, tb)

    if tag == "app":
        if len(term) != 3:
            raise ValueError("Malformed term: app length")
        f, a = term[1], term[2]
        tf = infer(f, env, subst)
        ta = infer(a, env, subst)
        tr = fresh_var()
        unify(tf, TypeFunc(ta, tr), subst)
        return tr

    if tag == "if":
        if len(term) != 4:
            raise ValueError("Malformed term: if length")
        c, t, e = term[1], term[2], term[3]
        tc = infer(c, env, subst)
        unify(tc, TypeBool(), subst)
        tt = infer(t, env, subst)
        te = infer(e, env, subst)
        unify(tt, te, subst)
        return tt

    if tag == "let":
        if len(term) != 4:
            raise ValueError("Malformed term: let length")
        x, e1, e2 = term[1], term[2], term[3]
        if not isinstance(x, str) or not x:
            raise ValueError("Malformed term: let name")
        t1 = infer(e1, env, subst)
        scheme = generalize(t1, env)
        new_env = env + [{x: scheme}]
        return infer(e2, new_env, subst)

    if tag == "letrec":
        if len(term) != 3:
            raise ValueError("Malformed term: letrec length")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or len(group) == 0:
            raise ValueError("Malformed term: letrec group")
        names = []
        exprs = []
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2:
                raise ValueError("Malformed term: letrec pair")
            n, e = item
            if not isinstance(n, str) or not n:
                raise ValueError("Malformed term: letrec name")
            if n in names:
                raise ValueError("Malformed term: letrec duplicate name")
            names.append(n)
            exprs.append(e)

        # Create fresh vars for names
        type_vars = [fresh_var() for _ in names]
        # Extend env with monomorphic vars
        # "monomorphic there" means they are just vars, not generalized schemes
        # But we need to put them in env so they can be looked up.
        # We can put them as schemes with empty quantification?
        # Or just as vars in a special way?
        # Standard approach: put fresh vars in env.
        # Since they are monomorphic, they shouldn't be generalized inside.
        # But for lookup, we need a Scheme.
        # Scheme((), v) means monomorphic v.
        scope = {n: Scheme((), v) for n, v in zip(names, type_vars)}
        new_env = env + [scope]

        # Infer types for expressions
        inferred_types = []
        for e in exprs:
            t = infer(e, new_env, subst)
            inferred_types.append(t)

        # Unify fresh vars with inferred types
        for v, t in zip(type_vars, inferred_types):
            unify(v, t, subst)

        # Now generalize each name's type over vars not free in env outside group
        # "environment outside the group" is `env`
        # But wait, `env` might contain vars that are free in the types?
        # Yes.
        # We need to generalize each inferred type t_i over free_vars(t_i) - env_vars(env)

        final_env = env + [scope] # scope has the vars, but we want to replace with generalized schemes
        # Actually, we construct a new scope with generalized schemes
        final_scope = {}
        for n, t in zip(names, inferred_types):
            # Generalize over vars not in env (original env)
            # But wait, the type t might contain vars that were introduced in the group?
            # No, the vars in type_vars are unified into t.
            # So t is the type of the name.
            # We generalize t.
            scheme = generalize(t, env)
            final_scope[n] = scheme

        new_env_final = env + [final_scope]
        return infer(body, new_env_final, subst)

    if tag == "tuple":
        # e1, ..., en
        # len(term) - 1 elements
        items = term[1:]
        n = len(items)
        if n == 1:
            raise ValueError("Malformed term: tuple length 1")
        # n=0 allowed (empty tuple), n>=2 allowed
        # if n=0, items is empty
        if n > 0:
            types = [infer(e, env, subst) for e in items]
            return TypeTuple(types)
        else:
            return TypeTuple0()

    if tag == "proj":
        if len(term) != 4:
            raise ValueError("Malformed term: proj length")
        i, n, e = term[1], term[2], term[3]
        if isinstance(i, bool) or isinstance(n, bool):
            raise ValueError("Malformed term: proj indices")
        if not isinstance(i, int) or not isinstance(n, int):
            raise ValueError("Malformed term: proj indices")
        if n < 2:
            raise ValueError("Malformed term: proj n")
        if i < 0 or i >= n:
            raise ValueError("Malformed term: proj i")

        te = infer(e, env, subst)
        # Unify te with Tuple(t1, ..., tn)
        ts = [fresh_var() for _ in range(n)]
        unify(te, TypeTuple(ts), subst)
        return ts[i]

    raise ValueError(f"Unknown tag: {tag}")

def group_type(term):
    global _counter
    _counter = 0
    env = [
        {
            "add": Scheme((), TypeFunc(TypeInt(), TypeFunc(TypeInt(), TypeInt()))),
            "eq": Scheme((fresh_var(),), TypeFunc(TypeVar(0), TypeFunc(TypeVar(0), TypeBool()))), # Wait, fresh_var creates new id. Need to link.
            # Better: create vars and link them in scheme
        }
    ]
    # Re-do builtins properly
    # eq: a -> a -> Bool
    va = fresh_var()
    eq_scheme = Scheme((va,), TypeFunc(va, TypeFunc(va, TypeBool())))

    # nil: List a
    vb = fresh_var()
    nil_scheme = Scheme((vb,), TypeList(vb))

    # cons: a -> List a -> List a
    # Need fresh var for cons? Or reuse?
    # Scheme vars are distinct.
    vc = fresh_var()
    cons_scheme = Scheme((vc,), TypeFunc(vc, TypeFunc(TypeList(vc), TypeList(vc))))

    # head: List a -> a
    vd = fresh_var()
    head_scheme = Scheme((vd,), TypeFunc(TypeList(vd), vd))

    # tail: List a -> List a
    ve = fresh_var()
    tail_scheme = Scheme((ve,), TypeFunc(TypeList(ve), TypeList(ve)))

    # isnil: List a -> Bool
    vf = fresh_var()
    isnil_scheme = Scheme((vf,), TypeFunc(TypeList(vf), TypeBool()))

    env = [{
        "add": Scheme((), TypeFunc(TypeInt(), TypeFunc(TypeInt(), TypeInt()))),
        "eq": eq_scheme,
        "nil": nil_scheme,
        "cons": cons_scheme,
        "head": head_scheme,
        "tail": tail_scheme,
        "isnil": isnil_scheme
    }]

    subst = {}
    try:
        res_type = infer(term, env, subst)
    except ValueError:
        raise

    # Apply final substitution
    res_type = apply_subst(res_type, subst)

    # Collect and name vars
    seen = set()
    vars_list = collect_vars(res_type, seen)
    var_map = {v: get_name(i) for i, v in enumerate(vars_list)}

    return print_type(res_type, var_map)

import sys

class TypeInferer:
    def __init__(self):
        self.fresh_counter = 0
        self.subst = {}
        self.env = {}

        # Built-in functions
        self.env['add'] = (('func', ('func', ('int',), ('int',)), ('int',)), set())
        v_eq = self.fresh()
        self.env['eq'] = (('func', ('func', ('var', v_eq), ('var', v_eq)), ('bool',)), {v_eq})
        v_nil = self.fresh()
        self.env['nil'] = (('list', ('var', v_nil)), {v_nil})
        v_cons = self.fresh()
        self.env['cons'] = (('func', ('var', v_cons), ('func', ('list', ('var', v_cons)), ('list', ('var', v_cons)))), {v_cons})
        v_head = self.fresh()
        self.env['head'] = (('func', ('list', ('var', v_head)), ('var', v_head)), {v_head})
        v_tail = self.fresh()
        self.env['tail'] = (('func', ('list', ('var', v_tail)), ('list', ('var', v_tail))), {v_tail})
        v_isnil = self.fresh()
        self.env['isnil'] = (('func', ('list', ('var', v_isnil)), ('bool',)), {v_isnil})

    def fresh(self):
        self.fresh_counter += 1
        return ('var', self.fresh_counter)

    def apply_subst(self, t):
        if t[0] == 'var':
            while t[1] in self.subst:
                t = self.subst[t[1]]
            return t
        elif t[0] == 'tuple':
            return ('tuple', *[self.apply_subst(arg) for arg in t[1:]])
        elif t[0] == 'func':
            return ('func', self.apply_subst(t[1]), self.apply_subst(t[2]))
        elif t[0] == 'list':
            return ('list', self.apply_subst(t[1]))
        return t

    def free_vars(self, t):
        t = self.apply_subst(t)
        if t[0] == 'var': return {t[1]}
        elif t[0] == 'tuple':
            res = set()
            for arg in t[1:]: res |= self.free_vars(arg)
            return res
        elif t[0] == 'func':
            return self.free_vars(t[1]) | self.free_vars(t[2])
        elif t[0] == 'list':
            return self.free_vars(t[1])
        return set()

    def env_free_vars(self):
        res = set()
        for t, gen_vars in self.env.values():
            res |= self.free_vars(t) - gen_vars
        return res

    def occurs(self, id, t):
        t = self.apply_subst(t)
        if t[0] == 'var': return t[1] == id
        elif t[0] == 'tuple':
            return any(self.occurs(id, arg) for arg in t[1:])
        elif t[0] == 'func':
            return self.occurs(id, t[1]) or self.occurs(id, t[2])
        elif t[0] == 'list':
            return self.occurs(id, t[1])
        return False

    def unify(self, t1, t2):
        t1 = self.apply_subst(t1)
        t2 = self.apply_subst(t2)
        if t1 == t2: return
        if t1[0] == 'var':
            if t1[1] in self.subst: self.unify(self.subst[t1[1]], t2)
            else:
                if self.occurs(t1[1], t2): raise ValueError("Infinite type")
                self.subst[t1[1]] = t2
        elif t2[0] == 'var':
            if t2[1] in self.subst: self.unify(t1, self.subst[t2[1]])
            else:
                if self.occurs(t2[1], t1): raise ValueError("Infinite type")
                self.subst[t2[1]] = t1
        elif t1[0] == 'tuple' and t2[0] == 'tuple':
            if len(t1) != len(t2): raise ValueError("Type mismatch")
            for a, b in zip(t1[1:], t2[1:]): self.unify(a, b)
        elif t1[0] == 'func' and t2[0] == 'func':
            self.unify(t1[1], t2[1])
            self.unify(t1[2], t2[2])
        elif t1[0] == 'list' and t2[0] == 'list':
            self.unify(t1[1], t2[1])
        else: raise ValueError("Type mismatch")

    def instantiate(self, t, gen_vars):
        inst = {}
        for v in gen_vars:
            inst[v] = self.fresh()
        return self.apply_subst_with_dict(t, inst)

    def apply_subst_with_dict(self, t, subst):
        if t[0] == 'var':
            if t[1] in subst: return self.apply_subst_with_dict(subst[t[1]], subst)
            return t
        elif t[0] == 'tuple':
            return ('tuple', *[self.apply_subst_with_dict(arg, subst) for arg in t[1:]])
        elif t[0] == 'func':
            return ('func', self.apply_subst_with_dict(t[1], subst), self.apply_subst_with_dict(t[2], subst))
        elif t[0] == 'list':
            return ('list', self.apply_subst_with_dict(t[1], subst))
        return t

    def infer(self, term):
        if isinstance(term, int) and not isinstance(term, bool):
            return ('int',)
        if term is True or term is False:
            return ('bool',)
        if isinstance(term, str) and len(term) > 0:
            if term not in self.env:
                raise ValueError("Unbound variable")
            t, gen_vars = self.env[term]
            return self.instantiate(t, gen_vars)

        if isinstance(term, tuple) and len(term) >= 1 and isinstance(term[0], str):
            tag = term[0]
            if tag == 'lam':
                if len(term) != 3: raise ValueError("Malformed")
                x, body = term[1], term[2]
                if not isinstance(x, str) or len(x) == 0: raise ValueError("Malformed")
                fresh_t = self.fresh()
                new_env = {**self.env, x: (fresh_t, set())}
                old_env, old_subst = self.env, self.subst
                self.env = new_env
                t_body = self.infer(body)
                self.env, self.subst = old_env, old_subst
                return ('func', fresh_t, t_body)
            elif tag == 'app':
                if len(term) != 3: raise ValueError("Malformed")
                f, a = term[1], term[2]
                tf = self.infer(f)
                ta = self.infer(a)
                tr = self.fresh()
                self.unify(tf, ('func', ta, tr))
                return tr
            elif tag == 'if':
                if len(term) != 4: raise ValueError("Malformed")
                c, t, e = term[1], term[2], term[3]
                tc = self.infer(c)
                self.unify(tc, ('bool',))
                tt = self.infer(t)
                te = self.infer(e)
                self.unify(tt, te)
                return tt
            elif tag == 'let':
                if len(term) != 4: raise ValueError("Malformed")
                x, e1, e2 = term[1], term[2], term[3]
                if not isinstance(x, str) or len(x) == 0: raise ValueError("Malformed")
                t1 = self.infer(e1)
                fvs = self.free_vars(t1)
                env_fvs = self.env_free_vars()
                gen = fvs - env_fvs
                old_env = self.env
                self.env = {**self.env, x: (t1, gen)}
                res = self.infer(e2)
                self.env = old_env
                return res
            elif tag == 'letrec':
                if len(term) != 3: raise ValueError("Malformed")
                group, body = term[1], term[2]
                if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Malformed")
                names = []
                types = {}
                for pair in group:
                    if not isinstance(pair, tuple) or len(pair) != 2: raise ValueError("Malformed")
                    n, expr = pair
                    if not isinstance(n, str) or len(n) == 0: raise ValueError("Malformed")
                    if n in names: raise ValueError("Duplicate name")
                    names.append(n)
                    types[n] = self.fresh()
                new_env = {**self.env, **{n: (types[n], set()) for n in names}}
                old_env, old_subst = self.env, self.subst
                self.env = new_env
                for n, expr in group:
                    self.infer(expr)
                final_env = {}
                for n in names:
                    t_n = self.apply_subst(types[n])
                    fvs = self.free_vars(t_n)
                    env_fvs = self.env_free_vars()
                    gen = fvs - env_fvs
                    final_env[n] = (t_n, gen)
                self.env = final_env
                res = self.infer(body)
                self.env, self.subst = old_env, old_subst
                return res
            elif tag == 'tuple':
                args = term[1:]
                n = len(args)
                if n == 1: raise ValueError("Malformed")
                types = [self.infer(arg) for arg in args]
                return ('tuple', *types)
            elif tag == 'proj':
                if len(term) != 4: raise ValueError("Malformed")
                i, n, e = term[1], term[2], term[3]
                if isinstance(i, bool) or isinstance(n, bool) or not isinstance(i, int) or not isinstance(n, int):
                    raise ValueError("Malformed")
                if n < 2 or i < 0 or i >= n:
                    raise ValueError("Malformed")
                te = self.infer(e)
                ts = tuple(self.fresh() for _ in range(n))
                self.unify(te, ('tuple', *ts))
                return ts[i]
            else:
                raise ValueError("Unknown tag")
        raise ValueError("Malformed")

    def print_type(self, t):
        t = self.apply_subst(t)
        seen = []
        var_map = {}
        counter = [0]

        def next_letter():
            counter[0] += 1
            n = counter[0]
            res = ""
            while n > 0:
                n, rem = divmod(n - 1, 26)
                res = chr(ord('a') + rem) + res
            return res

        def helper(tt):
            if tt[0] == 'var':
                vid = tt[1]
                if vid not in var_map:
                    var_map[vid] = next_letter()
                    seen.append(vid)
                return var_map[vid]
            elif tt[0] == 'tuple':
                if len(tt) == 1: return "(Tuple)"
                parts = [helper(arg) for arg in tt[1:]]
                return "(Tuple " + " ".join(parts) + ")"
            elif tt[0] == 'func':
                return "(-> " + helper(tt[1]) + " " + helper(tt[2]) + ")"
            elif tt[0] == 'list':
                return "(List " + helper(tt[1]) + ")"
            elif tt[0] == 'int': return "Int"
            elif tt[0] == 'bool': return "Bool"
            return "?"

        return helper(t)

def group_type(term):
    inferer = TypeInferer()
    try:
        t = inferer.infer(term)
        return inferer.print_type(t)
    except ValueError:
        raise
    except Exception:
        raise ValueError("Malformed")

