                t1 = self.infer(e1)
                fvs = self.free_vars(t1)
                env_fvs = self.env_free_vars(self.env)
                gen = fvs - env_fvs
                old_env = self.env
                self.env = {**self.env, x: (t1, gen)}
                res = self.infer(e2)
                self.env = old_env
                return res
