                group, body = term[1], term[2]
                if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Malformed")
                names = []
                types = {}
                for pair in group:
                    if not isinstance(pair, tuple) or len(pair) != 2: raise ValueError("Malformed")
                    n, expr = pair
                    if not isinstance(n, str) or len(n) == 0: raise ValueError("Malformed")
                    if n in names: raise ValueError("Duplicate name")
                    names.append(n)
                    types[n] = self.fresh()
                old_env = self.env
                new_env = {**self.env, **{n: (types[n], set()) for n in names}}
                self.env = new_env
                for n, expr in group:
                    self.infer(expr)

                # Compute outer environment free vars
                outer_fvs = self.env_free_vars(old_env)

                final_env = {}
                for n in names:
                    t_n = self.apply_subst(types[n])
                    fvs = self.free_vars(t_n)
                    gen = fvs - outer_fvs
                    final_env[n] = (t_n, gen)

                self.env = final_env
                res = self.infer(body)
                self.env = old_env
                return res
            elif tag == 'tuple':
                args = term[1:]
                n = len(args)
                if n == 1: raise ValueError("Malformed")
                types = [self.infer(arg) for arg in args]
                return ('tuple', *types)
            elif tag == 'proj':
                if len(term) != 4: raise ValueError("Malformed")
                i, n, e = term[1], term[2], term[3]
                if isinstance(i, bool) or isinstance(n, bool) or not isinstance(i, int) or not isinstance(n, int):
                    raise ValueError("Malformed")
                if n < 2 or i < 0 or i >= n:
                    raise ValueError("Malformed")
                te = self.infer(e)
                ts = tuple(self.fresh() for _ in range(n))
                self.unify(te, ('tuple', *ts))
                return ts[i]
            else:
                raise ValueError("Unknown tag")
        raise ValueError("Malformed")

    def print_type(self, t):
        t = self.apply_subst(t)
        seen = []
        var_map = {}
        counter = [0]

        def next_letter():
            counter[0] += 1
            n = counter[0]
            res = ""
            while n > 0:
                n, rem = divmod(n - 1, 26)
                res = chr(ord('a') + rem) + res
            return res

        def helper(tt):
            if tt[0] == 'var':
                vid = tt[1]
                if vid not in var_map:
                    var_map[vid] = next_letter()
                    seen.append(vid)
                return var_map[vid]
            elif tt[0] == 'tuple':
                if len(tt) == 1: return "(Tuple)"
                parts = [helper(arg) for arg in tt[1:]]
                return "(Tuple " + " ".join(parts) + ")"
            elif tt[0] == 'func':
                return "(-> " + helper(tt[1]) + " " + helper(tt[2]) + ")"
            elif tt[0] == 'list':
                return "(List " + helper(tt[1]) + ")"
            elif tt[0] == 'int': return "Int"
            elif tt[0] == 'bool': return "Bool"
            return "?"

        return helper(t)

