def infer(term, env):
    if isinstance(term, bool): return BoolType()
    if isinstance(term, int): return IntType()
    if isinstance(term, str):
        if not term: raise ValueError("Empty string")
        for frame in reversed(env):
            if term in frame:
                return inst(frame[term])
        raise ValueError("Unbound variable")
    if not isinstance(term, tuple): raise ValueError("Malformed term")
    if len(term) == 0: raise ValueError("Empty tuple")
    tag = term[0]
    if not isinstance(tag, str): raise ValueError("Bad tag")

    if tag == "lam":
        if len(term) != 3: raise ValueError("Lam length")
        x, body = term[1], term[2]
        if not isinstance(x, str) or not x: raise ValueError("Bad param name")
        param_t = fresh_tvar()
        new_env = env + [ {x: mk_scheme((), param_t)} ]
        return FuncType(param_t, infer(body, new_env))

    if tag == "app":
        if len(term) != 3: raise ValueError("App length")
        f, a = term[1], term[2]
        f_t = infer(f, env)
        a_t = infer(a, env)
        ret_t = fresh_tvar()
        unify(f_t, FuncType(a_t, ret_t), {})
        return ret_t

    if tag == "if":
        if len(term) != 4: raise ValueError("If length")
        c, t, e = term[1], term[2], term[3]
        unify(infer(c, env), BoolType(), {})
        t_t = infer(t, env)
        e_t = infer(e, env)
        unify(t_t, e_t, {})
        return t_t

    if tag == "let":
        if len(term) != 4: raise ValueError("Let length")
        x, e1, e2 = term[1], term[2], term[3]
        if not isinstance(x, str) or not x: raise ValueError("Bad let name")
        e1_t = infer(e1, env)
        scheme = gen(env, e1_t)
        new_env = env + [ {x: scheme} ]
        return infer(e2, new_env)

    if tag == "letrec":
        if len(term) != 3: raise ValueError("Letrec length")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Bad group")
        names, exprs = [], []
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2: raise ValueError("Bad group item")
            n, e = item
            if not isinstance(n, str) or not n: raise ValueError("Bad name")
            names.append(n)
            exprs.append(e)
        if len(set(names)) != len(names): raise ValueError("Duplicate names")
        outer_env = env
        name_types = {n: fresh_tvar() for n in names}
        rec_env = env + [ {n: mk_scheme((), t) for n, t in name_types.items()} ]
        subst = {}
        for n, e in zip(names, exprs):
            e_t = infer(e, rec_env)
            unify(name_types[n], e_t, subst)
        rec_scheme = {}
        for n, t in name_types.items():
            rec_scheme[n] = gen(outer_env, t)
        final_env = outer_env + [rec_scheme]
        return infer(body, final_env)

    if tag == "tuple":
        es = term[1:]
        if len(es) == 1: raise ValueError("Tuple size 1")
        ts = [infer(e, env) for e in es]
        return TupleType(*ts)

    if tag == "proj":
        if len(term) != 4: raise ValueError("Proj length")
        i, n, e = term[1], term[2], term[3]
        if not isinstance(i, int) or isinstance(i, bool): raise ValueError("Bad i")
        if not isinstance(n, int) or isinstance(n, bool): raise ValueError("Bad n")
        if n < 2: raise ValueError("n < 2")
        if i < 0 or i >= n: raise ValueError("i out of bounds")
        e_t = infer(e, env)
        fresh_ts = [fresh_tvar() for _ in range(n)]
        s = unify(e_t, TupleType(*fresh_ts), {})
        e_t = apply_subst(s, e_t)
        return e_t.args[i]

    raise ValueError("Unknown tag")

def group_type(term):
    fresh_tvar.counter = 0
    env = [PREDEFINED]
    t = infer(term, env)
    return type_to_str(t)

