        return subst

    if t1.kind == 'tuple':
        if len(t1.args) != len(t2.args):
            raise ValueError("Tuple size mismatch")
        for a, b in zip(t1.args, t2.args):
            unify(a, b, subst)
        return subst

    if t1.kind == 'list':
        unify(t1.args[0], t2.args[0], subst)
        return subst

    return subst

def free_vars(t):
    if isinstance(t, TVar): return {t}
    return set().union(*(free_vars(a) for a in t.args))

def gen(env, t):
    t_fvs = free_vars(t)
    env_fvs = set()
    for frame in env:
        for scheme in frame.values():
            env_fvs.update(free_vars(scheme[1]))
    generalizable = t_fvs - env_fvs
    return (generalizable, t)

def inst(scheme):
    bvs, ty = scheme
    new_binds = {v: fresh_tvar() for v in bvs}
    return apply_subst(new_binds, ty)

def tvar_name(idx):
    chars = 'abcdefghijklmnopqrstuvwxyz'
    res = []
    idx += 1
    while idx > 0:
        idx -= 1
        res.append(chars[idx % 26])
        idx //= 26
    return ''.join(reversed(res))

def type_to_str(t):
    names = {}
    idx = 0
    def get_name(v):
        nonlocal idx
        if v not in names:
            names[v] = tvar_name(idx)
            idx += 1
        return names[v]

    def to_sexpr(t):
        if isinstance(t, TVar):
            return get_name(t)
        if t.kind == 'int': return 'Int'
        if t.kind == 'bool': return 'Bool'
        if t.kind == 'list': return f'(List {to_sexpr(t.args[0])})'
        if t.kind == 'tuple':
            if len(t.args) == 0: return '(Tuple)'
            return f'(Tuple {" ".join(to_sexpr(a) for a in t.args)})'
        if t.kind == 'func':
            return f'(-> {to_sexpr(t.args[0])} {to_sexpr(t.args[1])})'
        return str(t)
    return to_sexpr(t)

def mk_scheme(bound_vars, ty):
    return (frozenset(bound_vars), ty)

