        self.name = name
        self.link = None

_var_counter = 0

def _fresh():
    global _var_counter
    name = _to_name(_var_counter)
    _var_counter += 1
    return TypeVar(name)

def _to_name(n):
    if n < 26:
        return chr(ord('a') + n)
    return _to_name(n // 26 - 1) + chr(ord('a') + n % 26)

def _find(v):
    while v.link is not None:
        v = v.link
    return v

def _occurs(v, t):
    t = _find(t)
    if t is v:
        return True
    if isinstance(t, TypeVar):
        return False
    if isinstance(t, FuncType):
        return _occurs(v, t.arg) or _occurs(v, t.ret)
    if isinstance(t, ListType):
        return _occurs(v, t.elem)
    if isinstance(t, TupleType):
        return any(_occurs(v, e) for e in t.elems)
    return False

def _unify(t1, t2):
    t1, t2 = _find(t1), _find(t2)
    if t1 is t2:
        return
    if isinstance(t1, TypeVar):
        if _occurs(t1, t2):
            raise ValueError("infinite type")
        t1.link = t2
    elif isinstance(t2, TypeVar):
        if _occurs(t2, t1):
            raise ValueError("infinite type")
        t2.link = t1
    elif type(t1) is type(t2):
        if isinstance(t1, FuncType):
            _unify(t1.arg, t2.arg)
            _unify(t1.ret, t2.ret)
        elif isinstance(t1, ListType):
            _unify(t1.elem, t2.elem)
        elif isinstance(t1, TupleType):
            if len(t1.elems) != len(t2.elems):
                raise ValueError("tuple size mismatch")
            for a, b in zip(t1.elems, t2.elems):
                _unify(a, b)
        else:
            raise ValueError("type mismatch")
    else:
        raise ValueError("type mismatch")

def _free_vars(t):
    if isinstance(t, TypeVar):
        return {_find(t)}
    elif isinstance(t, FuncType):
        return _free_vars(t.arg) | _free_vars(t.ret)
    elif isinstance(t, ListType):
        return _free_vars(t.elem)
    elif isinstance(t, TupleType):
        result = set()
        for e in t.elems:
            result |= _free_vars(e)
        return result
    else:
        return set()

def _instantiate(t):
    if isinstance(t, TypeVar):
        return _fresh()
    elif isinstance(t, FuncType):
        return FuncType(_instantiate(t.arg), _instantiate(t.ret))
    elif isinstance(t, ListType):
        return ListType(_instantiate(t.elem))
    elif isinstance(t, TupleType):
        return TupleType(tuple(_instantiate(e) for e in t.elems))
    else:
        return t

def _free_vars_from_env(env):
    result = set()
    for t, _ in env.values():
        result |= _free_vars(t)
    return result

def _validate(term):
    if isinstance(term, bool):
        return ("Bool",)
    if isinstance(term, int):
        return ("Int",)
    if isinstance(term, str):
        if len(term) == 0:
            raise ValueError("empty str")
        return ("Var", term)
    if isinstance(term, tuple):
