            if not isinstance(group, tuple) or len(group) == 0:
                raise ValueError("letrec group")
            validated_group = []
            names = set()
            for pair in group:
                if not isinstance(pair, tuple) or len(pair) != 2:
                    raise ValueError("letrec pair")
                n, e = pair
                if not isinstance(n, str) or len(n) == 0:
                    raise ValueError("letrec name")
                if n in names:
                    raise ValueError("letrec duplicate")
                names.add(n)
                validated_group.append((n, _validate(e)))
            return ("Letrec", tuple(validated_group), _validate(body))
