            return ("Tuple", tuple(elems))
        elif tag == "proj":
            if len(term) != 4:
                raise ValueError("proj length")
            i, n, e = term[1], term[2], term[3]
            if isinstance(i, bool) or not isinstance(i, int):
                raise ValueError("proj i")
            if isinstance(n, bool) or not isinstance(n, int):
                raise ValueError("proj n")
            if n < 2:
                raise ValueError("proj n < 2")
            if not (0 <= i < n):
                raise ValueError("proj i")
            return ("Proj", i, n, _validate(e))
        else:
