    raise ValueError("malformed")

def _infer(term, env):
    tag = term[0]
    if tag == "Int":
        return IntType()
    if tag == "Bool":
        return BoolType()
    if tag == "Var":
        name = term[1]
        if name not in env:
            raise ValueError(f"unbound variable {name}")
        t, is_poly = env[name]
        if is_poly:
            return _instantiate(t)
        return t
    if tag == "Lam":
        x, body = term[1], term[2]
        tv = _fresh()
        env2 = {**env, x: (tv, False)}
        ret = _infer(body, env2)
        return FuncType(tv, ret)
    if tag == "App":
        f, a = term[1], term[2]
        tf = _infer(f, env)
        ta = _infer(a, env)
        tr = _fresh()
        _unify(tf, FuncType(ta, tr))
        return tr
    if tag == "If":
        c, t, e = term[1], term[2], term[3]
        tc = _infer(c, env)
        _unify(tc, BoolType())
        tt = _infer(t, env)
        te = _infer(e, env)
        _unify(tt, te)
        return tt
    if tag == "Let":
        x, e1, e2 = term[1], term[2], term[3]
        t1 = _infer(e1, env)
        forbidden = _free_vars_from_env(env)
        # Generalization: keep t1 as is, mark as polymorphic
        env2 = {**env, x: (t1, True)}
        return _infer(e2, env2)
    if tag == "Letrec":
        group, body = term[1], term[2]
        env0 = dict(env)
        vars_map = {}
        for name, _ in group:
            vars_map[name] = _fresh()
        for name, tv in vars_map.items():
            env0[name] = (tv, False)
        type_map = {}
        for name, expr in group:
            type_map[name] = _infer(expr, env0)
        for name, tv in vars_map.items():
            _unify(tv, type_map[name])
        forbidden = _free_vars_from_env(env)
        poly_map = {}
        for name, tv in vars_map.items():
            t = _find(tv)
            poly_map[name] = (t, True)
        env1 = {**env, **poly_map}
        return _infer(body, env1)
    if tag == "Tuple":
        elems = [_infer(e, env) for e in term[1:]]
        return TupleType(tuple(elems))
    if tag == "Proj":
        i, n, e = term[1], term[2], term[3]
        te = _infer(e, env)
        if isinstance(te, TypeVar):
            te = _find(te)
        if not isinstance(te, TupleType):
            raise ValueError("proj on non-tuple")
        if len(te.elems) != n:
            raise ValueError("proj size mismatch")
        return te.elems[i]
    raise ValueError("unknown tag")

def _to_string(t):
    if isinstance(t, IntType):
        return "Int"
    if isinstance(t, BoolType):
        return "Bool"
    if isinstance(t, TypeVar):
        return t.name
    if isinstance(t, ListType):
        return f"(List {_to_string(t.elem)})"
    if isinstance(t, TupleType):
        if len(t.elems) == 0:
            return "(Tuple)"
        return f"(Tuple {' '.join(_to_string(e) for e in t.elems)})"
    if isinstance(t, FuncType):
        return f"({_to_string(t.arg)} -> {_to_string(t.ret)})"
    return str(t)

