            f, a = term[1], term[2]
            return ("App", _validate(f), _validate(a))
        elif tag == "if":
            if len(term) != 4:
                raise ValueError("if length")
            c, t, e = term[1], term[2], term[3]
            return ("If", _validate(c), _validate(t), _validate(e))
