                n, e = pair
                if not isinstance(n, str) or len(n) == 0:
                    raise ValueError("letrec name")
                if n in names:
                    raise ValueError("letrec duplicate")
                names.add(n)
                validated_group.append((n, _validate(e)))
            return ("Letrec", tuple(validated_group), _validate(body))
        elif tag == "tuple":
            n = len(term) - 1
            if n == 1:
                raise ValueError("tuple size 1")
            elems = [_validate(e) for e in term[1:]]
            return ("Tuple", tuple(elems))
        elif tag == "proj":
            if len(term) != 4:
                raise ValueError("proj length")
            i, n, e = term[1], term[2], term[3]
            if isinstance(i, bool) or not isinstance(i, int):
                raise ValueError("proj i")
            if isinstance(n, bool) or not isinstance(n, int):
                raise ValueError("proj n")
            if n < 2:
                raise ValueError("proj n < 2")
            if not (0 <= i < n):
