        for name, expr in group:
            t = _infer(expr, env0)
            _unify(fresh_vars[name], t)
            type_map[name] = _find(fresh_vars[name])

        forbidden = _free_vars_from_env(env)
        poly_env = {}
        for name, tv in fresh_vars.items():
            t = _find(tv)
            poly_vars = _free_vars(t) - forbidden
            if poly_vars:
                subst = {v: _fresh() for v in poly_vars}
                t_gen = _apply_subst(t, subst)
            else:
                t_gen = t
            poly_env[name] = (t_gen, True)

        env1 = {**env, **poly_env}
        return _infer(body, env1)
    if tag == "Tuple":
        elems = [_infer(e, env) for e in term[1:]]
        return TupleType(tuple(elems))
    if tag == "Proj":
        i, n, e = term[1], term[2], term[3]
        te = _infer(e, env)
        if isinstance(te, TypeVar):
            te = _find(te)
        if not isinstance(te, TupleType):
            raise ValueError("proj on non-tuple")
        if len(te.elems) != n:
            raise ValueError("proj size mismatch")
        return te.elems[i]
    raise ValueError("unknown tag")

def _collect_vars(t, seen, ordered):
    t = _find(t)
    if isinstance(t, TypeVar):
        if t not in seen:
            seen.add(t)
            ordered.append(t)
    elif isinstance(t, FuncType):
        _collect_vars(t.arg, seen, ordered)
        _collect_vars(t.ret, seen, ordered)
    elif isinstance(t, ListType):
        _collect_vars(t.elem, seen, ordered)
    elif isinstance(t, TupleType):
        for e in t.elems:
            _collect_vars(e, seen, ordered)

def _to_string(t, var_map):
    t = _find(t)
    if isinstance(t, IntType):
        return "Int"
    if isinstance(t, BoolType):
        return "Bool"
    if isinstance(t, TypeVar):
        return var_map[t]
    if isinstance(t, ListType):
        return f"(List {_to_string(t.elem, var_map)})"
    if isinstance(t, TupleType):
        if len(t.elems) == 0:
            return "(Tuple)"
        return f"(Tuple {' '.join(_to_string(e, var_map) for e in t.elems)})"
    if isinstance(t, FuncType):
        return f"(-> {_to_string(t.arg, var_map)} {_to_string(t.ret, var_map)})"
    return str(t)

def group_type(term):
    global _var_counter
    _var_counter = 0
    try:
        validated = _validate(term)
    except ValueError:
        raise ValueError("malformed")

    # Reset counter for naming
    _var_counter = 0

    env = {}
    # Build initial environment with fresh type variables for polymorphic args
    # We use fresh vars so they can be unified later
    _a = _fresh()
    _b = _fresh()
    _c = _fresh()
    _d = _fresh()
    _e = _fresh()
    _f = _fresh()

    INITIAL_ENV = {
        "add": (FuncType(IntType(), FuncType(IntType(), IntType())), True),
        "eq": (FuncType(_a, FuncType(_a, BoolType())), True),
        "nil": (ListType(_b), True),
        "cons": (FuncType(_c, FuncType(ListType(_c), ListType(_c))), True),
        "head": (FuncType(ListType(_d), _d), True),
        "tail": (FuncType(ListType(_e), ListType(_e)), True),
        "isnil": (FuncType(ListType(_f), BoolType()), True),
    }
    env = dict(INITIAL_ENV)

    t = _infer(validated, env)

    # Collect type variables in order of first appearance in the string representation
    seen = set()
    ordered_vars = []
    _collect_vars(t, seen, ordered_vars)

    # Map each TypeVar to a name based on its order
    var_map = {}
    for i, tv in enumerate(ordered_vars):
        var_map[tv] = _to_name(i)

    return _to_string(t, var_map)

