    dfs_num[n] = 0
    rev_dfs_num[0] = n
    order = [n]
    while stack:
        u = stack.pop()
        for v in rev_adj[u]:
            if dfs_num[v] == -1:
                dfs_num[v] = len(order)
                rev_dfs_num[len(order)] = v
                order.append(v)
                parent[v] = u
                stack.append(v)

    # Compute semi
    semi[n] = n
    for i in range(len(order) - 1, 0, -1):
        u = order[i]
        min_semi = n_nodes
        for v in rev_adj[u]:
            if dfs_num[v] != -1:
                if dfs_num[v] < dfs_num[u]:
                    w = v
                else:
                    w = parent[v]
                temp = w
                while semi[label[temp]] == n_nodes:
                    temp = label[temp]
                if semi[w] < semi[temp]:
                    min_semi = semi[w]
                else:
                    min_semi = semi[label[temp]]
        semi[u] = min_semi
        bucket[semi[u]].append(u)

    # Compute dom
    for i in range(len(order) - 1, 0, -1):
        u = order[i]
        for w in bucket[u]:
            temp = w
            while semi[label[temp]] == n_nodes:
                temp = label[temp]
            if semi[w] == semi[label[temp]]:
                dom[w] = semi[w]
            else:
                dom[w] = label[temp]
        v = parent[u]
        label[u] = v
        sz[v] += sz[u]

    # Final pass
    for i in range(1, len(order)):
        u = order[i]
        if dom[u] != semi[u]:
            dom[u] = dom[dom[u]]

    # Build post-dominator tree (PDT)
    # pdt_parent[u] is the parent of u in PDT
    pdt_parent = [-1] * n_nodes
    for i in range(1, len(order)):
        u = order[i]
        pdt_parent[u] = dom[u]

    # Compute DFS order on PDT to get subtree ranges
    in_time = [-1] * n_nodes
    out_time = [-1] * n_nodes
    subtree_nodes = [[] for _ in range(n_nodes)]
    timer = 0
    stack = [n]
    while stack:
        u = stack.pop()
        if in_time[u] == -1:
            in_time[u] = timer
            timer += 1
            subtree_nodes[u].append(u)
            # Push children in reverse order to maintain order
            children = [v for v in range(n_nodes) if pdt_parent[v] == u]
            for v in reversed(children):
                stack.append(v)
        # Since it's a tree, we just need to process once. 
        # The above simple DFS works because pdt_parent defines a tree.
        # But we need to set out_time. Let's do a proper DFS.

    # Reset and do proper DFS for in_time, out_time, and subtree_nodes
    in_time = [-1] * n_nodes
    out_time = [-1] * n_nodes
    subtree_nodes = [[] for _ in range(n_nodes)]
    timer = 0

    def dfs_pdt(u):
        nonlocal timer
        in_time[u] = timer
        timer += 1
        subtree_nodes[u].append(u)
        for v in range(n_nodes):
            if pdt_parent[v] == u:
                dfs_pdt(v)
        out_time[u] = timer - 1

    dfs_pdt(n)

    # Compute C
    T = [t for t in targets if t in A]
    if not T:
        return ([], sorted(targets))

    C = set(T)
    queue = deque(T)
    processed = set(T)

    while queue:
        y = queue.popleft()
        # Find all x such that y is control dependent on x
        # x controls y if x -> s, s in subtree(y), x not in subtree(y)
        for s in subtree_nodes[y]:
            for x in radj[s]:
                if x == n: continue # END is not in A
                # Check if x is not in subtree(y)
                if not (in_time[y] <= in_time[x] <= out_time[y]):
                    if x not in C:
                        C.add(x)
                        queue.append(x)
                        processed.add(x)

    targets_not_in_A = sorted([t for t in targets if t not in A])
    return (sorted(C), targets_not_in_A)

