    for u, v in edges:
        adj[u].append(v)
        radj[v].append(u)

    # Compute R: reachable from entry
    R = set()
    queue = deque([entry])
    R.add(entry)
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in R:
                R.add(v)
                queue.append(v)

