                q.append(v)

    if not A:
        return ([], sorted(targets))

    # Build reversed graph for A ∪ {END} for post-dominator computation
    # END is node n
    n_nodes = n + 1
    rev_adj = [[] for _ in range(n_nodes)]

    for u in A:
        for v in adj[u]:
            if v in A:
                rev_adj[v].append(u)
    for u in exits:
        if u in A:
            rev_adj[n].append(u)

    # Lengauer-Tarjan algorithm
    parent = [-1] * n_nodes
    semi = [n_nodes] * n_nodes
