    # Build post-dominator tree (PDT)
    pdt_parent = [-1] * n_nodes
    for i in range(1, len(order)):
        u = order[i]
        pdt_parent[u] = dom[u]

    # Compute in_time, out_time for PDT
    in_time = [-1] * n_nodes
    out_time = [-1] * n_nodes
    subtree_nodes = [[] for _ in range(n_nodes)]
    timer = 0

    def dfs_pdt(u):
        nonlocal timer
        in_time[u] = timer
        timer += 1
        subtree_nodes[u].append(u)
        for v in range(n_nodes):
            if pdt_parent[v] == u:
                dfs_pdt(v)
        out_time[u] = timer - 1

    dfs_pdt(n)

    # Compute C
    T = [t for t in targets if t in A]
    if not T:
        return ([], sorted(targets))

    C = set(T)
    queue = deque(T)
    processed = set(T)

    # Precompute predecessors in A
    preds_in_A = [[] for _ in range(n)]
    for u in A:
        for v in adj[u]:
            if v in A:
                preds_in_A[v].append(u)

