                    if x not in C:
                        C.add(x)
                        queue.append(x)
                        processed.add(x)

    targets_not_in_A = sorted([t for t in targets if t not in A])
    return (sorted(C), targets_not_in_A)

def branch_influence(n, edges, entry, exits, targets):
    # Input validation
    if not (type(n) is int and not isinstance(n, bool) and n >= 1):
        raise ValueError("n must be an int >= 1")
    if not (type(entry) is int and not isinstance(entry, bool) and 0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for e in edges:
        if not (type(e) in (tuple, list) and len(e) == 2 and
                type(e[0]) is int and not isinstance(e[0], bool) and
                type(e[1]) is int and not isinstance(e[1], bool) and
                0 <= e[0] < n and 0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
    for name, lst in [("exits", exits), ("targets", targets)]:
        if not isinstance(lst, (list, tuple, set)):
            raise ValueError(f"{name} must be a list, tuple or set")
        for x in lst:
            if not (type(x) is int and not isinstance(x, bool) and 0 <= x < n):
                raise ValueError(f"{name} must each be a list, tuple or set of ints in 0..n-1")

    # Build adjacency
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    # Reachability from entry (R)
    R = set()
    stack = [entry]
    while stack:
        u = stack.pop()
        if u in R:
            continue
        R.add(u)
        stack.extend(adj[u])

    # Reverse graph restricted to R
    rev_adj = [[] for _ in range(n)]
    for u in R:
        for v in adj[u]:
            rev_adj[v].append(u)

    # Compute A: nodes in R that can reach an exit
    exits_in_R = [u for u in R if u in exits]
    A = set()
    stack = exits_in_R
    while stack:
        u = stack.pop()
        if u in A:
            continue
        A.add(u)
        for p in rev_adj[u]:
            if p in R:
                stack.append(p)

    if not A:
        return ([], sorted(targets))

    # Filtered graph for A + virtual END (index n)
    END = n
    adj_filtered = [[] for _ in range(n + 1)]
    rev_adj_filtered = [[] for _ in range(n + 1)]

    for u in A:
        for v in adj[u]:
            if v in A:
                adj_filtered[u].append(v)
                rev_adj_filtered[v].append(u)
        if u in exits:
            adj_filtered[u].append(END)
            rev_adj_filtered[END].append(u)

    # Post-dominator tree (iterative algorithm)
    IDOM = {END: END}
    for v in A:
        IDOM[v] = None
    depth = {END: 0}
    for v in A:
        depth[v] = -1

    def intersect(u, v):
        while u != v:
            while depth[u] < depth[v]:
                u = IDOM[u]
            while depth[v] < depth[u]:
                v = IDOM[v]
            if u != v:
                u = IDOM[u]
                v = IDOM[v]
        return u

    changed = True
    while changed:
        changed = False
        for v in A:
            preds = rev_adj_filtered[v]
            new_idom = END if not preds else preds[0]
            for p in preds[1:]:
                new_idom = intersect(new_idom, p)
            if IDOM[v] != new_idom:
                IDOM[v] = new_idom
                depth[v] = depth[IDOM[v]] + 1
                changed = True

    # Build PD tree for ancestry checks
    children = [[] for _ in range(n + 1)]
    for v in A:
        children[IDOM[v]].append(v)

    entry_time = {}
    exit_time = {}
    timer = 0
    stack = [(END, 0)]
    entry_time[END] = 0
    timer = 1
    while stack:
        u, idx = stack[-1]
        if idx < len(children[u]):
            child = children[u][idx]
            stack[-1] = (u, idx + 1)
            entry_time[child] = timer
            timer += 1
            stack.append((child, 0))
        else:
            exit_time[u] = timer - 1
            stack.pop()

    def is_proper_ancestor(a, b):
        return entry_time[a] <= entry_time[b] and exit_time[a] >= exit_time[b] and a != b

    # Compute control dependencies
    ctrl_deps = {y: [] for y in A}
    for x in A:
        candidates = set()
        for s in adj_filtered[x]:
            if s == END:
                continue
            curr = s
            while curr != END:
                candidates.add(curr)
                curr = IDOM[curr]
        for y in candidates:
            if not is_proper_ancestor(y, x):
                ctrl_deps[y].append(x)

    # Compute C (closure)
    T = set(t for t in targets if t in A)
    C = set(T)
    queue = list(T)
    visited = set(T)
    while queue:
        t = queue.pop()
        for x in ctrl_deps[t]:
            if x not in visited:
                visited.add(x)
                C.add(x)
                queue.append(x)

    targets_not_in_A = sorted(t for t in targets if t not in A)
    return (sorted(C), targets_not_in_A)

