    # Reachability from entry (R)
    R = set()
    stack = [entry]
    while stack:
        u = stack.pop()
        if u in R:
            continue
        R.add(u)
        stack.extend(adj[u])

    # Reverse graph restricted to R
    rev_adj = [[] for _ in range(n)]
    for u in R:
        for v in adj[u]:
            rev_adj[v].append(u)

    # Compute A: nodes in R that can reach an exit
    exits_in_R = [u for u in R if u in exits]
    A = set()
    stack = exits_in_R
    while stack:
        u = stack.pop()
        if u in A:
            continue
        A.add(u)
        for p in rev_adj[u]:
            if p in R:
                stack.append(p)

    if not A:
        return ([], sorted(targets))

    # Filtered graph for A + virtual END (index n)
    END = n
    adj_filtered = [[] for _ in range(n + 1)]
    rev_adj_filtered = [[] for _ in range(n + 1)]

    for u in A:
        for v in adj[u]:
            if v in A:
                adj_filtered[u].append(v)
                rev_adj_filtered[v].append(u)
        if u in exits:
            adj_filtered[u].append(END)
            rev_adj_filtered[END].append(u)

    # Post-dominator tree (iterative algorithm)
    IDOM = {END: END}
    for v in A:
        IDOM[v] = None
    depth = {END: 0}
    for v in A:
        depth[v] = -1

    def intersect(u, v):
        while u != v:
            while depth[u] < depth[v]:
                u = IDOM[u]
            while depth[v] < depth[u]:
                v = IDOM[v]
            if u != v:
                u = IDOM[u]
                v = IDOM[v]
        return u

    changed = True
    while changed:
        changed = False
        for v in A:
            preds = rev_adj_filtered[v]
            new_idom = END if not preds else preds[0]
            for p in preds[1:]:
