            if IDOM[v] != new_idom:
                IDOM[v] = new_idom
                depth[v] = depth[IDOM[v]] + 1
                changed = True

    # Build control dependencies efficiently
    # ctrl_deps[y] stores list of x such that x controls y
    ctrl_deps = {y: [] for y in A}

    # We traverse up the post-dominator tree from each successor s of each x in A.
    # To avoid O(N^2) in worst case, we use a simple but effective optimization:
    # only traverse if we haven't processed this path segment yet, or rely on typical CFG structure.
    # Given constraints, direct traversal is usually fast enough.
    for x in A:
        for s in adj_filtered[x]:
            if s == END:
                continue
            y = s
            while y != END:
