    # ctrl_deps[y] contains x where x controls y. So edges are y -> x in the "controller" graph.
    # We BFS from T following these edges.
    while queue:
        y = queue.pop()
        for x in ctrl_deps[y]:
            if x not in C:
                C.add(x)
                queue.append(x)

    targets_not_in_A = sorted(t for t in targets if t not in A)
    return (sorted(C), targets_not_in_A)

import sys
