import itertools

def live_phi_sites(n, edges, entry, blocks, params):
    # --- Validation ---
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges a list of pairs")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges a list of pairs")
        if not all(isinstance(x, int) and not isinstance(x, bool) and 0 <= x < n for x in e):
            raise ValueError("edges a list of pairs")

    if not isinstance(blocks, dict):
        raise ValueError("blocks a dict")
    for k, v in blocks.items():
        if not isinstance(k, int) or isinstance(k, bool) or not (0 <= k < n):
            raise ValueError("blocks a dict")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values are lists")
        for instr in v:
            if not isinstance(instr, (list, tuple)) or len(instr) != 2:
                raise ValueError("blocks instructions are pairs")
            op, name = instr
            if op not in ("use", "def", "upd"):
                raise ValueError("op must be one of the three strings")
            if not isinstance(name, str) or not name:
                raise ValueError("name is a non-empty str")

    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params a list, tuple, set or frozenset")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("params non-empty str")

    # --- Reachability Pruning ---
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    reachable = [False] * n
    q = collections.deque([entry])
    reachable[entry] = True
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                q.append(v)

    # Filter graph to reachable nodes only
    r_adj = [[] for _ in range(n)]
    r_rev_adj = [[] for _ in range(n)]
    reachable_nodes = [i for i in range(n) if reachable[i]]
    for u in reachable_nodes:
        for v in adj[u]:
            if reachable[v]:
                r_adj[u].append(v)
                r_rev_adj[v].append(u)

    # --- Dominator Computation (Lengauer-Tarjan) ---
    parent = [-1] * n
    semi = [-1] * n
    dom = [-1] * n
    bucket = [[] for _ in range(n)]
    ancestor = [-1] * n
    best = [-1] * n

    preorder = [-1] * n
    node_at = [-1] * n
    timer = 0
    order = []

    # Iterative DFS
    stack = [entry]
    visited = [False] * n
    visited[entry] = True
    while stack:
        u = stack.pop()
        timer += 1
        preorder[u] = timer
        node_at[timer] = u
        order.append(u)
        for v in r_adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    # Semi-dominators
    def eval_path(u):
        path = []
        curr = u
        while ancestor[curr] != -1:
            path.append(curr)
            curr = ancestor[curr]
        root = curr
        for node in path:
            ancestor[node] = root
        return root

    for i in range(len(order) - 1, 0, -1):
        w = node_at[i]
        for v in r_adj[w]:
            if preorder[v] != -1:
                if preorder[v] < preorder[w]:
                    if semi[v] == -1 or preorder[v] < preorder[semi[w]]:
                        semi[w] = v
        p = parent[w]
        bucket[p].append(w)
        for v in bucket[p]:
            u = eval_path(v)
            if semi[u] == -1 or preorder[u] < preorder[semi[v]]:
                semi[v] = u
        ancestor[w] = p

    # Dominators
    for i in range(1, len(order)):
        w = node_at[i]
        if semi[w] != parent[w]:
            dom[w] = dom[semi[w]]
        else:
            dom[w] = parent[w]

    for i in range(1, len(order)):
        w = node_at[len(order) - i]
        if dom[w] != semi[w]:
            dom[w] = dom[dom[w]]

    dom[entry] = entry

    # --- Dominance Frontier ---
    DF = [set() for _ in range(n)]
    for u in reachable_nodes:
        for v in r_adj[u]:
            if dom[u] != dom[v]:
                DF[v].add(u)

    # --- Name Processing ---
    # Collect all relevant names
    all_names = set(params)
    defines = [set() for _ in range(n)]
    upward_exposed_uses = [set() for _ in range(n)]

    for u in reachable_nodes:
        if u in blocks:
            instrs = blocks[u]
            has_def = False
            for op, name in instrs:
                all_names.add(name)
                if op == "def":
                    defines[u].add(name)
                    has_def = True
                elif op == "upd":
                    defines[u].add(name)
                    upward_exposed_uses[u].add(name)
                    has_def = True
                elif op == "use":
                    if not has_def:
                        upward_exposed_uses[u].add(name)
                    # upd acts as def for subsequent uses in same block
                    has_def = True

    result_nodes = {}

    for x in all_names:
        # D(x)
        D_x = set()
        if x in params:
            D_x.add(entry)
        for u in reachable_nodes:
            if x in defines[u]:
                D_x.add(u)

        if not D_x:
            continue

        # P(x) = closure of D(x) under DF
        P_x = set(D_x)
        worklist = list(D_x)
        while worklist:
            u = worklist.pop()
            for v in DF[u]:
                if v not in P_x:
                    P_x.add(v)
                    worklist.append(v)

        # Liveness for x
        # x is live-in at y if y can reach an upward-exposed use without passing a def/upd
        live_in = set()
        worklist = list(upward_exposed_uses[u] for u in reachable_nodes if x in upward_exposed_uses[u])
        # Flatten
        w_list = []
        for s in worklist:
            w_list.extend(s)

        while w_list:
            y = w_list.pop()
            if y in live_in:
                continue
            live_in.add(y)
            for p in r_rev_adj[y]:
                if p not in live_in and x not in defines[p]:
                    w_list.append(p)

        # Phi needed at y iff y in P_x and x live-in at y
        needed = P_x & live_in
        if needed:
            result_nodes[y] = result_nodes.get(y, set())
            result_nodes[y].add(x)

    # Format output
    out = []
    for node in sorted(result_nodes.keys()):
        names = sorted(result_nodes[node])
        out.append((node, names))

    return out

