sys.setrecursionlimit(100000)

def live_phi_sites(n, edges, entry, blocks, params):
    # --- Validation ---
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges a list of pairs")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges a list of pairs")
        if not all(isinstance(x, int) and not isinstance(x, bool) and 0 <= x < n for x in e):
            raise ValueError("edges a list of pairs")

    if not isinstance(blocks, dict):
        raise ValueError("blocks a dict")
    for k, v in blocks.items():
        if not isinstance(k, int) or isinstance(k, bool) or not (0 <= k < n):
            raise ValueError("blocks a dict")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values are lists")
        for instr in v:
            if not isinstance(instr, (list, tuple)) or len(instr) != 2:
                raise ValueError("blocks instructions are pairs")
            op, name = instr
            if op not in ("use", "def", "upd"):
                raise ValueError("op must be one of the three strings")
            if not isinstance(name, str) or not name:
                raise ValueError("name is a non-empty str")

    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params a list, tuple, set or frozenset")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("params non-empty str")

    # --- Adjacency Lists ---
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    # --- Reachability ---
    reachable = [False] * n
    q = collections.deque([entry])
    reachable[entry] = True
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                q.append(v)

    reachable_nodes = [i for i in range(n) if reachable[i]]
    r_adj = [[] for _ in range(n)]
    r_rev_adj = [[] for _ in range(n)]
    for u in reachable_nodes:
        for v in adj[u]:
            if reachable[v]:
                r_adj[u].append(v)
                r_rev_adj[v].append(u)

    # --- Dominators (Lengauer-Tarjan) ---
    parent = [-1] * n
    semi = list(range(n))
    dom = list(range(n))
    bucket = [[] for _ in range(n)]
    ancestor = [-1] * n
    best = list(range(n))

    preorder = [-1] * n
    node_at = [-1] * (n + 1)
    timer = 0

    stack = [entry]
    visited = [False] * n
    visited[entry] = True
    while stack:
        u = stack.pop()
        timer += 1
        preorder[u] = timer
        node_at[timer] = u
        for v in r_adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    for i in range(1, timer + 1):
        u = node_at[i]
        semi[u] = u
        best[u] = u
        ancestor[u] = -1

    def eval_path(u):
        if ancestor[u] == -1:
            return u
        if ancestor[best[u]] != -1:
            eval_path(ancestor[best[u]])
            if preorder[best[ancestor[u]]] < preorder[best[u]]:
                best[u] = best[ancestor[u]]
        return best[u]

    for i in range(timer, 1, -1):
        w = node_at[i]
        for v in r_rev_adj[w]:
            if preorder[v] != -1:
                if preorder[v] < preorder[w]:
                    u = eval_path(v)
                    if preorder[u] < preorder[semi[w]]:
                        semi[w] = u
                else:
                    if preorder[v] < preorder[semi[w]]:
                        semi[w] = v

        p = parent[w]
        if p != -1:
            bucket[p].append(w)
            ancestor[w] = p
            for v in bucket[p]:
                u = eval_path(v)
                if preorder[u] < preorder[semi[v]]:
                    semi[v] = u
            bucket[p] = []

    for i in range(1, timer + 1):
        w = node_at[i]
        if semi[w] != parent[w]:
            dom[w] = dom[semi[w]]
        else:
            dom[w] = parent[w]

    for i in range(1, timer + 1):
        w = node_at[i]
        if dom[w] != semi[w]:
            dom[w] = dom[dom[w]]

    dom[entry] = entry

    # --- Dominance Frontier ---
    DF = [set() for _ in range(n)]
    for u in reachable_nodes:
        for v in r_adj[u]:
            if dom[u] == dom[v]:
                DF[v].add(u)

    # --- Precompute Defines and Upward Exposed Uses ---
    defines = [set() for _ in range(n)]
    upward_exposed_uses = [set() for _ in range(n)]
    all_names = set(params)

    for u in reachable_nodes:
        if u in blocks:
            instrs = blocks[u]
            has_def = False
            for op, name in instrs:
                all_names.add(name)
                if op == "def":
                    defines[u].add(name)
                    has_def = True
                elif op == "upd":
                    defines[u].add(name)
                    upward_exposed_uses[u].add(name)
                    has_def = True
                elif op == "use":
                    if not has_def:
                        upward_exposed_uses[u].add(name)
                    has_def = True

    result_nodes = {}

    for x in all_names:
        # D(x)
        D_x = set()
        if x in params:
            D_x.add(entry)
        for u in reachable_nodes:
            if x in defines[u]:
                D_x.add(u)

        if not D_x:
            continue

        # P(x) closure
        P_x = set(D_x)
        worklist = list(D_x)
        while worklist:
            u = worklist.pop()
            for v in DF[u]:
                if v not in P_x:
                    P_x.add(v)
                    worklist.append(v)

        # Liveness
        live_in = set()
        w_list = [u for u in reachable_nodes if x in upward_exposed_uses[u]]
        while w_list:
            y = w_list.pop()
            if y in live_in:
                continue
            live_in.add(y)
            for p in r_rev_adj[y]:
                if p not in live_in and x not in defines[p]:
                    w_list.append(p)

        # Phi needed
        needed = P_x & live_in
        if needed:
            for y in needed:
                if y not in result_nodes:
                    result_nodes[y] = set()
                result_nodes[y].add(x)

    out = []
    for node in sorted(result_nodes.keys()):
        names = sorted(result_nodes[node])
        out.append((node, names))

    return out

