        raise ValueError("params must be a list, tuple, set or frozenset")
    for p in params:
        if not isinstance(p, str) or len(p) == 0:
            raise ValueError("params elements must be non-empty str")

    params = set(params)

    # --- Reachability & Graph Setup ---
    adj = collections.defaultdict(list)
    rev_adj = collections.defaultdict(list)
    for u, v in edges:
