        rev_adj[v].append(u)

    reachable = set()
    q = collections.deque([entry])
    reachable.add(entry)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in reachable:
                reachable.add(v)
                q.append(v)

    # Filter to reachable only
    adj = {u: [v for v in vs if v in reachable] for u, vs in adj.items() if u in reachable}
    rev_adj = {v: [u for u in us if u in reachable] for v, us in rev_adj.items() if v in reachable}

    # --- Dominator Tree (Iterative O(V+E) typical, fast enough for 40k) ---
    order = list(reachable)
    pos = {v: i for i, v in enumerate(order)}
    dom = {entry: entry}
    for v in order:
        if v != entry:
            dom[v] = None

    changed = True
    while changed:
        changed = False
        for v in order:
            if v == entry:
                continue
            preds = [p for p in adj[v] if p in dom]
            if not preds:
                continue
            new_dom = preds[0]
            for p in preds[1:]:
                a, b = new_dom, dom[p]
                while a != b:
                    while pos[a] > pos[b]:
                        a = dom[a]
                    while pos[b] > pos[a]:
                        b = dom[b]
                new_dom = a
            if dom[v] != new_dom:
                dom[v] = new_dom
                changed = True

    # --- Dominance Frontier ---
    df = collections.defaultdict(set)
    # idom lookup
    idom = {entry: entry}
    for v in order:
        if v == entry:
            continue
        # find immediate dominator: deepest proper dominator of v
        d = dom[v]
        while d != entry and dom[d] != dom[dom.get(d, d)]: # simplified: just walk up
            # Actually, standard: idom(v) is the node d such that d != v, d dominates v, and no other node strictly between
            pass
        # Simpler: compute idom properly
        pass

    # Recompute idom cleanly
    idom = {}
    for v in order:
        if v == entry:
            idom[v] = entry
            continue
        # idom(v) is the unique node d != v that dominates v and is dominated by all other strict dominators of v
        # Since dom[v] is the intersection of preds' dominators, idom(v) = dom[v] unless dom[v] == v
        # Actually, dom[v] is the immediate dominator itself in this formulation!
        idom[v] = dom[v]

    # Standard DF computation: O(E log V) or O(E) with path compression
    # For each edge (p, y), walk up from p until idom(y)
    for p in adj:
        for y in adj[p]:
            w = p
            while w != idom[y] and w is not None:
                df[w].add(y)
                w = idom.get(w)

    # --- P(x) Computation ---
    # Precompute def/upd nodes per name
    defs = collections.defaultdict(set)
    for u in reachable:
        if u in blocks:
            for op, x in blocks[u]:
                if op in ("def", "upd"):
                    defs[x].add(u)

    def compute_P(x):
        D = set(defs[x])
        if x in params:
            D.add(entry)
        P = set(D)
        queue = collections.deque(D)
        while queue:
            d = queue.popleft()
            for y in df[d]:
                if y not in P:
                    P.add(y)
                    queue.append(y)
        return P

    # --- Liveness Computation ---
    # Precompute upward-exposed uses per name
    exposed = collections.defaultdict(set)
    for u in reachable:
        if u in blocks:
            has_def = False
            for op, x in blocks[u]:
                if op in ("def", "upd"):
                    has_def = True
                elif op == "use" and not has_def:
                    exposed[x].add(u)
                if op in ("def", "upd"):
                    # upd is use then def, so if it's the first instruction, use is exposed
                    # But "upd" itself is a use. If nothing precedes it, it's exposed.
                    # Our loop handles it: if has_def is False when we see "upd", it's exposed.
                    # But we need to mark it as exposed before marking has_def=True
                    pass
            # Fix: scan properly
            exposed[u] = set() # clear if needed, but defaultdict handles it
            pass

    # Redo exposed correctly
    exposed = collections.defaultdict(set)
    for u in reachable:
        if u in blocks:
            seen_def = False
            for op, x in blocks[u]:
                if op in ("def", "upd"):
                    if not seen_def:
                        exposed[x].add(u)
                    seen_def = True
                elif op == "use":
                    if not seen_def:
                        exposed[x].add(u)

    def compute_live_in(x):
        if x not in exposed:
            return set()
        live = set(exposed[x])
        queue = collections.deque(exposed[x])
        visited = set(exposed[x])
        while queue:
            w = queue.popleft()
            for p in rev_adj.get(w, []):
                if p in visited:
                    continue
                visited.add(p)
                if p in defs[x]:
                    continue
                live.add(p)
                queue.append(p)
        return live

    # --- Combine & Output ---
    phi_map = collections.defaultdict(set)
    for x in set(defs.keys()) | params:
        P = compute_P(x)
        L = compute_live_in(x)
        for node in P & L:
            phi_map[node].add(x)

    result = []
    for node in sorted(phi_map.keys()):
        names = sorted(phi_map[node])
        result.append((node, names))

    return result

