    dom_adj = collections.defaultdict(list)
    for v in order:
        if v != entry:
            dom_adj[dom[v]].append(v)

    q = collections.deque([entry])
    depth = {entry: 0}
    while q:
        u = q.popleft()
        for v in dom_adj[u]:
            depth[v] = depth[u] + 1
            q.append(v)

    def get_lca(u, v):
        # Walk up deeper node
        du = depth.get(u, 0)
        dv = depth.get(v, 0)
        while du > dv:
            u = dom[u]
            du -= 1
        while dv > du:
            v = dom[v]
            dv -= 1
        while u != v:
            u = dom[u]
            v = dom[v]
        return u

    # Compute DF
    # We can accumulate DF as a dict of sets
    # But to avoid O(N*E) insertions, maybe we can process per node?
    # Actually, let's just do it. 120k edges * small depth usually.

    for u, neighbors in adj.items():
        for v in neighbors:
            l = get_lca(u, v)

            # Case 1: v is ancestor of u (back edge)
            if l == v:
                # v in DF(v)
                df[v].add(v)
                # Nodes on path v->u excluding v
                curr = u
                while curr != v:
                    df[curr].add(v)
                    curr = dom[curr]
            else:
                # l != v
                # Nodes on path l->u excluding l
                curr = u
                while curr != l:
                    df[curr].add(v)
                    curr = dom[curr]

    # --- P(x) Computation ---
    # Precompute def/upd nodes per name
    defs = collections.defaultdict(set)
    for u in reachable:
        if u in blocks:
            for op, x in blocks[u]:
                if op in ("def", "upd"):
                    defs[x].add(u)

    def compute_P(x):
        D = set(defs[x])
        if x in params:
            D.add(entry)
        P = set(D)
        queue = collections.deque(D)
        while queue:
            d = queue.popleft()
            # P = DF(D union P)
            # We need to add DF(d) to P for all d in D union P
            # But we only add new ones to queue
            for y in df[d]:
                if y not in P:
                    P.add(y)
                    queue.append(y)
        return P

    # --- Liveness Computation ---
    # Precompute upward-exposed uses per name
    exposed = collections.defaultdict(set)
    for u in reachable:
        if u in blocks:
            seen_def = False
            for op, x in blocks[u]:
                if op in ("def", "upd"):
                    if not seen_def:
                        exposed[x].add(u)
                    seen_def = True
                elif op == "use":
                    if not seen_def:
                        exposed[x].add(u)

    def compute_live_in(x):
        if x not in exposed:
            return set()
        live = set(exposed[x])
        queue = collections.deque(exposed[x])
        visited = set(exposed[x])
        while queue:
            w = queue.popleft()
            for p in rev_adj.get(w, []):
                if p in visited:
                    continue
                visited.add(p)
                if p in defs[x]:
                    continue
                live.add(p)
                queue.append(p)
        return live

    # --- Combine & Output ---
    phi_map = collections.defaultdict(set)
    all_names = set(defs.keys()) | params

    for x in all_names:
        P = compute_P(x)
        L = compute_live_in(x)
        for node in P & L:
            phi_map[node].add(x)

    result = []
    for node in sorted(phi_map.keys()):
        names = sorted(phi_map[node])
        result.append((node, names))

    return result

