import sys

def live_phi_sites(n, edges, entry, blocks, params):
    # --- Input Validation ---
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list of pairs")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2)")
        if not all(isinstance(x, int) and not isinstance(x, bool) for x in e):
            raise ValueError("edge nodes must be ints")
        if not (0 <= e[0] < n and 0 <= e[1] < n):
            raise ValueError("edge nodes must be in 0..n-1")

    if not isinstance(blocks, dict):
        raise ValueError("blocks must be a dict")
    for k, v in blocks.items():
        if not isinstance(k, int) or isinstance(k, bool) or not (0 <= k < n):
            raise ValueError("blocks keys must be ints in 0..n-1")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values must be lists or tuples")
        for inst in v:
            if not isinstance(inst, (list, tuple)) or len(inst) != 2:
                raise ValueError("instructions must be pairs")
            if inst[0] not in ("use", "def", "upd"):
                raise ValueError("op must be one of 'use', 'def', 'upd'")
            if not isinstance(inst[1], str) or len(inst[1]) == 0:
                raise ValueError("name must be a non-empty str")

    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be a list, tuple, set or frozenset")
    for p in params:
        if not isinstance(p, str) or len(p) == 0:
            raise ValueError("params elements must be non-empty str")

    params = set(params)

    # --- Reachability & Graph Setup ---
    adj = collections.defaultdict(list)
    rev_adj = collections.defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    reachable = set()
    q = collections.deque([entry])
    reachable.add(entry)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in reachable:
                reachable.add(v)
                q.append(v)

    # Filter to reachable only
    adj = {u: [v for v in vs if v in reachable] for u, vs in adj.items() if u in reachable}
    rev_adj = {v: [u for u in us if u in reachable] for v, us in rev_adj.items() if v in reachable}

    # --- Dominator Tree ---
    order = list(reachable)
    pos = [0] * n
    for i, v in enumerate(order):
        pos[v] = i

    dom = [0] * n
    dom[entry] = entry
    for v in order:
        if v != entry:
            dom[v] = entry # Initialize to entry

    changed = True
    while changed:
        changed = False
        for v in order:
            if v == entry:
                continue
            preds = adj[v]
            if not preds:
                continue

            new_dom = preds[0]
            for p in preds[1:]:
                a, b = new_dom, dom[p]
                while a != b:
                    while pos[a] > pos[b]:
                        a = dom[a]
                    while pos[b] > pos[a]:
                        b = dom[b]
                new_dom = a
            if dom[v] != new_dom:
                dom[v] = new_dom
                changed = True

    # --- Dominance Frontier ---
    # Precompute depth for LCA
    dom_adj = collections.defaultdict(list)
    for v in order:
        if v != entry:
            dom_adj[dom[v]].append(v)

    depth = [0] * n
    q = collections.deque([entry])
    while q:
        u = q.popleft()
        for v in dom_adj[u]:
            depth[v] = depth[u] + 1
            q.append(v)

    def get_lca(u, v):
        du = depth[u]
        dv = depth[v]
        while du > dv:
            u = dom[u]
            du -= 1
        while dv > du:
            v = dom[v]
            dv -= 1
        while u != v:
            u = dom[u]
            v = dom[v]
        return u

    # Compute DF
    # df[d] will store the set of nodes y such that y is in DF(d)
    df = [set() for _ in range(n)]

    for u, neighbors in adj.items():
        for v in neighbors:
            l = get_lca(u, v)

            # We want to find all d such that d dominates u and d does not strictly dominate v.
            # d dominates u <=> d is ancestor of u.
            # d does not strictly dominate v <=> d is not ancestor of v (or d == v).

            # Path root->u is split at l = LCA(u, v).
            # Path root->l is common. Path l->u is unique to u.
            # Path root->l is also on path to v.

            # Ancestors of u are (root->l) U (l->u exclusive l).
            # Ancestors of v are (root->l) U (l->v exclusive l).

            # We want d in (root->l U (l->u)) such that d is NOT in (root->l exclusive v) AND d != v.
            # Actually, d dominates v means d in (root->l U (l->v)).
            # Strictly dominates means d != v.
            # So d does not strictly dominate v means d is NOT in (root->l U (l->v)) OR d == v.

            # Intersection with d in (root->l U (l->u)):
            # 1. d in (root->l). Then d dominates v. So d must be v.
            #    So if v is in (root->l), i.e., v is ancestor of u, then d=v is a solution.
            #    v is ancestor of u iff l == v.
            # 2. d in (l->u exclusive l). Then d does not dominate v (since l is the lowest common ancestor).
            #    So all d in (l->u exclusive l) are solutions.

            if l == v:
                # v is ancestor of u.
                # d=v is a solution.
                df[v].add(v)
                # d in (v->u exclusive v) are solutions.
                curr = u
                while curr != v:
                    df[curr].add(v)
                    curr = dom[curr]
            else:
                # l != v. v is not ancestor of u.
                # d in (l->u exclusive l) are solutions.
                curr = u
                while curr != l:
                    df[curr].add(v)
                    curr = dom[curr]

    # --- P(x) Computation ---
    defs = collections.defaultdict(set)
    for u in reachable:
        if u in blocks:
            for op, x in blocks[u]:
                if op in ("def", "upd"):
                    defs[x].add(u)

    def compute_P(x):
        D = set(defs[x])
        if x in params:
            D.add(entry)
        P = set(D)
        queue = collections.deque(D)
        while queue:
            d = queue.popleft()
            for y in df[d]:
                if y not in P:
                    P.add(y)
                    queue.append(y)
        return P

    # --- Liveness Computation ---
    exposed = collections.defaultdict(set)
    for u in reachable:
        if u in blocks:
            seen_def = False
            for op, x in blocks[u]:
                if op in ("def", "upd"):
                    if not seen_def:
                        exposed[x].add(u)
                    seen_def = True
                elif op == "use":
                    if not seen_def:
                        exposed[x].add(u)

    def compute_live_in(x):
        if x not in exposed:
            return set()
        live = set(exposed[x])
        queue = collections.deque(exposed[x])
        visited = set(exposed[x])
        while queue:
            w = queue.popleft()
            for p in rev_adj.get(w, []):
                if p in visited:
                    continue
                visited.add(p)
                if p in defs[x]:
                    continue
                live.add(p)
                queue.append(p)
        return live

    # --- Combine & Output ---
    phi_map = collections.defaultdict(set)
    all_names = set(defs.keys()) | params

    for x in all_names:
        P = compute_P(x)
        L = compute_live_in(x)
        for node in P & L:
            phi_map[node].add(x)

    result = []
    for node in sorted(phi_map.keys()):
        names = sorted(phi_map[node])
        result.append((node, names))

    return result

