def live_phi_sites(n, edges, entry, blocks, params):
    # --- Input Validation ---
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1 (bool is not int)")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for e in edges:
        if not (isinstance(e, (list, tuple)) and len(e) == 2):
            raise ValueError("edges must contain pairs of length 2")
        if any(not isinstance(x, int) or isinstance(x, bool) or x < 0 or x >= n for x in e):
            raise ValueError("edge elements must be ints in 0..n-1")
    if not isinstance(blocks, dict):
        raise ValueError("blocks must be a dict")
    for k, v in blocks.items():
        if not isinstance(k, int) or isinstance(k, bool) or k < 0 or k >= n:
            raise ValueError("blocks keys must be ints in 0..n-1")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values must be lists or tuples")
        for instr in v:
            if not (isinstance(instr, (list, tuple)) and len(instr) == 2):
                raise ValueError("instructions must be pairs of length 2")
            op, name = instr
            if op not in ("use", "def", "upd"):
                raise ValueError("op must be one of 'use', 'def', 'upd'")
            if not isinstance(name, str) or not name:
                raise ValueError("name must be a non-empty str")
    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be a list, tuple, set or frozenset")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("params elements must be non-empty str")

    # --- Reachability ---
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    reachable = set()
    stack = [entry]
    while stack:
        u = stack.pop()
        if u not in reachable:
            reachable.add(u)
            for v in adj[u]:
                if v not in reachable:
                    stack.append(v)

    # Filter to reachable subgraph
    r_adj = [[] for _ in range(n)]
    r_pred = [[] for _ in range(n)]
    for u in reachable:
        for v in adj[u]:
            if v in reachable:
                r_adj[u].append(v)
                r_pred[v].append(u)

    # --- Dominators & Dominance Frontier (Lengauer-Tarjan) ---
    dfs_num = [-1] * n
    dfs_rev = [-1] * n
    parent = [-1] * n
    semi = [0] * n
    idom = [0] * n
    ancestor = [-1] * n
    vertex = [0] * n
    bucket = [[] for _ in range(n)]
    dsu = list(range(n))

    num = 0
    def dfs(u):
        nonlocal num
        dfs_num[u] = num
        dfs_rev[num] = u
        vertex[num] = u
        num += 1
        for v in r_adj[u]:
            if dfs_num[v] == -1:
                parent[v] = u
                dfs(v)

    dfs(entry)

    def eval_(u):
        if dsu[u] == u:
            return u
        res = eval_(dsu[u])
        if semi[dsu[u]] < semi[u]:
            semi[u] = semi[dsu[u]]
        dsu[u] = res
        return res

    def link(u, v):
        dsu[u] = v
        if semi[u] < semi[v]:
            semi[v] = semi[u]

    for i in range(num - 1, 0, -1):
        u = dfs_rev[i]
        for v in bucket[u]:
            w = eval_(v)
            if semi[w] < semi[u]:
                semi[u] = semi[w]
        w = parent[u]
        link(u, w)
        bucket[ancestor[w]].append(u)
        if i == 1:
            continue
        if semi[ancestor[u]] == semi[u]:
            idom[u] = ancestor[u]
        else:
            idom[u] = u

    for i in range(1, num):
        u = dfs_rev[i]
        if idom[u] != semi[u]:
            idom[u] = idom[idom[u]]

    # Compute DF efficiently
    DF = [[] for _ in range(n)]
    for i in range(1, num):
        u = dfs_rev[i]
        w = idom[u]
        for v in r_adj[u]:
            if v != w:
                DF[v].append(u)

    # --- Liveness (Backward Dataflow) ---
    uses = [set() for _ in range(n)]
    defs = [set() for _ in range(n)]
    for u in reachable:
        instrs = blocks.get(u, [])
        found_def_or_upd = False
        for op, name in instrs:
            if op in ("def", "upd"):
                found_def_or_upd = True
                defs[u].add(name)
            elif op == "use":
                if not found_def_or_upd:
                    uses[u].add(name)

    live_in = [set() for _ in range(n)]
    live_out = [set() for _ in range(n)]
    worklist = list(reachable)
    while worklist:
        u = worklist.pop()
        new_out = set()
        for v in r_adj[u]:
            new_out |= live_in[v]
        if new_out == live_out[u]:
            continue
        live_out[u] = new_out
        new_in = uses[u] | (live_out[u] - defs[u])
        if new_in != live_in[u]:
            live_in[u] = new_in
            for p in r_pred[u]:
                worklist.append(p)

    # --- P(x) & Phi Sites ---
    all_names = set()
    for u in reachable:
        all_names |= defs[u]
        all_names |= uses[u]
    all_names |= set(params)

    phi_sites = {}
    for x in all_names:
        D_x = set()
        for u in reachable:
            if x in defs[u]:
                D_x.add(u)
        if x in params:
            D_x.add(entry)

        P_x = set(D_x)
        queue = list(D_x)
        while queue:
            d = queue.pop()
            for y in DF[d]:
                if y not in P_x:
                    P_x.add(y)
                    queue.append(y)

        for y in P_x:
            if x in live_in[y]:
                phi_sites.setdefault(y, set()).add(x)

    # --- Output ---
    result = []
    for u in sorted(phi_sites.keys()):
        result.append((u, sorted(phi_sites[u])))
    return result

