        if not all(isinstance(x, int) and not isinstance(x, bool) for x in e):
            raise ValueError("edge nodes must be ints")
        if not all(0 <= x < n for x in e):
            raise ValueError("edge nodes must be in 0..n-1")

    if not isinstance(blocks, dict):
        raise ValueError("blocks must be a dict")
    for k, v in blocks.items():
        if not isinstance(k, int) or isinstance(k, bool) or not (0 <= k < n):
            raise ValueError("blocks keys must be ints in 0..n-1")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values must be lists/tuples")
        for instr in v:
            if not isinstance(instr, (list, tuple)) or len(instr) != 2:
                raise ValueError("instructions must be pairs")
            op, name = instr
            if op not in ("use", "def", "upd"):
                raise ValueError("op must be use/def/upd")
            if not isinstance(name, str) or not name:
                raise ValueError("name must be non-empty str")

    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be a collection")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("params must be non-empty strs")

    sys.setrecursionlimit(100000)

    # --- Reachability ---
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
    reachable = set()
    q = deque([entry])
    reachable.add(entry)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in reachable:
                reachable.add(v)
                q.append(v)

    # --- CFG Structures ---
    cfg_adj = defaultdict(list)
    cfg_preds = defaultdict(list)
    for u, v in edges:
        if u in reachable and v in reachable:
            cfg_adj[u].append(v)
            cfg_preds[v].append(u)

    # --- Dominators (Lengauer-Tarjan) ---
    dfs_num = [-1] * n
    dfs_rev = [-1] * n
    parent = [-1] * n
    semi = [-1] * n
    ancestor = [-1] * n
    bucket = [[] for _ in range(n)]
    idom = [-1] * n

    order = []
    num_nodes = 0
    def dfs(u):
        nonlocal num_nodes
        dfs_num[u] = num_nodes
        dfs_rev[num_nodes] = u
        order.append(u)
        num_nodes += 1
        for v in cfg_adj[u]:
            if dfs_num[v] == -1:
                parent[v] = u
                dfs(v)
    dfs(entry)

    for i in range(num_nodes):
        v = dfs_rev[i]
        semi[v] = v
        ancestor[v] = -1

    def eval_lt(u):
        if ancestor[u] == -1:
            return u
        if ancestor[eval_lt(ancestor[u])] != -1:
            ancestor[u] = eval_lt(ancestor[u])
            semi[u] = semi[ancestor[u]]
        return ancestor[u]

    def link_lt(v, w):
        ancestor[w] = v

    for i in range(num_nodes - 1, 0, -1):
        w = dfs_rev[i]
        v = parent[w]
        for u in bucket[v]:
            a = eval_lt(u)
            if semi[a] < semi[u]:
                semi[u] = semi[a]
        link_lt(v, w)
        bucket[semi[v]].append(w)
        if semi[v] == v:
            idom[w] = v
        else:
            idom[w] = semi[v]

    for i in range(num_nodes - 1, 0, -1):
        w = dfs_rev[i]
        if idom[w] != semi[w]:
            idom[w] = idom[idom[w]]

    # --- Dominance Check (tin/tout) ---
    tin = [-1] * n
    tout = [-1] * n
    timer = 0
    dom_tree_adj = defaultdict(list)
    for v in reachable:
        if idom[v] != -1:
            dom_tree_adj[idom[v]].append(v)

    def dfs_dom(u):
        nonlocal timer
        timer += 1
        tin[u] = timer
        for v in dom_tree_adj[u]:
            dfs_dom(v)
        tout[u] = timer

    dfs_dom(entry)

    def dominates(a, b):
        return tin[a] <= tin[b] and tout[b] <= tout[a]

    # --- Dominance Frontiers ---
    DF = defaultdict(set)
    for v in reachable:
        for u in cfg_preds[v]:
            if semi[v] == semi[u]:
                DF[semi[v]].add(v)
            else:
                w = semi[u]
                while semi[w] != semi[v]:
