                    w = semi[w]
                DF[semi[v]].add(w)

    # --- Instructions Analysis ---
    # Precompute defs and upward-exposed uses per name
    name_defs = defaultdict(set)
    name_uses = defaultdict(set)
    for v in reachable:
        instrs = blocks.get(v, [])
        has_def = False
        for op, name in instrs:
            if op in ("def", "upd"):
                has_def = True
                name_defs[name].add(v)
            elif op == "use":
                if not has_def:
                    name_uses[name].add(v)
        # upd counts as use even if preceded by def? 
        # Problem: "upd itself is a use, so it is exposed when nothing precedes it"
        # Actually, upd is (op, x) reads x then assigns. So it's a use at read time.
        # "upward exposed if no def or upd comes before it"
        # So we need to track per instruction.
    # Rethink upward-exposed uses carefully:
    name_upward_uses = defaultdict(set)
    for v in reachable:
        instrs = blocks.get(v, [])
        has_def_before = False
        for op, name in instrs:
            if op in ("def", "upd"):
                has_def_before = True
                name_defs[name].add(v)
            elif op == "use":
                if not has_def_before:
                    name_upward_uses[name].add(v)
            elif op == "upd":
                # upd is both use and def. It is a use at the start of the instruction.
                # "upd itself is a use, so it is exposed when nothing precedes it"
                # So if no def/upd before this upd, it's an upward-exposed use.
                if not has_def_before:
                    name_upward_uses[name].add(v)
                has_def_before = True # upd assigns

    # --- Liveness & P(x) Computation ---
    phi_sites = defaultdict(set)
    all_names = set(name_defs.keys()) | set(name_upward_uses.keys()) | set(params)

    for x in all_names:
        D_x = set(name_defs[x])
        if x in params:
            D_x.add(entry)

        # P(x) closure
        P_x = set(D_x)
        q_p = deque(P_x)
        while q_p:
            u = q_p.popleft()
            for v in DF[u]:
                if v not in P_x:
                    P_x.add(v)
                    q_p.append(v)

        # Liveness for x
        defs_x = name_defs[x]
        uses_x = name_upward_uses[x]
        live_x = set(uses_x)
        q_live = deque(uses_x)
        visited_live = set(uses_x)
        while q_live:
            w = q_live.popleft()
            for u in cfg_preds[w]:
                if u in reachable and u not in defs_x and u not in visited_live:
                    visited_live.add(u)
                    live_x.add(u)
                    q_live.append(u)

        # PHI placement
        for v in P_x:
            if v in live_x:
                phi_sites[v].add(x)

    # --- Format Output ---
    result = []
    for v in sorted(phi_sites.keys()):
        if phi_sites[v]:
            result.append((v, sorted(phi_sites[v])))
    return result

import sys
from collections import deque

def live_phi_sites(n, edges, entry, blocks, params):
    # Validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be pairs")
        if not all(isinstance(c, int) and not isinstance(c, bool) and 0 <= c < n for c in e):
            raise ValueError("edge components must be ints in 0..n-1")
    if not isinstance(blocks, dict):
        raise ValueError("blocks must be a dict")
    valid_ops = {"use", "def", "upd"}
    for k, v in blocks.items():
        if not isinstance(k, int) or isinstance(k, bool) or not (0 <= k < n):
            raise ValueError("blocks keys must be ints in 0..n-1")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values must be lists or tuples")
        for inst in v:
            if not isinstance(inst, (list, tuple)) or len(inst) != 2:
                raise ValueError("instructions must be pairs")
            op, name = inst
            if op not in valid_ops:
                raise ValueError("op must be one of use, def, upd")
            if not isinstance(name, str) or not name:
                raise ValueError("name must be non-empty str")
    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be a collection")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("params elements must be non-empty str")

    sys.setrecursionlimit(100000)

    # Reachability
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    reachable = set()
    q = deque([entry])
    reachable.add(entry)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in reachable:
                reachable.add(v)
                q.append(v)

    # Build succ/pred for reachable nodes
    succ = [[] for _ in range(n)]
    pred = [[] for _ in range(n)]
    for u, v in edges:
        if u in reachable and v in reachable:
            succ[u].append(v)
            pred[v].append(u)

    # Liveness data
    def_set = [set() for _ in range(n)]
    use_upward = [set() for _ in range(n)]
    for y in reachable:
        if y in blocks:
            seen = set()
            ups = set()
            for op, x in blocks[y]:
                if op in ("use", "upd"):
                    if x not in seen:
                        ups.add(x)
                if op in ("def", "upd"):
                    seen.add(x)
            use_upward[y] = ups
            def_set[y] = seen

    # Backward liveness analysis
    live_in = [set() for _ in range(n)]
    worklist = deque(reachable)
    while worklist:
        y = worklist.popleft()
        out = set()
        for z in succ[y]:
            out |= live_in[z]
        new_in = use_upward[y] | (out - def_set[y])
        if new_in != live_in[y]:
            live_in[y] = new_in
            for z in succ[y]:
                worklist.append(z)

    # Dominators (Lengauer-Tarjan)
    pre = [-1] * n
    tree_parent = [-1] * n
    dfs_order = []
    pre_count = 0
    stack = [entry]
    while stack:
        u = stack.pop()
        if pre[u] != -1:
            continue
        pre[u] = pre_count
        pre_count += 1
        dfs_order.append(u)
        for v in succ[u]:
            if pre[v] == -1:
                tree_parent[v] = u
                stack.append(v)

    semi = list(range(n))
    idom = list(range(n))
    ancestor = list(range(n))
    val = list(range(n))
    label = list(range(n))
    bucket = [[] for _ in range(n)]
    size = [1] * n

    def find(v):
        if val[v] == v:
            return v
        res = find(val[v])
        if semi[label[v]] < semi[label[val[v]]]:
            label[v] = label[val[v]]
        val[v] = res
        return res

    def link(u, v):
        ancestor[v] = u
        size[u] += size[v]
        val[v] = u

    for i in range(len(dfs_order) - 1, 0, -1):
        v = dfs_order[i]
        for w in pred[v]:
            if pre[w] != -1:  # w is reachable and visited
                u = find(w)
                if semi[u] < semi[v]:
                    semi[v] = semi[u]
        bucket[semi[v]].append(v)
        link(tree_parent[v], v)
        an = ancestor[tree_parent[v]]
        for u in bucket[an]:
            w = find(u)
            if semi[w] < semi[u]:
                semi[u] = semi[w]
        bucket[an].clear()
        if semi[v] != tree_parent[v]:
            idom[v] = semi[v]
        else:
            idom[v] = tree_parent[v]
        if idom[v] != semi[v]:
            link(v, idom[v])

    for i in range(1, len(dfs_order)):
        v = dfs_order[i]
        if idom[v] != semi[v]:
            idom[v] = idom[idom[v]]

    # Compute P(x) for each name
    # P(x) = set of all ancestors of D(x) in dominance tree
    name_to_P = {}
    all_names = set()
    for y in reachable:
        for x in def_set[y]:
            all_names.add(x)
    for p in params:
        all_names.add(p)
        if entry in reachable:
            # entry is in D(x) for params
            pass

    for x in all_names:
        D_x = set()
        for y in reachable:
            if x in def_set[y]:
                D_x.add(y)
        if x in params and entry in reachable:
            D_x.add(entry)

        P_x = set()
        for d in D_x:
            curr = d
            while curr != -1:
                P_x.add(curr)
                curr = idom[curr]
        name_to_P[x] = P_x

    # Collect results
    result = []
    for y in sorted(reachable):
        needed = []
        for x in live_in[y]:
            if x in name_to_P and y in name_to_P[x]:
                needed.append(x)
        if needed:
            result.append((y, sorted(needed)))

    return result

def format_sigfigs(s, sig, mode):
    if not isinstance(s, str):
        raise ValueError
    if len(s) > 100000:
        raise ValueError
    if not isinstance(sig, int) or isinstance(sig, bool) or not (1 <= sig <= 2000):
        raise ValueError
    valid_modes = {"nearest_even", "nearest_away", "nearest_zero", 
                   "toward_zero", "away_zero", "toward_neg", "toward_pos", "zero_five"}
    if mode not in valid_modes:
        raise ValueError

    # Parse sign
    if s[0] in '+-':
        sign = s[0]
        start = 1
    else:
        sign = ''
        start = 0

    # Parse exponent part
    e_idx = s.find('e', start)
    if e_idx == -1:
        e_idx = s.find('E', start)

    if e_idx != -1:
        if e_idx == start:
            raise ValueError
        exp_part = s[e_idx+1:]
        if len(exp_part) == 0:
            raise ValueError
        if exp_part[0] in '+-':
            if len(exp_part) < 2 or not exp_part[1:].isdigit():
                raise ValueError
            if len(exp_part) > 11:
                raise ValueError
            explicit_exp = int(exp_part)
        else:
            if not exp_part.isdigit():
                raise ValueError
            if len(exp_part) > 10:
                raise ValueError
            explicit_exp = int(exp_part)
    else:
        explicit_exp = 0

    # Parse mantissa part
    num_part = s[start:e_idx] if e_idx != -1 else s[start:]
    if '.' in num_part:
        if num_part.count('.') > 1:
            raise ValueError
        dot_idx = num_part.find('.')
        int_part = num_part[:dot_idx]
        frac_part = num_part[dot_idx+1:]
    else:
        int_part = num_part
        frac_part = ''

    if not int_part and not frac_part:
        raise ValueError

    digits = int_part + frac_part

    # Find first non-zero
    first_nonzero = -1
    for i, c in enumerate(digits):
        if c != '0':
            first_nonzero = i
            break

    # Zero handling
    if first_nonzero == -1:
        if sig == 1:
            res = "0"
        else:
            res = "0." + "0" * (sig - 1)
        return res + "e+00"

    # Calculate exponent E
    if int_part and any(c != '0' for c in int_part):
        E = len(int_part) - 1 + explicit_exp
    else:
        k = -1
        for i, c in enumerate(frac_part):
            if c != '0':
                k = i
                break
        if k == -1:
            E = 0
        else:
            E = -k - 1 + explicit_exp

    # Extract significant digits
    sig_digits = digits[first_nonzero:]

    if len(sig_digits) <= sig:
        # No rounding needed, just pad
        padded = sig_digits + "0" * (sig - len(sig_digits))
        res = padded[0] + "." + padded[1:] if sig > 1 else padded[0]
        return res + f"e{E:+03d}"

    kept = sig_digits[:sig]
    rd = int(sig_digits[sig])
    rest = sig_digits[sig+1:]

    rest_all_zero = True
    if rest:
        for c in rest:
            if c != '0':
                rest_all_zero = False
                break
    is_tie = (rd == 5) and rest_all_zero

    round_up = False
    if mode == "toward_zero":
        round_up = False
    elif mode == "away_zero":
        round_up = (rd > 0) or is_tie
    elif mode == "toward_neg":
        round_up = (sign == '-') and ((rd > 0) or is_tie)
    elif mode == "toward_pos":
        round_up = (sign != '-') and ((rd > 0) or is_tie)
    elif mode == "nearest_even":
        if rd > 5:
            round_up = True
        elif rd < 5:
            round_up = False
        else:
            round_up = (int(kept[-1]) % 2 != 0)
    elif mode == "nearest_away":
        if rd > 5:
            round_up = True
        elif rd < 5:
            round_up = False
        else:
            round_up = True
    elif mode == "nearest_zero":
        if rd > 5:
            round_up = True
        elif rd < 5:
            round_up = False
        else:
            round_up = False
    elif mode == "zero_five":
        round_up = (rd > 0) and (kept[-1] in ('0', '5'))

    if round_up:
        # Add 1 to kept
        lst = list(kept)
        i = len(lst) - 1
        while i >= 0:
            if lst[i] == '9':
                lst[i] = '0'
                i -= 1
            else:
                lst[i] = str(int(lst[i]) + 1)
                kept = "".join(lst)
                break
        else:
            # All 9s, carry out
            kept = "1" + "0" * len(kept)
            E += 1

    # Format output
    res = kept[0] + "." + kept[1:] if sig > 1 else kept[0]

    # Check exponent range
    if not (-999999999 <= E <= 999999999):
        raise ValueError

    exp_str = f"e{E:+03d}"
    if sign == '-' and res != "0" and not (sig == 1 and res == "0"):
        res = "-" + res

    return res + exp_str

def format_sigfigs(s, sig, mode):
    if not isinstance(s, str):
        raise ValueError
    if len(s) > 100000:
        raise ValueError
    if not isinstance(sig, int) or isinstance(sig, bool) or not (1 <= sig <= 2000):
        raise ValueError
    valid_modes = {"nearest_even", "nearest_away", "nearest_zero", 
                   "toward_zero", "away_zero", "toward_neg", "toward_pos", "zero_five"}
    if mode not in valid_modes:
        raise ValueError

    # Parse sign
    if s[0] in '+-':
        sign = s[0]
        start = 1
    else:
        sign = ''
        start = 0

    # Parse exponent part
    e_idx = s.find('e', start)
    if e_idx == -1:
        e_idx = s.find('E', start)

    if e_idx != -1:
        if e_idx == start:
            raise ValueError
        exp_part = s[e_idx+1:]
        if len(exp_part) == 0:
            raise ValueError
        if exp_part[0] in '+-':
            if len(exp_part) < 2 or not exp_part[1:].isdigit():
                raise ValueError
            if len(exp_part) > 11:
                raise ValueError
            explicit_exp = int(exp_part)
        else:
            if not exp_part.isdigit():
                raise ValueError
            if len(exp_part) > 10:
                raise ValueError
            explicit_exp = int(exp_part)
    else:
        explicit_exp = 0

    # Parse mantissa part
    num_part = s[start:e_idx] if e_idx != -1 else s[start:]
    if '.' in num_part:
        if num_part.count('.') > 1:
            raise ValueError
        dot_idx = num_part.find('.')
        int_part = num_part[:dot_idx]
        frac_part = num_part[dot_idx+1:]
    else:
        int_part = num_part
        frac_part = ''

    if not int_part and not frac_part:
        raise ValueError

    digits = int_part + frac_part

    # Find first non-zero
    first_nonzero = -1
    for i, c in enumerate(digits):
        if c != '0':
            first_nonzero = i
            break

    # Zero handling
    if first_nonzero == -1:
        if sig == 1:
            res = "0"
        else:
            res = "0." + "0" * (sig - 1)
        return res + "e+00"

    # Calculate exponent E
    # The position of the decimal point in 'digits' is after len(int_part) chars.
    # The first significant digit is at index first_nonzero.
    # Its power of 10 is (len(int_part) - 1) - first_nonzero.
    # Add explicit exponent.
    E = (len(int_part) - 1) - first_nonzero + explicit_exp

    # Extract significant digits
    sig_digits = digits[first_nonzero:]

    if len(sig_digits) <= sig:
        # No rounding needed, just pad
        padded = sig_digits + "0" * (sig - len(sig_digits))
        res = padded[0] + "." + padded[1:] if sig > 1 else padded[0]
        return res + f"e{E:+03d}"

    kept = sig_digits[:sig]
    rd = int(sig_digits[sig])
    rest = sig_digits[sig+1:]

    rest_all_zero = True
    if rest:
        for c in rest:
            if c != '0':
                rest_all_zero = False
                break
    is_tie = (rd == 5) and rest_all_zero

    # Determine if we need to round up (increase magnitude)
    # Note: "round up" here means incrementing the kept digits, which increases magnitude.
    # For negative numbers, "round up" in magnitude means making it more negative (floor).
    # But the logic of adding 1 to the integer representation of digits handles magnitude increase.
    # We just need to decide if we add 1 to the kept digits or not.

    round_up = False

    if mode == "toward_zero":
        round_up = False
    elif mode == "away_zero":
        # Goes to next larger magnitude.
        # If there is any dropped part (value > 0), increase magnitude.
        # Dropped part is non-zero if rd > 0 or rest is not all zeros.
        has_drop = (rd > 0) or (not rest_all_zero)
        if has_drop:
            round_up = True
    elif mode == "toward_neg":
        # Floor. For positive numbers, floor is truncate (no round up).
        # For negative numbers, floor is round down (away from zero).
        # Wait, floor(-1.2) = -2. Truncated is -1. So magnitude increases.
        # floor(1.2) = 1. Truncated is 1. Magnitude same.
        # So for positive, round_up = False.
        # For negative, round_up = True if drop > 0.
        if sign == '-':
            has_drop = (rd > 0) or (not rest_all_zero)
            if has_drop:
                round_up = True
    elif mode == "toward_pos":
        # Ceiling. For positive, ceil is round up if drop > 0.
        # For negative, ceil is truncate.
        if sign != '-':
            has_drop = (rd > 0) or (not rest_all_zero)
            if has_drop:
                round_up = True
    elif mode == "nearest_even":
        if rd > 5:
            round_up = True
        elif rd < 5:
            round_up = False
        else:
            # Tie case (rd == 5 and rest all zero)
            # Round to even last digit
            round_up = (int(kept[-1]) % 2 != 0)
    elif mode == "nearest_away":
        if rd > 5:
            round_up = True
        elif rd < 5:
            round_up = False
        else:
            # Tie case
            round_up = True
    elif mode == "nearest_zero":
        if rd > 5:
            round_up = True
        elif rd < 5:
            round_up = False
        else:
            # Tie case
            round_up = False
    elif mode == "zero_five":
        # Truncates, except if dropped and last kept is 0 or 5, go one unit away from zero.
        has_drop = (rd > 0) or (not rest_all_zero)
        if has_drop and kept[-1] in ('0', '5'):
            round_up = True

    if round_up:
        # Add 1 to kept
        lst = list(kept)
        i = len(lst) - 1
        while i >= 0:
            if lst[i] == '9':
                lst[i] = '0'
                i -= 1
            else:
                lst[i] = str(int(lst[i]) + 1)
                kept = "".join(lst)
                break
        else:
            # All 9s, carry out
            kept = "1" + "0" * len(kept)
            E += 1

    # Format output
    res = kept[0] + "." + kept[1:] if sig > 1 else kept[0]

    # Check exponent range
    if not (-999999999 <= E <= 999999999):
        raise ValueError

    exp_str = f"e{E:+03d}"
    if sign == '-' and res != "0" and not (sig == 1 and res == "0"):
        res = "-" + res

    return res + exp_str

def format_sigfigs(s: str, sig: int, mode: str) -> str:
    # Validate inputs
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if isinstance(sig, bool) or not isinstance(sig, int):
        raise ValueError("sig must be an int")
    if not (1 <= sig <= 2000):
        raise ValueError("sig must be in 1..2000")
    valid_modes = {
        "nearest_even", "nearest_away", "nearest_zero",
        "toward_zero", "away_zero", "toward_neg", "toward_pos", "zero_five"
    }
    if mode not in valid_modes:
        raise ValueError("Invalid mode")
    if len(s) > 100000:
        raise ValueError("s is too long")

    # Parse sign
    sign = '+'
    if s[0] in '+-':
        sign = s[0]
        s = s[1:]
    elif s[0] == '0' and len(s) > 1 and s[1] == '.':
        pass # handled below
    elif s[0] == '.':
        pass # handled below

    # Split exponent
    e_idx = -1
    for i, c in enumerate(s):
        if c in 'eE':
            e_idx = i
            break

    if e_idx == -1:
        mantissa_str = s
        exp_val = 0
    else:
        mantissa_str = s[:e_idx]
        exp_part = s[e_idx+1:]
        if exp_part:
            exp_val = int(exp_part)
        else:
            raise ValueError("Invalid exponent part")

    # Parse mantissa
    dot_idx = mantissa_str.find('.')
    if dot_idx == -1:
        digits = mantissa_str
        dot_pos = len(digits)
    else:
        digits = mantissa_str[:dot_idx] + mantissa_str[dot_idx+1:]
        dot_pos = dot_idx

    # Validate digits
    if not digits or not all(c in '0123456789' for c in digits):
        raise ValueError("Invalid mantissa")
    if len(digits) == 0:
        raise ValueError("No digits in mantissa")

    # Compute exponent of the integer formed by digits
    # value = int(digits) * 10^(exp_val - (len(digits) - dot_pos))
    E = exp_val - (len(digits) - dot_pos)

    # Convert to integer and strip leading zeros
    N = int(digits)
    if N == 0:
        # Zero result
        exp_out = 0
        if sig > 1:
            return f"0.{sig-1*'0'}e+{exp_out:02d}"
        else:
            return f"0e+{exp_out:02d}"

    N_str = str(N)
    L = len(N_str)
    shift = L - sig

    if shift <= 0:
        # No rounding needed
        rounded_N = N
    else:
        divisor = 10 ** shift
        quotient, remainder = divmod(N, divisor)
        half = 5 * 10**(shift - 1)

        # Determine rounding action: -1 (down), 0 (no change), 1 (up)
        if remainder == 0:
            action = 0
        elif remainder < half:
            action = -1
        elif remainder > half:
            action = 1
        else: # Tie
            last_digit = quotient % 10
            if mode == "nearest_even":
                action = 0 if last_digit % 2 == 0 else 1
            elif mode == "nearest_away":
                action = 1
            elif mode == "nearest_zero":
                action = 0
            elif mode == "zero_five":
                # zero_five: truncates, but if dropped > 0 and last digit is 0 or 5, round away
                action = 1 if last_digit in (0, 5) else 0
            else:
                action = 0 # Should not reach here

        # Apply mode specific adjustments
        if mode == "toward_zero":
            action = 0 if remainder == 0 else -1
        elif mode == "away_zero":
            action = 0 if remainder == 0 else 1
        elif mode == "toward_neg":
            # Floor: toward -inf
            if sign == '+':
                action = 0 if remainder == 0 else -1
            else:
                action = 0 if remainder == 0 else 1
        elif mode == "toward_pos":
            # Ceiling: toward +inf
            if sign == '+':
                action = 0 if remainder == 0 else 1
            else:
                action = 0 if remainder == 0 else -1
        elif mode == "zero_five":
            # Already handled in tie, but also applies to non-ties
            if action == 0 and remainder > 0:
                last_digit = quotient % 10
                if last_digit in (0, 5):
                    action = 1

        if action == 1:
            rounded_N = (quotient + 1) * divisor
        else:
            rounded_N = quotient * divisor

    # Format result
    rounded_N_str = str(rounded_N)
    new_L = len(rounded_N_str)

    # Exponent of the first significant digit
    P_new = E + new_L - 1

    # Range check
    if P_new < -999999999 or P_new > 999999999:
        raise ValueError("Exponent out of range")

    # Extract sig digits
    mantissa_digits = rounded_N_str[:sig]
    if len(mantissa_digits) < sig:
        mantissa_digits += '0' * (sig - len(mantissa_digits))
