def snap_to_step(x: str, step: str, mode: str) -> str:
    if not isinstance(x, str) or not isinstance(step, str) or not isinstance(mode, str):
        raise ValueError("x and step must be strings, mode must be a string")
    if len(x) > 4000 or len(step) > 4000:
        raise ValueError("Input string length exceeds 4000")

    valid_modes = {"floor", "ceil", "outward", "inward", "tie_even", "tie_odd", "tie_away", "tie_zero"}
    if mode not in valid_modes:
        raise ValueError("Invalid mode")

    def parse_decimal(s: str):
        sign = 1
        if s[0] == '+':
            s = s[1:]
        elif s[0] == '-':
            sign = -1
            s = s[1:]
        if not s:
            raise ValueError("Empty string after sign")

        exp_val = 0
        if 'e' in s or 'E' in s:
            idx = s.find('e' if 'e' in s else 'E')
            exp_str = s[idx+1:]
            s = s[:idx]
            if not exp_str or not exp_str.lstrip('+-').isdigit():
                raise ValueError("Invalid exponent")
            if exp_str[0] in '+-':
                exp_str = exp_str[1:]
            exp_val = int(exp_str)

        if '.' in s:
            parts = s.split('.')
            if len(parts) != 2 or not all(p.isdigit() for p in parts) or (not parts[0] and not parts[1]):
                raise ValueError("Invalid decimal format")
            int_part, frac_part = parts
            digits = (int_part or "0") + frac_part
            decimal_shift = len(frac_part)
        else:
            if not s.isdigit():
                raise ValueError("Invalid decimal format")
            digits = s
            decimal_shift = 0

        digits = digits.lstrip('0')
        if not digits:
            digits = "0"

        return sign, int(digits), exp_val - decimal_shift

    sx, mx, ex = parse_decimal(x)
    ss, ms, es = parse_decimal(step)

    if ss == -1 or ms == 0:
        raise ValueError("Step must be greater than zero")

    diff_exp = ex - es
    if diff_exp >= 0:
        num = mx * (10 ** diff_exp)
        den = ms
    else:
        num = mx
        den = ms * (10 ** (-diff_exp))

    k_floor = num // den
    rem = num % den
    k_ceil = k_floor + 1

    if mode == "floor":
        k = k_floor
    elif mode == "ceil":
        k = k_ceil
    elif mode == "outward":
        k = k_floor if k_floor < 0 else k_ceil
    elif mode == "inward":
        k = k_ceil if k_floor < 0 else k_floor
    elif mode == "tie_even":
        if rem * 2 < den:
            k = k_floor
        elif rem * 2 > den:
            k = k_ceil
        else:
            k = k_floor if k_floor % 2 == 0 else k_ceil
    elif mode == "tie_odd":
        if rem * 2 < den:
            k = k_floor
        elif rem * 2 > den:
            k = k_ceil
        else:
            k = k_floor if k_floor % 2 != 0 else k_ceil
    elif mode == "tie_away":
        if rem * 2 < den:
            k = k_floor
        elif rem * 2 > den:
            k = k_ceil
        else:
            k = k_floor if k_floor < 0 else k_ceil
    elif mode == "tie_zero":
        if rem * 2 < den:
            k = k_floor
        elif rem * 2 > den:
            k = k_ceil
        else:
            k = k_ceil if k_floor < 0 else k_floor

