    # step = ms * 10^es
    # Normalize step to m * 10^e where m % 10 != 0
    m = ms
    e = es
    while m % 10 == 0:
        m //= 10
        e += 1

    d = max(0, -e)

    res_int = abs(k) * m
    s_res = str(res_int)

    if k == 0:
        sign = ""
    else:
        sign = "-" if k < 0 else ""

    if d == 0:
        int_part = s_res
        frac_part = ""
