        if len(s_res) <= d:
            int_part = "0"
            frac_part = "0" * (d - len(s_res)) + s_res
        else:
            int_part = s_res[:-d]
            frac_part = s_res[-d:]

    if len(int_part) + d > 3000:
        raise ValueError("Output exceeds 3000 digits")

    return f"{sign}{int_part}.{frac_part}" if frac_part else f"{sign}{int_part}"

