            # Tie: farther from zero
            if abs(k_floor) > abs(k_ceil):
                k = k_floor
            else:
                k = k_ceil
    elif mode == "tie_zero":
        if rem * 2 < denominator:
            k = k_floor
        elif rem * 2 > denominator:
            k = k_ceil
        else:
            # Tie: nearer to zero
            if abs(k_floor) < abs(k_ceil):
                k = k_floor
            else:
                k = k_ceil

    # Format result: k * step
    # step = ms * 10^es
    # Normalize step to m * 10^e where m % 10 != 0
    m = ms
    e = es
    while m % 10 == 0:
        m //= 10
        e += 1

    d = max(0, -e)

    # Result value is k * step = k * m * 10^e
    # We need to represent this as integer part and fractional part with d digits.
    # Value = (k * m) * 10^e

    res_int_magnitude = abs(k) * m
    s_res = str(res_int_magnitude)

    if k == 0:
        sign = ""
    else:
        sign = "-" if k < 0 else ""

    if d == 0:
        int_part = s_res
        frac_part = ""
    else:
        if len(s_res) <= d:
            int_part = "0"
            frac_part = "0" * (d - len(s_res)) + s_res
        else:
            int_part = s_res[:-d]
            frac_part = s_res[-d:]

    # Check size limit
    if len(int_part) + d > 3000:
        raise ValueError("Output exceeds 3000 digits")

    if frac_part:
        return f"{sign}{int_part}.{frac_part}"
    else:
        return f"{sign}{int_part}"

def snap_to_step(x: str, step: str, mode: str) -> str:
    if not isinstance(x, str) or not isinstance(step, str) or not isinstance(mode, str):
        raise ValueError("x and step must be strings, mode must be a string")
    if len(x) > 4000 or len(step) > 4000:
        raise ValueError("Input string length exceeds 4000")

    valid_modes = {"floor", "ceil", "outward", "inward", "tie_even", "tie_odd", "tie_away", "tie_zero"}
    if mode not in valid_modes:
        raise ValueError("Invalid mode")

    def parse_decimal(s: str):
        if not s:
            raise ValueError("Empty string")

        sign = 1
        idx = 0
        if s[0] == '+':
            idx = 1
        elif s[0] == '-':
            sign = -1
            idx = 1

        if idx == len(s):
            raise ValueError("Empty string after sign")

        e_idx = -1
        for i in range(idx, len(s)):
            if s[i] in 'eE':
                e_idx = i
                break

        if e_idx != -1:
            exp_str = s[e_idx+1:]
            if not exp_str:
                raise ValueError("Missing exponent value")

            e_sign = 1
            e_start = 0
            if exp_str[0] == '+':
                e_start = 1
            elif exp_str[0] == '-':
                e_sign = -1
                e_start = 1

            if e_start == len(exp_str):
                raise ValueError("Missing exponent digits")

            if not exp_str[e_start:].isdigit():
                raise ValueError("Invalid exponent digits")

            exp_val = int(exp_str[e_start:]) * e_sign
            mantissa = s[idx:e_idx]
        else:
            mantissa = s[idx:]
            exp_val = 0

        if '.' in mantissa:
            parts = mantissa.split('.')
            if len(parts) != 2:
                raise ValueError("Multiple decimal points")
            int_part, frac_part = parts
            if not int_part and not frac_part:
                raise ValueError("No digits")
            if not int_part.isdigit() or not frac_part.isdigit():
                raise ValueError("Non-digit characters in mantissa")

            digits_str = int_part + frac_part
            digits_str = digits_str.lstrip('0')
            if not digits_str:
                digits_str = "0"
            decimal_shift = len(frac_part)
        else:
            if not mantissa.isdigit():
                raise ValueError("Non-digit characters in mantissa")
            digits_str = mantissa.lstrip('0')
            if not digits_str:
                digits_str = "0"
            decimal_shift = 0

        coeff = int(digits_str)
        exp = exp_val - decimal_shift
        return sign, coeff, exp

    sx, cx, ex = parse_decimal(x)
    ss, cs, es = parse_decimal(step)

    if ss == -1 or cs == 0:
        raise ValueError("Step must be greater than zero")

    diff = ex - es

    # Safety check for extremely large exponents to avoid memory/time issues
    if diff > 5000:
        raise ValueError("Output would exceed 3000 digits")
    if diff < -5000:
        diff = -5000  # Effectively makes k = 0

    if diff >= 0:
        numerator = sx * cx * (10 ** diff)
        denominator = cs
    else:
        numerator = sx * cx
        denominator = cs * (10 ** (-diff))

    k_floor = numerator // denominator
    rem = numerator % denominator
    k_ceil = k_floor + 1

    if rem == 0:
        k = k_floor
    else:
        if mode == "floor":
            k = k_floor
        elif mode == "ceil":
            k = k_ceil
        elif mode == "outward":
            k = k_floor if abs(k_floor) > abs(k_ceil) else k_ceil
        elif mode == "inward":
            k = k_floor if abs(k_floor) < abs(k_ceil) else k_ceil
        elif mode == "tie_even":
            if rem * 2 < denominator:
                k = k_floor
            elif rem * 2 > denominator:
                k = k_ceil
            else:
                k = k_floor if k_floor % 2 == 0 else k_ceil
        elif mode == "tie_odd":
            if rem * 2 < denominator:
                k = k_floor
            elif rem * 2 > denominator:
                k = k_ceil
            else:
                k = k_floor if k_floor % 2 != 0 else k_ceil
        elif mode == "tie_away":
            if rem * 2 < denominator:
                k = k_floor
            elif rem * 2 > denominator:
                k = k_ceil
            else:
                k = k_floor if abs(k_floor) > abs(k_ceil) else k_ceil
        elif mode == "tie_zero":
            if rem * 2 < denominator:
                k = k_floor
            elif rem * 2 > denominator:
                k = k_ceil
            else:
                k = k_floor if abs(k_floor) < abs(k_ceil) else k_ceil

    # Normalize step to m * 10^e where m % 10 != 0
    m = cs
    e = es
    while m % 10 == 0:
        m //= 10
        e += 1

    d = max(0, -e)

    # Calculate result magnitude
    res_int_magnitude = abs(k) * m
    s_res = str(res_int_magnitude)

    if k == 0:
        sign = ""
    else:
        sign = "-" if k < 0 else ""

    if d == 0:
        int_part = s_res
        frac_part = ""
    else:
        if len(s_res) <= d:
            int_part = "0"
            frac_part = "0" * (d - len(s_res)) + s_res
        else:
            int_part = s_res[:-d]
            frac_part = s_res[-d:]

    if len(int_part) + d > 3000:
        raise ValueError("Output exceeds 3000 digits")

    if frac_part:
        return f"{sign}{int_part}.{frac_part}"
    else:
        return f"{sign}{int_part}"

def snap_to_step(x: str, step: str, mode: str) -> str:
    valid_modes = {"floor", "ceil", "outward", "inward", "tie_even", "tie_odd", "tie_away", "tie_zero"}
    if mode not in valid_modes:
        raise ValueError("Invalid mode")
    if not isinstance(x, str) or not isinstance(step, str):
        raise ValueError("x and step must be strings")
    if len(x) > 4000 or len(step) > 4000:
        raise ValueError("Input string too long")

    def parse(s):
        if not s or s[0] in '+-':
            if not s or (len(s) == 1 and s[0] in '+-'):
                raise ValueError("No digits in sign part")
        sign = 1
        if s[0] == '-':
            sign = -1
            s = s[1:]
        elif s[0] == '+':
            s = s[1:]

        if 'e' in s.lower():
            base, exp_str = s.split('e', 1)
            exp_str = exp_str.strip()
            if not exp_str:
                raise ValueError("Missing exponent")
            exp_sign = 1
            if exp_str[0] == '-':
                exp_sign = -1
                exp_str = exp_str[1:]
            elif exp_str[0] == '+':
                exp_str = exp_str[1:]
            if not exp_str.isdigit():
                raise ValueError("Invalid exponent")
            exp_val = int(exp_str) * exp_sign
        else:
            base = s
            exp_val = 0

        if '.' in base:
            int_part, frac_part = base.split('.')
        else:
            int_part = base
            frac_part = ""

        if not int_part and not frac_part:
            raise ValueError("No digits")

        coeff_str = int_part + frac_part
        if not coeff_str.isdigit():
            raise ValueError("Invalid digits")

        coeff = int(coeff_str)
        frac_len = len(frac_part)
        return sign, coeff, exp_val - frac_len

    sx, cx, ex = parse(x)
    if cx == 0:
        raise ValueError("step must be greater than zero")
    ss, cs, es = parse(step)
    if ss != 1:
        raise ValueError("step must be positive")
    if cs == 0:
        raise ValueError("step must be greater than zero")

    diff = ex - es
    if diff >= 0:
        num = sx * cx
        den = cs
        Q, R = divmod(num, den)
        # k_floor = Q * 10^diff
        # Check size early
        digits_Q = len(str(Q)) if Q != 0 else 1
        if digits_Q + diff > 3000:
            raise ValueError("Output too large")
        k_floor = Q * (10 ** diff)
        k_ceil = k_floor + 1
        # frac = R / den
        # Compare 2*R vs den
        cmp = 2 * R - den
    else:
        shift = -diff
        # Check size: result will be k * step. k will be 0 or 1 roughly.
        # But we compute Q, R = divmod(num, den * 10^shift)
        # den_shifted = den * 10^shift. shift <= 4000, so fine.
        den_shifted = den * (10 ** shift)
        Q, R = divmod(num, den_shifted)
        k_floor = Q
        k_ceil = Q + 1
        cmp = 2 * R - den_shifted

    if cmp < 0:
        k = k_floor
    elif cmp > 0:
        k = k_ceil
    else:  # tie
        if mode == "tie_even":
            k = k_floor if k_floor % 2 == 0 else k_ceil
        elif mode == "tie_odd":
            k = k_floor if k_floor % 2 != 0 else k_ceil
        elif mode == "tie_away":
            k = k_floor if abs(k_floor) > abs(k_ceil) else k_ceil
        elif mode == "tie_zero":
            k = k_floor if abs(k_floor) < abs(k_ceil) else k_ceil
        elif mode == "floor":
            k = k_floor
        elif mode == "ceil":
            k = k_ceil
        elif mode == "outward":
            k = k_floor if abs(k_floor) > abs(k_ceil) else k_ceil
        elif mode == "inward":
            k = k_floor if abs(k_floor) < abs(k_ceil) else k_ceil

    # Format result = k * step = k * cs * 10^es
    coeff = k * cs
    es_neg = es < 0
    d = -es if es_neg else 0

    # Check size
    len_coeff = len(str(coeff)) if coeff != 0 else 1
    total_len = len_coeff + d
    if total_len > 3000:
        raise ValueError("Output too large")

    # Build string
    coeff_str = str(coeff)
    if d == 0:
        res = coeff_str
    else:
        # Pad with leading zeros if necessary to have d fractional digits
        # Actually, we want exactly d digits after decimal point.
        # result = coeff * 10^es. If es < 0, result = coeff / 10^d.
        # We want to represent it as integer_part.fractional_part with d fractional digits.
        # So we compute coeff * 10^d? No.
        # Example: coeff=10, es=-2, d=2. result=0.10.
        # We want "0.10".
        # Formula: pad coeff_str to length d with leading zeros? No.
        # result_str = coeff_str.zfill(d+1) ? 
        # Let's just construct it properly.
        # val = coeff * 10^es.
        # If es >= 0: val = coeff_str + '0'*es
        # If es < 0: val = coeff / 10^(-es). 
        # We need d = -es fractional digits.
        # So we take coeff_str, pad with leading zeros to length d, then insert '.'
        # Wait, if coeff=10, d=2. pad to length 2 -> "10". insert '.' at len-2=0 -> ".10"? No.
        # Correct approach: 
        # s = coeff_str
        # if len(s) <= d:
        #     s = '0' * (d - len(s) + 1) + s  # Ensure at least one digit before dot
        #     res = s[: -d] + '.' + s[-d:]
        # else:
        #     res = s[: -d] + '.' + s[-d:]
        # But this gives "0.10" for coeff=10, d=2. s="10". len=2 <= 2.
        # pad: '0'*(2-2+1) + '10' = "010". s[:0]='', s[-2:]='10'. res=".10". Missing leading zero.
        # Fix:
        s = coeff_str
        if len(s) <= d:
            s = '0' * (d - len(s) + 1) + s
        res = s[:-d] + '.' + s[-d:]

    # Remove trailing zeros? No, "exactly d fractional digits".
    # Remove leading zeros in integer part? "0" if zero.
    if '.' in res:
        int_part, frac_part = res.split('.')
        if int_part == '' or int_part == '-':
            res = '0' + res
        elif int_part.startswith('-') and int_part[1:] == '':
            res = '-0.' + frac_part
        elif int_part.startswith('-'):
            if int_part[1:].lstrip('0') == '':
                res = '-0.' + frac_part
            else:
                res = int_part + '.' + frac_part
        else:
            if int_part.lstrip('0') == '':
                res = '0.' + frac_part
            else:
                res = int_part + '.' + frac_part
    else:
        if res.startswith('-') and res[1:].lstrip('0') == '':
            res = '0'
        elif res.lstrip('0') == '':
            res = '0'

    if res == '-0' or res == '-0.0' * (d>0):
        res = '0' if d == 0 else '0.' + '0'*d

    return res
